BEGIN;
WITH p AS (SELECT value AS r FROM jsonb_array_elements($ap$[{"id": "b2717fcc-4425-45cf-a20f-5f037f1bf9c5", "term": "Extract Groove", "definition": "Extract Groove is a command in Ableton Live that creates a new, reusable groove from an existing audio or MIDI clip. It captures the timing and volume information of the clip's playing portion and saves it as a groove (.agr) file in the Groove Pool. The groove can then be applied to other clips.", "plain_english": "Extract Groove copies the feel of one clip. It reads how the notes sit in time and how loud they are. It saves that as a groove file. You can then put that same feel on other clips.", "purpose_function": "It lets a technician reuse the natural timing and dynamics of one performance or loop as a template for others, spreading a consistent feel.", "practical_application": "An engineer right-clicks a well-played drum loop, chooses Extract Groove, and applies the captured feel to stiff MIDI parts.", "category": "Grooves", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Groove Pool", "Commit Groove", "Ableton Live", "Session Clip", "Auto-Warp"], "common_mistakes": ["Expecting it to change the source clip; it only creates a new groove file", "Forgetting the extracted groove must be applied to other clips to have an effect", "Confusing extracting a groove with committing one, which work in opposite directions"], "scenario_contexts": ["Capturing swing from a favorite loop", "Reusing a drummer's feel on programmed parts", "Building a groove library from reference tracks"], "formula_symbolic": "", "formula_words": ""}, {"id": "01503f90-5c08-4afb-9e59-ffa6cf0cc245", "term": "Follow Action", "definition": "A Follow Action in Ableton Live is a rule that tells a clip what to do when it finishes playing, such as play the next clip, stop, repeat, or jump to another clip in the track. Actions can be set with a probability and a time, allowing automatic or randomized clip sequencing within a track.", "plain_english": "A Follow Action decides what happens after a clip plays. It can start the next clip, stop, repeat, or pick one at random. You set the chance and the timing. Live then moves through clips on its own.", "purpose_function": "It exists to automate clip playback in the Session View, letting clips chain, loop, or vary without the performer launching each one by hand.", "practical_application": "A performer sets follow actions so a group of clips cycles or randomly picks the next loop, building variation hands-free during a set.", "category": "Session View", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Clip Slot", "Session Clip", "Ableton Live", "Live Clip", "Auto-Warp"], "common_mistakes": ["Forgetting that follow actions act per track between clips, not across whole scenes", "Setting a very short action time and cutting clips off early", "Using random actions and expecting a fixed, repeatable order"], "scenario_contexts": ["Auto-cycling loops during a live set", "Randomizing fills for variation", "Chaining intro, main, and fill clips automatically"], "formula_symbolic": "", "formula_words": ""}, {"id": "1e47548e-c292-4323-ac56-0d6993fb41dc", "term": "Glue Compressor", "definition": "The Glue Compressor is a bus (master) compressor in Ableton Live modeled on a classic 1980s British analog VCA bus compressor of the SSL-console type. It offers fixed ratios (2:1, 4:1, 10:1), attack and release times with an auto-release option, makeup gain, a sidechain filter, dry/wet mix, and a soft-clipping output stage. It was developed with Cytomic and shares its engine with Cytomic's The Glue.", "plain_english": "The Glue Compressor squeezes a whole mix or group so it sounds like one solid sound. It copies a famous 1980s studio bus compressor. It has simple ratio, attack, and release controls. Engineers use it to glue tracks together.", "purpose_function": "It exists to gently compress a bus or full mix, tightening dynamics and making separate tracks feel cohesive, the classic glue effect of an analog bus compressor.", "practical_application": "A mix engineer places the Glue Compressor on the master or drum bus and sets a slow attack and a couple of dB of gain reduction to bind the mix.", "category": "Audio Effect", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Drum Buss", "Saturator", "Ableton Live", "Erosion", "Corpus"], "common_mistakes": ["Over-compressing the bus and squashing the mix's punch", "Using a fast attack that kills transients on the master", "Confusing it with a per-channel compressor; it is voiced for bus and glue duty"], "scenario_contexts": ["Gluing a full mix on the master bus", "Tightening a drum group", "Adding subtle parallel compression with the dry/wet control"], "formula_symbolic": "", "formula_words": ""}, {"id": "97c7256e-d964-4436-9ce9-d1d3dadb3e84", "term": "Grain Delay", "definition": "Grain Delay is an audio effect in Ableton Live that applies granular processing to a delay. It chops the incoming signal into tiny grains and plays each back after a delay, while allowing pitch-shifting of the grains, random timing spray, adjustable grain frequency (size), and feedback. This produces pitch-shifted echoes and granular clouds.", "plain_english": "Grain Delay is a delay that cuts sound into tiny pieces called grains. It can change the pitch of each echo. It can scatter the timing for a cloud-like effect. Feedback lets the grains repeat and build up.", "purpose_function": "It exists to create pitched, textured, and experimental delays that go beyond a normal echo, useful for sound design and movement.", "practical_application": "A producer adds Grain Delay to a vocal or synth, sets the pitch up an octave, and uses feedback to spin the repeats into a shimmering cloud.", "category": "Audio Effect", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Erosion", "Corpus", "Ableton Live", "Spectral Time", "Redux"], "common_mistakes": ["Expecting a clean echo; Grain Delay is a granular, pitch-shifting effect", "Running feedback and pitch high and losing control of the sound", "Confusing grain frequency (grain size) with delay time"], "scenario_contexts": ["Pitch-shifting echoes on a synth line", "Building granular clouds from a vocal", "Adding shimmering repeats for texture"], "formula_symbolic": "", "formula_words": ""}, {"id": "eb7cbef0-c5e4-41cd-8354-9e8d2ff3849b", "term": "Groove Pool", "definition": "The Groove Pool is the workspace in Ableton Live where loaded grooves are managed. It lists every groove in use and lets the user adjust groove parameters, such as timing, quantize, and random, in real time, affecting all clips assigned to that groove. It is opened from the browser or a keyboard shortcut.", "plain_english": "The Groove Pool is where Live keeps your grooves. Grooves add swing and feel to clips. In the pool you tweak how strong the feel is. Any clip using that groove updates as you change it.", "purpose_function": "It centralizes groove control, so one edit can reshape the feel of every clip using that groove, making timing changes fast and consistent.", "practical_application": "An engineer opens the Groove Pool, raises the Timing amount on a swing groove, and hears every assigned clip loosen up together.", "category": "Grooves", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Commit Groove", "Extract Groove", "Ableton Live", "Session Clip", "Auto-Warp"], "common_mistakes": ["Editing a groove in the pool and forgetting it changes every clip using it", "Confusing the Groove Pool (the control area) with individual groove files", "Leaving grooves loaded but unassigned and hearing no change"], "scenario_contexts": ["Dialing in swing across a whole project", "Comparing several grooves on the same clip", "Adjusting groove amount live during arrangement"], "formula_symbolic": "", "formula_words": ""}, {"id": "b32812c4-5b30-4b00-b968-9ef8884718e5", "term": "Hybrid Reverb", "definition": "Hybrid Reverb is an audio effect in Ableton Live that combines a convolution reverb, which uses impulse responses of real or sampled spaces, with an algorithmic reverb that models spaces mathematically. The two engines can run alone, in series (convolution first), or in parallel, balanced by a Blend control, followed by an optional EQ.", "plain_english": "Hybrid Reverb mixes two kinds of reverb in one effect. One kind uses recordings of real spaces. The other builds spaces with math. You can blend them or use one alone. This gives both realistic and creative echoes.", "purpose_function": "It exists to combine the realism of convolution reverb with the flexibility of algorithmic reverb, and to allow custom impulse responses for sound design.", "practical_application": "An engineer loads a real room impulse in Hybrid Reverb's convolution side, blends in an algorithmic tail, and shapes the result with its EQ.", "category": "Audio Effect", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Corpus", "Grain Delay", "Ableton Live", "Erosion", "Spectral Resonator"], "common_mistakes": ["Assuming it only makes realistic rooms; the algorithmic side and custom impulses allow creative spaces", "Loading heavy impulse responses and raising CPU load", "Ignoring the Blend control and hearing only one engine"], "scenario_contexts": ["Placing vocals in a realistic sampled room", "Designing an unusual space from a custom impulse", "Blending a natural and a synthetic tail on a mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "62a1884e-0050-4f25-911f-b83f1102d2c6", "term": "Impulse", "definition": "Impulse is a drum sampler instrument in Ableton Live with eight sample slots. Each slot plays a sample and offers processing such as time-stretch, filter, saturation, envelope, pan, and volume, plus velocity and random modulation. It is used to build and play drum kits from samples.", "plain_english": "Impulse is a drum instrument in Ableton Live. It has eight pads, and each holds one sample. You can stretch, filter, and shape each sound. It is made for building and playing drum kits.", "purpose_function": "It exists to load, shape, and trigger up to eight drum samples in one device, making it a compact kit builder for beats.", "practical_application": "A producer drags kick, snare, and hat samples into Impulse's eight slots, tunes and filters each, then plays a beat from a MIDI clip or pads.", "category": "Instrument", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Drum Buss", "Simpler", "Drift", "Ableton Live", "Collision"], "common_mistakes": ["Trying to load more than eight sounds into one Impulse", "Confusing Impulse (an eight-slot drum sampler) with Simpler (a single-sample instrument)", "Ignoring the per-slot filter and saturation that shape each drum"], "scenario_contexts": ["Building an eight-piece drum kit from samples", "Adding stretch and saturation to individual hits", "Playing a beat live from a controller into Impulse"], "formula_symbolic": "", "formula_words": ""}, {"id": "06e75b87-bf06-43fa-b977-8a8d30e5f45b", "term": "Live API", "definition": "The Live API is Ableton Live's application programming interface, used mainly through Max for Live, that lets devices observe and control Live's objects and parameters. Its structure is the Live Object Model (LOM), a hierarchy of tracks, clips, devices, and the application. Max objects such as live.path, live.object, and live.observer read, write, and monitor these objects.", "plain_english": "The Live API is a way for code to talk to Ableton Live. It lets custom tools read and change Live's tracks, clips, and controls. Programmers reach it through Max for Live. The map of what they can touch is called the Live Object Model.", "purpose_function": "It exists so developers can build Max for Live devices and control tools that watch Live's state and change it, extending what Live can do.", "practical_application": "A developer uses live.path and live.object in a Max for Live device to read a track's volume and drive custom behavior inside Live.", "category": "Programming", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Max for Live Device", "Ableton Live", "Push Standalone", "Core Library", "Ableton Cloud"], "common_mistakes": ["Assuming the Live API is a normal audio plugin; it is accessed through Max for Live", "Confusing the Live Object Model paths with computer file paths", "Expecting every Live feature to be controllable; only exposed objects are available"], "scenario_contexts": ["Building a custom Max for Live control device", "Reading and reacting to clip launches", "Automating parameters beyond Live's built-in options"], "formula_symbolic": "", "formula_words": ""}, {"id": "caecf378-3f77-466d-93ce-35d329c4408d", "term": "Live Clip", "definition": "In Ableton Live, a Live Clip is a single clip saved to disk as a reusable file (.alc). It stores the clip's audio or MIDI content and its Clip View settings, and it can also save the source track's instrument and effects chain, so the clip can be dragged into any Set from the browser. \"Live Clip\" is a term of Ableton AG's Live software.", "plain_english": "A Live Clip is one saved clip you can reuse. Live keeps its notes or audio plus its settings in a file. It can even store the track's instrument and effects with it. You drag it from the browser into any project to use again.", "purpose_function": "It lets a producer store a single musical idea, together with its sound, as a portable building block that can be recalled across different projects.", "practical_application": "A technician drags a finished loop from a track to the User Library to save it as a Live Clip, then reuses it in later Sets.", "category": "Clips & Files", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Session Clip", "Clip Slot", "User Library", "Live Pack", "Sample Offset Envelope"], "common_mistakes": ["Assuming a Live Clip embeds the actual audio; it references the sample on disk, so moving the sample can break it unless it is saved with the Set.", "confusing a Live Clip (a saved .alc file) with a Session clip (a clip currently sitting in a Session slot)", "expecting the instrument and effects to always load, when they are only included if the clip is saved from its track"], "scenario_contexts": ["Saving a drum groove as a Live Clip to reuse across several songs", "sharing a MIDI melody together with its synth patch as one .alc file", "building a personal library of loops in the User Library"], "formula_symbolic": "", "formula_words": ""}, {"id": "3e0a6a9f-7499-492e-b1fd-c65d08f0e8a6", "term": "Live Pack", "definition": "A Live Pack is Ableton's installable content bundle, distributed as a compressed .alp file, containing items such as samples, presets, instrument and effect Racks, Live Clips, grooves and lessons. Installing a Pack adds its content to Live's browser and User Library. \"Live Pack\" is a term of Ableton AG.", "plain_english": "A Live Pack is a bundle of ready-made sounds and presets. It arrives as one file that ends in .alp. When you install it, its samples and presets show up in Live's browser. Ableton and other makers offer Packs.", "purpose_function": "It packages related content into one installable file so users can add whole sound libraries and instruments to Live in a single step.", "practical_application": "A technician double-clicks an .alp file, or uses the Install Pack command, to add a sample library and then browses its presets.", "category": "Library & Content", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Core Library", "User Library", "Ableton Cloud", "Live Clip", "Sound Similarity"], "common_mistakes": ["Confusing the always-present Core Library with optional add-on Packs", "assuming a Pack is only samples, when Packs can also hold Racks, presets, Clips and grooves", "deleting the downloaded .alp and not realizing it can be reinstalled later from the account"], "scenario_contexts": ["Installing a factory Pack of orchestral samples", "adding a third-party drum Pack to expand the browser", "redownloading a Pack from an Ableton account after a fresh install"], "formula_symbolic": "", "formula_words": ""}, {"id": "2806ad77-eb81-4661-91be-3d191a1253a3", "term": "MIDI Effect Rack", "definition": "A MIDI Effect Rack is a Live Rack that holds one or more parallel chains of MIDI effects behind a single device interface with Macro controls. It processes MIDI note and controller data only, is placed on MIDI tracks, and its chains can be filtered by key, velocity and chain-select zones. \"MIDI Effect Rack\" is a term of Ableton AG's Live.", "plain_english": "A MIDI Effect Rack groups several MIDI effects into one device. MIDI effects change notes, not audio. You can run effects side by side in chains inside it. Eight Macro knobs then control many of its settings at once.", "purpose_function": "It lets a user combine and layer several MIDI effects and control them together, so they can build complex note-processing tools.", "practical_application": "A technician builds a MIDI Effect Rack combining Arpeggiator, Scale and Chord devices, then maps key parameters to Macros for quick control.", "category": "Racks & Macros", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Macro Variations", "Max for Live Device", "Automation Capture", "Session Clip"], "common_mistakes": ["Placing a MIDI Effect Rack after the instrument; MIDI effects must sit before the instrument in the chain", "thinking it processes audio, when a MIDI Effect Rack only affects note and controller data", "forgetting that all parallel chains receive the same incoming notes unless zones filter them"], "scenario_contexts": ["Layering an arpeggiator and a chord generator in one device", "mapping several MIDI effect parameters to a single Macro for a live set", "splitting incoming notes by velocity into different MIDI effect chains"], "formula_symbolic": "", "formula_words": ""}, {"id": "ea6278dc-e0e1-4745-9f03-5b78e8fb346f", "term": "Macro Variations", "definition": "Macro Variations are stored snapshots of all Macro control positions within a single Live Rack. A user can save multiple variations and then recall or randomize them to instantly reconfigure every mapped parameter. \"Macro Variations\" is a term of Ableton AG's Live.", "plain_english": "Macros are knobs that control many settings at once inside a Rack. A Macro Variation saves where all those knobs are set. You can store several and switch between them instantly. This lets one Rack snap between very different sounds.", "purpose_function": "They let users capture and recall preset states of a Rack's Macros, making it easy to compare, perform or evolve a sound.", "practical_application": "A technician saves several Macro Variations for a synth Rack, then recalls them to switch patches during a performance.", "category": "Racks & Macros", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["MIDI Effect Rack", "Max for Live Device", "Automation Capture", "Simpler"], "common_mistakes": ["Expecting a variation to store parameters that are not mapped to Macros; only Macro positions are saved", "overwriting the current variation by accident instead of storing a new one", "assuming variations morph smoothly by default, when recall is immediate unless automated"], "scenario_contexts": ["Storing verse, chorus and breakdown settings as three variations of one Rack", "randomizing Macro Variations to find new sounds quickly", "switching an instrument's tone live without loading a new preset"], "formula_symbolic": "", "formula_words": ""}, {"id": "87fa5d8a-f17c-45d1-b7e0-9b9f4f2d9b4c", "term": "Max for Live Device", "definition": "A Max for Live device is an instrument, audio effect or MIDI effect built in the Max visual programming environment that runs inside Live like any native device, and is saved as a .amxd file. Max for Live is an add-on co-developed by Ableton AG and Cycling '74, the makers of Max.", "plain_english": "Max for Live lets people build their own Live devices. They make them in a visual coding tool called Max. The finished device runs inside Live like any instrument or effect. Its file ends in .amxd. Ableton built this together with a company called Cycling '74.", "purpose_function": "It lets users and developers extend Live with custom instruments, effects and tools that go beyond the built-in devices.", "practical_application": "A technician loads a Max for Live device to add a feature Live lacks, such as a custom sequencer or a script that talks to external hardware.", "category": "Extensibility", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Live API", "MIDI Effect Rack", "Macro Variations", "Ableton Cloud"], "common_mistakes": ["Assuming any Max patch runs in Live, when it must be built or wrapped as a Max for Live (.amxd) device", "confusing Max for Live, which runs inside Live, with standalone Max applications", "forgetting Max for Live needs a Live edition or license that includes it, such as Suite"], "scenario_contexts": ["Adding a generative sequencer built in Max for Live", "using a Max for Live device to communicate with external hardware", "editing a device's underlying Max patch to change its behavior"], "formula_symbolic": "", "formula_words": ""}, {"id": "37dda452-9b6e-4487-b528-87028a958294", "term": "Meld", "definition": "Meld is a bi-timbral synthesizer in Live that pairs two independent macro-oscillator engines, each with its own filters, envelopes, LFOs and modulation matrix. Its oscillators expose high-level \"macro\" controls plus scale-aware options, and it supports MPE (MIDI Polyphonic Expression). Meld is a device of Ableton AG's Live, introduced in Live 12.", "plain_english": "Meld is a synthesizer built from two sound engines. Each engine has its own filters, envelopes and modulation. Simple knobs shape the oscillators without deep menus. It also responds to per-note expression, known as MPE.", "purpose_function": "It is designed for hands-on, exploratory sound design, layering two synthesis engines to create evolving or unusual tones.", "practical_application": "A producer stacks Meld's two engines to build an expressive lead or an evolving pad, adjusting the macro oscillator knobs to explore timbres.", "category": "Ableton Instrument", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Drift", "Simpler", "Tension", "Roar", "Macro Variations"], "common_mistakes": ["Treating Meld as a single-engine synth, when it has two separate engines that can be layered or split", "ignoring MPE, when much of Meld's expression comes from per-note control", "expecting classic subtractive labels, when its oscillator macros are high-level rather than raw waveforms"], "scenario_contexts": ["Designing an evolving pad with the two engines detuned", "playing expressive leads from an MPE controller", "sound design for electronic tracks needing unusual textures"], "formula_symbolic": "", "formula_words": ""}, {"id": "44e61ea3-3226-4df1-be12-b19e1d8d3e1f", "term": "Note Set", "definition": "A Note Set is a project created in Ableton Note, Ableton's mobile sketching app for iOS/iPadOS. Note Sets contain the app's beats, melodies and sampled audio, and can be transferred to Live's browser through Ableton Cloud for further production. \"Note\" and \"Note Set\" are terms of Ableton AG.", "plain_english": "Ableton Note is a phone and tablet app for sketching music ideas. A project you make in it is called a Note Set. You can send a Note Set to Live using Ableton Cloud. Then you finish the track on your computer.", "purpose_function": "It lets musicians capture ideas on a mobile device and move them into Live, bridging quick sketching and full production.", "practical_application": "A technician records a beat as a Note Set on a phone, syncs it through Ableton Cloud, and opens it in Live to finish the arrangement.", "category": "Ableton Ecosystem", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Ableton Cloud", "Live Clip", "Session Clip", "Simpler"], "common_mistakes": ["Expecting to reopen an edited Note Set back in the Note app, when changing it in Live makes it no longer a Note project", "confusing a Note Set with a Live Set (.als), which is a different file type", "assuming transfer works without an Ableton Cloud account and internet"], "scenario_contexts": ["Sketching a melody on a phone during a commute", "syncing a mobile beat into Live to develop it", "sampling a real-world sound and importing it via a Note Set"], "formula_symbolic": "", "formula_words": ""}, {"id": "169ce20d-c61c-46fa-9de2-0820da46052b", "term": "Pseudo-Warp Marker", "definition": "A Pseudo-Warp Marker is a temporary, greyed marker Live shows at a detected transient in a warped audio clip. It is not yet a real Warp Marker, but double-clicking or dragging it creates an actual (yellow) Warp Marker that locks that point to the timeline. This is a feature of Ableton AG's Live.", "plain_english": "When you warp audio, Live marks likely beats with faint grey markers. These are Pseudo-Warp Markers. They are only suggestions, not fixed points yet. Double-click one to turn it into a real Warp Marker.", "purpose_function": "They give quick access to transient points, so a user can place Warp Markers exactly where beats occur without adding them by hand.", "practical_application": "A technician double-clicks Pseudo-Warp Markers on drum hits to pin them to the grid when fixing the timing of a recorded loop.", "category": "Warping", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Warp From Here", "Auto-Warp", "Sample Offset Envelope", "Session Clip"], "common_mistakes": ["Thinking Pseudo-Warp Markers already lock the audio, when they do nothing until converted to real Warp Markers", "confusing the grey pseudo markers with the yellow real Warp Markers", "expecting them on transient-free material, since they follow detected transients"], "scenario_contexts": ["Tightening a live drum take to the grid", "creating Warp Markers on beat transients before quantizing audio", "fixing timing in a sampled loop by pinning key hits"], "formula_symbolic": "", "formula_words": ""}, {"id": "50e4ce29-b8b5-43bc-b17a-52ac8822f397", "term": "Push Session Overview", "definition": "Push Session Overview is a navigation mode on Ableton's Push hardware that turns its 8x8 pad grid into a zoomed-out map of the Session View. Each pad then represents a block of clip slots, letting the user jump to any area of a large Set without looking at the computer screen. Push is hardware by Ableton AG.", "plain_english": "Push is Ableton's hardware controller with a grid of pads. Session Overview zooms the grid out to show the whole Session. Each pad then stands for a group of clips. Press a pad to jump straight to that part of your set.", "purpose_function": "It lets performers move quickly around a large Session View grid using the hardware, keeping their eyes off the computer.", "practical_application": "During a live set, a technician enters Session Overview and taps a pad to jump to a distant group of scenes on Push.", "category": "Push Hardware", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Push Standalone", "Session Clip", "Clip Slot", "Follow Action"], "common_mistakes": ["Confusing Session Overview, a zoomed navigation map, with normal Session mode where pads launch single clips", "forgetting it maps blocks of clips rather than individual clips", "expecting it for Arrangement work, when it navigates the Session grid"], "scenario_contexts": ["Jumping between song sections on Push during a performance", "navigating a large clip grid without the laptop screen", "locating a scene block quickly in a big Live Set"], "formula_symbolic": "", "formula_words": ""}, {"id": "8fe1ab19-7794-4d9f-8ab3-cd9b18b9fcc4", "term": "Push Standalone", "definition": "Push Standalone refers to Ableton's Push (the Push 3 standalone edition, or a controller fitted with the Upgrade Kit) that has an onboard computer running Ableton Live, so it can record and produce Sets without a connected laptop. It does not host VST or AU plug-ins and cannot edit the Arrangement View on the device. Push is hardware by Ableton AG.", "plain_english": "Some versions of Ableton's Push have a small computer built in. This lets Push run Live and make music with no laptop attached. You can record and play clips right on the hardware. It cannot use outside plug-ins or edit the Arrangement view on the device.", "purpose_function": "It lets producers work fully on the hardware, taking Live to places where using a computer is not practical.", "practical_application": "A technician sketches and records a track directly on a standalone Push, then later opens the Set on a computer to finish it.", "category": "Push Hardware", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Push Session Overview", "Session Clip", "Ableton Cloud", "Live API"], "common_mistakes": ["Assuming every Push is standalone, when only the standalone edition or an upgraded unit has the onboard computer", "expecting VST or AU plug-ins to run, when standalone Push does not host them, so such tracks must be frozen first", "trying to edit the Arrangement View on the device, when standalone mode records into Session View instead"], "scenario_contexts": ["Producing a track on Push away from a desk", "recording audio into Session View without a laptop", "freezing plug-in tracks before moving a project onto standalone Push"], "formula_symbolic": "", "formula_words": ""}, {"id": "6a8c2103-b365-41ea-8c90-d521171769e1", "term": "Redux", "definition": "Redux is a Live audio effect that degrades a signal by two means: bit-depth reduction (bit-crushing), which lowers amplitude resolution, and downsampling (sample-rate reduction), which lowers time resolution. Redux 2 (Live 11) adds further shaping controls. Redux is a device of Ableton AG's Live.", "plain_english": "Redux makes sound rougher on purpose. It cuts how finely the level is measured, called bit reduction. It also cuts how often the sound is sampled, called downsampling. Together these add grit and a lo-fi, digital character.", "purpose_function": "It recreates lo-fi digital artifacts and adds harshness or grit, useful for retro or aggressive electronic sounds.", "practical_application": "A technician adds Redux to a synth or drum bus and lowers the bit depth and sample rate to give it a crunchy, vintage-digital tone.", "category": "Ableton Audio Effect", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Saturator", "Roar", "Erosion", "Grain Delay"], "common_mistakes": ["Confusing bit reduction (level steps) with downsampling (rate reduction), since they cause different artifacts", "expecting warm analog distortion, when Redux produces harsh digital artifacts", "assuming the classic Redux has a dry/wet blend, when it does not"], "scenario_contexts": ["Adding lo-fi crunch to a drum loop", "creating retro video-game style tones", "roughening a clean synth for an aggressive texture"], "formula_symbolic": "", "formula_words": ""}, {"id": "7da83081-2b26-4ac3-b602-3b889b0ae34f", "term": "Roar", "definition": "Roar is a Live audio effect for saturation, distortion and coloration built around waveshaping stages (\"Shapers\") that can run in single, serial, parallel, mid-side, multiband or feedback configurations. It includes a modulation section (LFOs, envelope follower, noise) and a feedback loop with delay and compression. Roar is a device of Ableton AG's Live, introduced in Live 12.", "plain_english": "Roar adds warmth, grit or heavy distortion to sound. It shapes the waveform using one or more distortion stages. You can split the sound by frequency band or treat left and right separately. Built-in movement and feedback let the distortion change over time.", "purpose_function": "It provides flexible, modulatable saturation and distortion, from gentle warmth to extreme, animated destruction.", "practical_application": "A technician uses Roar in multiband mode to distort only the low end of a bass, then modulates the drive with an LFO for movement.", "category": "Ableton Audio Effect", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Saturator", "Redux", "Drum Buss", "Meld"], "common_mistakes": ["Pushing feedback too far without the internal compressor, so the sound collapses into noise", "treating Roar as a single distortion, when its routing modes such as serial, multiband and mid-side behave very differently", "forgetting that modulation is doing the work when a patch keeps changing"], "scenario_contexts": ["Warming up a drum bus with gentle saturation", "distorting only selected frequency bands of a bass", "designing evolving, modulated distortion textures"], "formula_symbolic": "", "formula_words": ""}, {"id": "0c548709-2ccd-4a8c-a2a0-73e2d1f0c4d2", "term": "Sample Offset Envelope", "definition": "A Sample Offset envelope is a clip envelope that modulates an audio clip's playback position while it is in Beats Warp Mode. Its values move the read position forward or backward in sixteenth-note steps, up to plus or minus eight sixteenths, producing stutters and glitches without editing the underlying sample. It is a feature of Ableton AG's Live.", "plain_english": "A clip envelope draws changes over a clip without editing the file. The Sample Offset type jumps where the audio is read from. It moves the playback spot earlier or later in small steps. This creates stutters and glitch effects in beats.", "purpose_function": "It lets a user rearrange and glitch a rhythmic loop non-destructively by shifting where playback reads within the sample.", "practical_application": "A technician draws a Sample Offset envelope on a drum loop to repeat or reorder hits, creating stutter fills without slicing the audio.", "category": "Clip Envelopes", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Pseudo-Warp Marker", "Warp From Here", "Session Clip", "Live Clip"], "common_mistakes": ["Trying to use it outside Beats Warp Mode, which the Sample Offset envelope requires", "expecting smooth pitch changes, when offsets jump the read position rather than time-stretch", "setting values beyond the plus or minus eight sixteenth range and expecting more"], "scenario_contexts": ["Creating stutter fills on a drum loop", "glitching a vocal chop rhythmically", "making quick variations of a beat without slicing it"], "formula_symbolic": "", "formula_words": ""}, {"id": "f04d1724-6f4a-4f4b-9462-f5446cce5061", "term": "Saturator", "definition": "Saturator is a Live audio effect that adds harmonic distortion by waveshaping. A Drive control sets the amount, while six selectable curves (such as Analog Clip, Soft Sine, Sinoid Fold and Digital Clip) plus a custom waveshaper section set its character, from subtle warmth to hard clipping. Saturator is a device of Ableton AG's Live.", "plain_english": "Saturator adds warmth and edge by gently distorting a signal. A Drive knob sets how hard it pushes. Different curves change the flavor of the distortion. You can go from soft warmth to hard clipping.", "purpose_function": "It adds harmonics and perceived loudness or grit, used to warm, thicken or aggressively distort a sound.", "practical_application": "A technician puts Saturator on a bass or drum bus, raises Drive for warmth, then picks a curve and sets the output to control level.", "category": "Ableton Audio Effect", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Roar", "Redux", "Drum Buss", "Glue Compressor"], "common_mistakes": ["Adding heavy Drive without lowering the output, causing clipping further down the chain", "assuming all curves sound the same, when each waveshaping curve has a distinct tone", "using it only for loudness and ignoring the harmonic change it makes"], "scenario_contexts": ["Warming a clean bassline", "adding edge to a synth lead", "gluing a drum bus with gentle saturation"], "formula_symbolic": "", "formula_words": ""}, {"id": "39c6e2d5-5146-4883-8691-6701e91244bd", "term": "Session Clip", "definition": "A Session Clip is a clip that sits in a slot of Live's Session View grid, launched on demand by its own play button and looped or triggered independently of the timeline. It contrasts with an Arrangement clip, which plays at a fixed position on the Arrangement timeline. The term is from Ableton AG's Live.", "plain_english": "The Session View is a grid of clip slots in Live. A clip in one of those slots is a Session Clip. You start it by pressing its play button, in any order. This suits live jamming and looping.", "purpose_function": "Session Clips let a user trigger musical ideas freely and loop them, supporting improvisation, live performance and non-linear arranging.", "practical_application": "A technician launches Session Clips from scenes to build a live arrangement on the fly, looping sections until the next cue.", "category": "Clips & Files", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Live Clip", "Clip Slot", "Follow Action", "Push Session Overview", "Sample Offset Envelope"], "common_mistakes": ["Confusing a Session Clip in the Session grid with a saved Live Clip file (.alc)", "forgetting that launching a Session clip stops the Arrangement on that track", "expecting linear playback, when Session clips are launched rather than laid on a timeline"], "scenario_contexts": ["Jamming ideas by triggering clips live", "looping a section during a performance", "recording a Session performance into the Arrangement"], "formula_symbolic": "", "formula_words": ""}, {"id": "c1fd1fab-13a2-493d-acfc-f9a8d2f16536", "term": "Simpler", "definition": "Simpler is a sample-based instrument in Live that plays a single audio sample across the keyboard with envelope, filter and modulation controls. It offers three playback modes, Classic, One-Shot and Slicing, and can warp samples; it works as a streamlined subset of Live's full Sampler. Simpler is a device of Ableton AG's Live.", "plain_english": "Simpler is an instrument that plays one audio sample. You can play that sample at different pitches across a keyboard. It has three modes for melodies, one-shots and chopped slices. It is a simpler version of Ableton's full Sampler.", "purpose_function": "It turns any sample into a playable instrument quickly, for melodic sampling, one-shot drums or slicing loops.", "practical_application": "A technician drags a vocal sample into Simpler, sets Slicing mode, and plays each slice from a different pad.", "category": "Ableton Instrument", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Impulse", "Meld", "Tension", "Sample Offset Envelope", "Sound Similarity"], "common_mistakes": ["Confusing Simpler with the full Sampler, when Simpler exposes fewer controls and plays one sample layer", "using Classic mode for drum hits, when One-Shot mode avoids retriggering and envelope cutoff", "forgetting that Slicing mode maps slices across the keyboard automatically"], "scenario_contexts": ["Turning a found sound into a playable instrument", "chopping a break into slices for a beat", "triggering one-shot samples from a controller"], "formula_symbolic": "", "formula_words": ""}, {"id": "c8fc358a-2346-4a0b-8f75-02f9ef1ec0e6", "term": "Sound Similarity", "definition": "Sound Similarity (Similarity Search) is a Live 12 browser feature that finds samples that sound alike by analyzing their audio and comparing a reference file to items in the Core Library and User Library. Results are ranked by sonic closeness. It is a feature of Ableton AG's Live.", "plain_english": "Sound Similarity helps you find samples that sound alike. Live listens to a sample and compares it with your library. It then shows the closest matches, ranked by how similar they are. This helps you find alternatives fast.", "purpose_function": "It speeds up browsing large sample libraries by surfacing sonically related sounds instead of relying on file names or folders.", "practical_application": "A technician right-clicks a snare sample and chooses to show similar files, then auditions the ranked matches to pick a better fit.", "category": "Library & Browser", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["User Library", "Core Library", "Live Pack", "Simpler"], "common_mistakes": ["Expecting it to search by file name, when it compares the actual sound rather than the label", "assuming it covers every folder, when it compares against analyzed Library content", "forgetting that samples must be analyzed before they can be matched"], "scenario_contexts": ["Finding a snare that sits better in a mix", "discovering forgotten samples that match a reference", "browsing a large library by sound instead of by name"], "formula_symbolic": "", "formula_words": ""}, {"id": "bf828d95-8839-4409-bff6-021ac34f3aca", "term": "Spectral Resonator", "definition": "Spectral Resonator is a Live audio effect that uses spectral (FFT) processing to split incoming sound into frequency partials and resonate them around a tunable fundamental, set by hand or played via MIDI. Partials can be stretched or pitch-shifted as a group and given long decay times. It is a device of Ableton AG's Live, introduced in Live 11.", "plain_english": "Spectral Resonator breaks a sound into many frequency parts. It then rings those parts around a chosen pitch. You can tune it by hand or play it with MIDI notes. This adds metallic, bell-like or pitched tones to any sound.", "purpose_function": "It reshapes a signal's frequency content into tuned, resonant tones, useful for pitched textures, metallic effects and playable ambiences.", "practical_application": "A technician sends a drum loop through Spectral Resonator and plays MIDI chords into it, turning the hits into ringing metallic harmonies.", "category": "Ableton Audio Effect", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Spectral Time", "Corpus", "Hybrid Reverb", "Grain Delay"], "common_mistakes": ["Confusing it with a reverb, when it resonates tuned partials rather than simulating a space", "forgetting it can be pitched by MIDI, not only set by hand", "pushing long decay times into runaway buildups without watching levels"], "scenario_contexts": ["Turning percussion into pitched metallic tones", "playing the effect as a tuned instrument via MIDI", "adding ringing resonances to a pad"], "formula_symbolic": "", "formula_words": ""}, {"id": "d41089b7-1dd3-407b-b478-f191ab070465", "term": "Spectral Time", "definition": "Spectral Time is a Live audio effect built on spectral (FFT) processing with two sections: a Freezer that captures and sustains a moment of the sound's spectrum, and a Delay with a frequency shifter that can tilt delay time across the frequency range, producing smearing and blurring. It is a device of Ableton AG's Live, introduced in Live 11.", "plain_english": "Spectral Time works on the frequency picture of a sound. Its Freezer can hold a moment of sound and stretch it out. Its Delay smears echoes across different pitches. Together they make blurred, ghostly, granular textures.", "purpose_function": "It creates spectral freezes and frequency-dependent delays, useful for ambient smears, granular textures and evolving tails.", "practical_application": "A technician freezes a vocal note with Spectral Time and adds the tilted delay to create a slowly blurring ambient tail.", "category": "Ableton Audio Effect", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Spectral Resonator", "Grain Delay", "Hybrid Reverb", "Corpus"], "common_mistakes": ["Confusing the Freezer, a spectral hold, with the Delay section, which does a different job", "expecting a normal delay, when its delay is frequency-dependent and smears the sound", "freezing without automation, so the texture never evolves"], "scenario_contexts": ["Freezing a chord into a sustained pad", "creating granular ambient smears from vocals", "adding blurred, pitched delay tails to a synth"], "formula_symbolic": "", "formula_words": ""}, {"id": "a46436bc-0114-4cb4-ba1b-558dcbcb3a61", "term": "Tension", "definition": "Tension is a physical-modeling synthesizer in Live that simulates strings rather than using samples. Its signal chain models an excitator (bow, hammer or plectrum), a vibrating string, a damper and a resonating body, plus filter and global voice controls. Tension was developed by Ableton AG with Applied Acoustics Systems (AAS).", "plain_english": "Tension makes string sounds by simulating physics, not by playing recordings. It models how a string is set moving, by a bow, hammer or pick. It then models the string, a damper and a body that resonates. This creates realistic or unusual string tones.", "purpose_function": "It generates plucked, struck and bowed string sounds and lets users push the model beyond real instruments for new timbres.", "practical_application": "A technician chooses the bow excitator in Tension and adjusts the string and body settings to craft an expressive bowed-string patch.", "category": "Ableton Instrument", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Collision", "Electric", "Corpus", "Meld", "Simpler"], "common_mistakes": ["Expecting sampled realism, when Tension synthesizes strings, so tuning many interacting parameters matters", "ignoring the excitator choice, which strongly shapes whether a string is bowed, struck or plucked", "pushing physical parameters to extremes and getting sudden level jumps"], "scenario_contexts": ["Designing a bowed string patch", "creating plucked or struck string tones without samples", "sound design for evolving, unreal string textures"], "formula_symbolic": "", "formula_words": ""}, {"id": "4e685891-1fec-4bb2-b324-b977589b746a", "term": "User Library", "definition": "The User Library is a fixed location in Live's browser where a user's own content lives: saved presets, Racks, default presets, samples, Live Clips, grooves and Max devices. It is the standard place Live stores user content, and installed Packs may add material to it. It is a feature of Ableton AG's Live.", "plain_english": "The User Library is your personal folder inside Live's browser. Live saves your presets, Racks and clips here. It also holds your default settings and grooves. You can reach this content from any project.", "purpose_function": "It gives users one persistent place to store and recall their own presets and content across all projects.", "practical_application": "A technician drags a custom effect Rack into the User Library so it is available as a preset in every future Set.", "category": "Library & Content", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Live Pack", "Core Library", "Live Clip", "Sound Similarity"], "common_mistakes": ["Confusing the User Library, which holds your content, with the Core Library, which holds Ableton's factory content", "saving custom presets into a single project instead of the User Library, so they are not reusable elsewhere", "assuming default presets live elsewhere, when Live stores them in the User Library"], "scenario_contexts": ["Saving a signature effect chain for reuse", "storing a default preset for a device", "keeping a personal collection of loops and Racks"], "formula_symbolic": "", "formula_words": ""}, {"id": "f8f3d885-8f2b-4437-9f84-acb73bc99da6", "term": "Warp From Here", "definition": "Warp From Here is a Live context-menu command that runs the Auto-Warp algorithm on the audio to the right of a chosen point, aligning it to Live's tempo grid from that spot. Variants include Warp From Here (Straight), which assumes a steady tempo and sets a single marker, and Warp From Here (Start at [tempo] BPM). It is a feature of Ableton AG's Live.", "plain_english": "Warping stretches audio to match Live's tempo. Warp From Here tells Live to auto-warp everything after a chosen point. Live then lines up the beats from that spot onward. A \"Straight\" version assumes a steady tempo and adds just one marker.", "purpose_function": "It quickly aligns a section of audio to the project tempo while giving the user control over where auto-warping begins.", "practical_application": "A technician right-clicks a downbeat in a clip and chooses Warp From Here to auto-align the rest of the loop to the grid.", "category": "Warping", "difficulty": "intermediate", "achievement_id": "38c2d27b-ab2f-4f66-865d-762cf92c8f83", "cross": [], "related_terms": ["Auto-Warp", "Pseudo-Warp Marker", "Sample Offset Envelope", "Session Clip"], "common_mistakes": ["Using the Straight option on tempo-varying audio, which assumes a single steady tempo", "choosing the wrong start point, so the whole warp ends up offset", "expecting it to fix audio to the left of the chosen marker, when it works to the right"], "scenario_contexts": ["Aligning a loop to the project tempo from its first downbeat", "re-warping the second half of a clip after an edit", "fixing grid alignment on an imported sample"], "formula_symbolic": "", "formula_words": ""}, {"id": "3747f02d-abf5-4097-a4dc-ad157471c8ee", "term": "ADG file", "definition": "An ADG file is Ableton Live's Device Group format (extension .adg), a preset file that stores a Rack preset: one or more instruments and/or effects grouped into a Rack, with their device chains, parameter settings and Macro Control mappings. It stores device configuration, not audio. The .adg name is proprietary to Ableton AG, which develops Live; the underlying idea of a saved multi-device preset is generic across DAWs.", "plain_english": "An ADG file is a saved Ableton Live \"Rack.\" A Rack bundles several instruments or effects, plus their settings, into one preset. You drag it from the browser onto a track to load the whole group at once. Ableton AG makes Live and owns the ADG name.", "purpose_function": "It lets a user save a whole group of devices and their settings as one recallable preset, so complex signal chains can be reused instantly. It exists so Racks can be organized, shared and loaded from the Library.", "practical_application": "A technician drags or double-clicks an .adg in Live's browser to drop a pre-built effect or instrument Rack onto a track, or saves a custom Rack as .adg to reuse it across projects.", "category": "Ableton file format", "difficulty": "intermediate", "achievement_id": "ab5f6383-b4af-499d-937d-c8cd9cab317f", "cross": ["38c2d27b-ab2f-4f66-865d-762cf92c8f83"], "related_terms": ["ALS file", "ADV file", "Instrument Rack", "Drum Rack", "Macro Control", "Ableton Live Library"], "common_mistakes": ["Confusing .adg (a Rack / device group) with .adv (a single device preset).", "Thinking an .adg contains audio; it stores device settings, not samples.", "Assuming an .adg holds a whole song, which is actually a Live Set (.als).", "Expecting an .adg to work without the plug-ins it references being installed."], "scenario_contexts": ["Loading a preset effects Rack onto a vocal track from the browser.", "Saving a custom multi-device instrument Rack for reuse in later sessions.", "Sharing a signature effect chain with a collaborator as one .adg file."], "formula_symbolic": "", "formula_words": ""}, {"id": "b17fa6ae-13e7-4858-bb98-eb9462cbf192", "term": "AGR file", "definition": "An AGR file is Ableton Live's Groove format (extension .agr), a file that stores a groove template: the timing and, optionally, velocity/volume information that imposes a rhythmic feel on clips. Grooves can be extracted from audio or MIDI clips and are applied non-destructively through the Groove Pool. The .agr name is proprietary to Ableton AG; the underlying concept of groove/quantize templates is generic across DAWs.", "plain_english": "An AGR file is an Ableton Live \"groove.\" A groove is a saved rhythmic feel, such as how far notes sit ahead of or behind the beat. You drop it onto a clip to add swing or a more human feel. Ableton AG makes Live and owns the AGR name.", "purpose_function": "It stores a reusable timing and feel template so the same rhythmic feel can be applied to many clips without editing each note by hand. It exists to add swing or match one part's feel to another.", "practical_application": "A technician drags a groove (.agr) from the browser onto a MIDI or audio clip, then adjusts timing, quantize and velocity amounts in the Groove Pool to tighten or loosen the feel.", "category": "Ableton file format", "difficulty": "intermediate", "achievement_id": "ab5f6383-b4af-499d-937d-c8cd9cab317f", "cross": ["38c2d27b-ab2f-4f66-865d-762cf92c8f83"], "related_terms": ["ALC file", "ASD file", "Groove Pool", "Quantization", "Warp", "MIDI clip"], "common_mistakes": ["Thinking a groove permanently rewrites the clip; it is non-destructive until committed.", "Expecting a groove to add or remove notes; it only shifts timing and velocity of existing ones.", "Confusing the global Amount slider with per-note swing or quantize settings.", "Forgetting that grooves on audio clips rely on the clip's warp markers."], "scenario_contexts": ["Applying an extracted drum-loop feel to a stiff programmed MIDI beat.", "Adding subtle swing to a hi-hat pattern using a library groove.", "Extracting the timing of a recorded performance to reuse on other parts."], "formula_symbolic": "", "formula_words": ""}, {"id": "29eb183e-97b0-40d9-973a-fbe988848da7", "term": "ALC file", "definition": "An ALC file is Ableton Live's Live Clip format (extension .alc), which stores a single audio or MIDI clip together with its clip and envelope/automation settings and the source track's device chain. Audio Live Clips store references to samples on disk rather than the audio itself, so the files are small. The .alc format is proprietary to Ableton AG, which develops Live.", "plain_english": "An ALC file is one saved clip from Ableton Live. It keeps the clip's settings and the effects that were on its track. For audio clips it points to the sound file instead of copying it, so the file stays small. Ableton AG makes Live and owns the ALC name.", "purpose_function": "It lets a user save and reuse a single clip, plus its device chain and settings, across projects. It exists so people can build a personal library of ready-made parts.", "practical_application": "A technician drags a clip into the browser to create an .alc, then later double-clicks or drags it onto a track to recall that part with its original sound and effects.", "category": "Ableton file format", "difficulty": "intermediate", "achievement_id": "ab5f6383-b4af-499d-937d-c8cd9cab317f", "cross": ["38c2d27b-ab2f-4f66-865d-762cf92c8f83"], "related_terms": ["ALS file", "ADG file", "ASD file", "AGR file", "Session View", "MIDI clip"], "common_mistakes": ["Assuming an audio .alc contains the audio; it usually only references the sample on disk.", "Moving the .alc away from its referenced sample, which breaks playback.", "Confusing a Live Clip (.alc) with a whole Live Set (.als).", "Expecting an .alc loaded onto a track with devices to replace them; it keeps the existing devices."], "scenario_contexts": ["Saving a favorite MIDI bassline with its instrument and effects for reuse.", "Building a browser library of loops that recall their processing.", "Dragging a Live Clip into a new set to reuse a drum pattern."], "formula_symbolic": "", "formula_words": ""}, {"id": "36e906b2-6372-49a9-92b8-28fa43e97c54", "term": "ALP file", "definition": "An ALP file is Ableton Live's Live Pack format (extension .alp), a compressed archive used to distribute official Ableton Packs or to bundle a user-packed Live Set and its associated content into a single installable file. Live uses lossless compression to reduce the size. The .alp format is proprietary to Ableton AG, which develops Live.", "plain_english": "An ALP file is an Ableton Live \"Pack.\" It bundles sounds, presets, or a whole project into one compressed file. You double-click it to install the content into Live. Ableton AG makes Live and owns the ALP name.", "purpose_function": "It packages related content such as samples, presets and sets into one compressed file for easy sharing, backup and installation. It exists to move complete content libraries or projects as a single item.", "practical_application": "A technician double-clicks an .alp, or uses Install Pack, to add a sound library to Live, or packs a project into an .alp to archive or send it.", "category": "Ableton file format", "difficulty": "intermediate", "achievement_id": "ab5f6383-b4af-499d-937d-c8cd9cab317f", "cross": ["38c2d27b-ab2f-4f66-865d-762cf92c8f83"], "related_terms": ["ALS file", "ALC file", "ADG file", "ASD file", "Ableton Live Library", "Sample"], "common_mistakes": ["Confusing a Live Pack (.alp) with a Live Set (.als); a Pack is a distributable archive.", "Deleting the .alp after install, then expecting to reinstall later without it.", "Assuming .alp is an ordinary zip to edit directly; it is Live's managed archive.", "Thinking installing a Pack embeds it into a specific Set rather than the Library."], "scenario_contexts": ["Installing a purchased Ableton instrument or sound Pack.", "Packing a finished project to archive all its samples with the set.", "Sending a complete project to a collaborator as one file."], "formula_symbolic": "", "formula_words": ""}, {"id": "49001f3d-e426-4e8b-8bf2-a112130cb8eb", "term": "ALS file", "definition": "An ALS file is Ableton Live's Live Set format (extension .als), the main project document that stores a single song: its tracks, Session and Arrangement clips, device settings, mixer state and arrangement. It references the samples it uses rather than embedding them, and is normally kept inside a Live Project folder. Template Sets also use the .als extension. The format is proprietary to Ableton AG, which develops Live.", "plain_english": "An ALS file is an Ableton Live project, meaning one song. It saves your tracks, clips, instruments, effects, and mix. It points to your audio files rather than storing them inside. Ableton AG makes Live and owns the ALS name.", "purpose_function": "It is the working document a user saves and reopens to keep and edit an entire arrangement in Live. It exists to hold all the parts of one song project in one file.", "practical_application": "A technician saves work as an .als and reopens it to continue a mix or arrangement; keeping it inside its Live Project folder lets Live track the samples and clips it uses.", "category": "Ableton file format", "difficulty": "intermediate", "achievement_id": "ab5f6383-b4af-499d-937d-c8cd9cab317f", "cross": ["38c2d27b-ab2f-4f66-865d-762cf92c8f83"], "related_terms": ["ALC file", "ALP file", "ADG file", "ASD file", "Ableton Live Project", "Session View"], "common_mistakes": ["Moving the .als out of its Project folder and losing links to samples.", "Thinking the .als embeds audio; it references samples stored on disk.", "Confusing a Live Set (.als) with a Live Pack (.alp) or a Live Clip (.alc).", "Sending only the .als without collecting or packing its samples."], "scenario_contexts": ["Saving and reopening a song project across multiple sessions.", "Creating a default template Set saved as .als.", "Handing off a project by packing the .als and its samples together."], "formula_symbolic": "", "formula_words": ""}, {"id": "a2a7bf44-f11c-472d-b4e6-f3e1063f38c2", "term": "AMXD file", "definition": "An AMXD file is Ableton Live's Max for Live device format (extension .amxd), a standalone patch file containing a device (instrument, audio or MIDI effect, or MIDI tool) built in the Max programming environment. Max for Live is co-developed by Ableton AG and Cycling '74, and Max itself is developed by Cycling '74. A Set references the .amxd rather than embedding it.", "plain_english": "An AMXD file is a Max for Live device. It is a custom instrument or effect built with the Max programming tool. You drag it onto a track like any other Live device. Ableton AG and Cycling '74 build Max for Live together, and Cycling '74 makes Max.", "purpose_function": "It lets users add and share custom-built instruments, effects and tools that extend Live beyond its built-in devices. It exists so the Max environment's capabilities can run as Live devices.", "practical_application": "A technician loads an .amxd device from the browser onto a track, and can choose Edit in Max to open and modify its patch.", "category": "Ableton file format", "difficulty": "intermediate", "achievement_id": "ab5f6383-b4af-499d-937d-c8cd9cab317f", "cross": ["38c2d27b-ab2f-4f66-865d-762cf92c8f83"], "related_terms": ["ADG file", "ADV file", "ALS file", "Max for Live", "Audio Effect Rack", "MIDI effect"], "common_mistakes": ["Moving or renaming a referenced .amxd, which breaks its file path in the Set.", "Assuming Max for Live ships with every Live edition; it comes with Suite or as an add-on.", "Thinking the .amxd is embedded in the Set; the Set references it.", "Confusing a Max device (.amxd) with a standard device preset (.adv or .adg)."], "scenario_contexts": ["Loading a community-made Max for Live synth or effect.", "Editing a Max device's patch through Edit in Max.", "Distributing a custom-built MIDI tool as an .amxd file."], "formula_symbolic": "", "formula_words": ""}, {"id": "4c6a3cac-4502-41f8-911a-bf04ff9e8c91", "term": "ASD file", "definition": "An ASD file is Ableton Live's sample analysis format (extension .asd), a small companion file Live creates the first time a sample is imported. It stores analysis data used to optimize time-stretching (warping) quality, speed up waveform display and support automatic tempo detection, and it can also store default clip settings for that sample. Live saves it next to the sample, and it does not appear in Live's browser. The format is proprietary to Ableton AG.", "plain_english": "An ASD file is a small helper file Ableton Live makes for an audio sample. It holds analysis data so Live can stretch the sound, draw its waveform quickly, and guess its tempo. Live saves it next to the sample and hides it from the browser. Ableton AG makes Live and owns the ASD name.", "purpose_function": "It caches per-sample analysis, plus optional default clip settings, so Live can warp, display and tempo-detect audio quickly without re-analyzing each time. It exists to speed up sample handling and preserve warp defaults.", "practical_application": "A technician sees an .asd appear automatically beside an imported audio file; saving clip settings to it means the sample reloads with the same warp markers and defaults.", "category": "Ableton file format", "difficulty": "intermediate", "achievement_id": "ab5f6383-b4af-499d-937d-c8cd9cab317f", "cross": ["38c2d27b-ab2f-4f66-865d-762cf92c8f83"], "related_terms": ["ALC file", "ALS file", "AGR file", "Warp", "Warp Markers", "Sample"], "common_mistakes": ["Deleting .asd files thinking they are audio; Live re-creates them but loses saved warp and default settings.", "Expecting to see the .asd in the browser; it stays hidden next to the sample.", "Thinking the .asd stores the audio; it only stores analysis and settings data.", "Assuming deleting .asd files frees meaningful space; they are tiny."], "scenario_contexts": ["An .asd appears automatically the first time a WAV is dragged into Live.", "Saving warp markers and default clip settings so a loop reloads correctly.", "Backing up a sample folder and including the .asd files to keep warp data."], "formula_symbolic": "", "formula_words": ""}, {"id": "14e8b713-4f50-4ea9-9a33-1c4e100d7209", "term": "360 Reality Audio", "definition": "360 Reality Audio is Sony's proprietary object-based immersive music format. Individual sounds are treated as objects carrying position metadata within a 360-degree spherical sound field, rather than fixed stereo or channel-based tracks. It is built on the MPEG-H 3D Audio codec, an ISO/IEC standard developed primarily by Fraunhofer IIS, and is delivered through streaming services for playback on ordinary headphones or certified speakers.", "plain_english": "360 Reality Audio is Sony's way of making music surround you. Each instrument or voice sits at its own spot in a sphere of sound. You can hear it on normal headphones through certain streaming apps. Sony owns this format, but it uses the shared MPEG-H standard underneath.", "purpose_function": "It exists to let artists position sounds anywhere around the listener, creating a three-dimensional music experience that channel-based stereo cannot reproduce.", "practical_application": "Engineers author tracks as objects and encode them to this format for streaming, and technicians confirm correct playback on certified headphones and speakers.", "category": "Immersive Audio Format", "difficulty": "advanced", "achievement_id": "cad1c4e5-d4fb-4543-85f6-3fe985dcec45", "cross": [], "related_terms": ["360 Spatial Sound", "WalkMix Creator", "MPEG-H 3D Audio", "Object-based audio", "Dolby Atmos Music"], "common_mistakes": ["Confusing 360 Reality Audio (Sony's object-based music format) with Dolby Atmos Music, a competing immersive format.", "Assuming it needs special speakers; it also renders binaurally over ordinary headphones.", "Thinking it is channel-based; it stores sounds as positioned objects plus metadata."], "scenario_contexts": ["Streaming a 360 Reality Audio track on a music service through compatible headphones.", "Verifying that a certified soundbar decodes the format correctly.", "Delivering a mix encoded in the format to a streaming platform."], "formula_symbolic": "", "formula_words": ""}, {"id": "da1fee90-52dc-4a98-ae9b-71a07f2d86e0", "term": "360 Reality Audio Creative Suite", "definition": "360 Reality Audio Creative Suite was the original name of Sony's digital audio workstation plug-in for authoring 360 Reality Audio content. Co-developed by Sony and Virtual Sonics (distributed via Audio Futures) and released in 2021, it let engineers pan audio objects in a 3D spherical field and encode them to the MPEG-H 3D Audio based 360 Reality Audio format. In January 2022 it was renamed 360 WalkMix Creator. The name and technology are trademarks of Sony.", "plain_english": "This was the first tool for making Sony's 360 Reality Audio music. It is a plug-in that runs inside recording software. Engineers use it to place sounds around a 3D sphere and save them in Sony's format. Sony renamed it WalkMix Creator in January 2022.", "purpose_function": "It gave creators a practical way to mix and encode object-based 360 Reality Audio inside common DAWs, instead of needing a dedicated studio system.", "practical_application": "An immersive-music engineer used it to place instrument objects and export MPEG-H deliverables; that same job is now done in its successor, WalkMix Creator.", "category": "Immersive Authoring Tool", "difficulty": "advanced", "achievement_id": "cad1c4e5-d4fb-4543-85f6-3fe985dcec45", "cross": [], "related_terms": ["WalkMix Creator", "360 Reality Audio", "MPEG-H 3D Audio", "Object-based audio", "DAW plug-in"], "common_mistakes": ["Treating it as a current product; it was renamed WalkMix Creator in January 2022.", "Assuming Sony built it alone; it was co-developed with Virtual Sonics / Audio Futures.", "Confusing the authoring plug-in with the 360 Reality Audio playback format itself."], "scenario_contexts": ["Reading older documentation that still uses the Creative Suite name.", "Migrating a legacy project into WalkMix Creator.", "Explaining the tool's history to a student learning immersive mixing."], "formula_symbolic": "", "formula_words": ""}, {"id": "6f6a0433-4e2b-43b3-82d9-c7596c789899", "term": "360 Spatial Sound", "definition": "360 Spatial Sound is Sony's brand name for its object-based spatial audio technology, which represents sounds as positioned objects in a three-dimensional field. It is the underlying approach behind Sony offerings such as 360 Reality Audio (music, using MPEG-H 3D Audio) and spatial features on Sony TVs, soundbars and headphones. The term is a Sony trademark; representing audio as objects is itself a general, industry-wide concept.", "plain_english": "360 Spatial Sound is Sony's name for its surround-you sound technology. It treats sounds as objects with a position in 3D space. Sony uses it in music, TVs, soundbars, and gaming headphones. Placing sound as objects is common, but this brand name belongs to Sony.", "purpose_function": "It provides a shared spatial-audio foundation Sony reuses across products, so sounds can be placed around the listener instead of fixed to two channels.", "practical_application": "Technicians meet the label on Sony product menus and spec sheets, where it signals object-based spatial rendering over speakers or headphones.", "category": "Spatial Audio Technology", "difficulty": "advanced", "achievement_id": "cad1c4e5-d4fb-4543-85f6-3fe985dcec45", "cross": [], "related_terms": ["360 Reality Audio", "360 Spatial Sound Mapping", "360 Spatial Sound Personalizer", "Object-based audio", "MPEG-H 3D Audio"], "common_mistakes": ["Reading it as one single product; it is an umbrella brand across several Sony features.", "Assuming it is identical to 360 Reality Audio; that music format is one application of it.", "Believing object-based audio is unique to Sony; the concept is used across the industry."], "scenario_contexts": ["Comparing Sony spatial-audio features when specifying a home-theatre system.", "Reading a Sony soundbar spec sheet that lists 360 Spatial Sound.", "Explaining to a client which Sony products share the technology."], "formula_symbolic": "", "formula_words": ""}, {"id": "fae2d4b7-757c-4ca7-973b-bf76ac80c7cb", "term": "360 Spatial Sound Mapping", "definition": "360 Spatial Sound Mapping (360SSM) is Sony's home-theatre technology that measures the relative position of each connected speaker and synthesises additional virtual (phantom) speakers around the listener. Found in Sony BRAVIA Theatre soundbars, systems and AV receivers, it widens the perceived sound field beyond the physical speakers. The name and technology are trademarks of Sony; creating phantom images between real speakers is itself a general acoustics principle.", "plain_english": "This Sony feature makes a soundbar seem to have more speakers than it does. It measures where your real speakers sit. Then it creates extra 'phantom' speakers around you for a wider, cinema-like sound. You find it in Sony's BRAVIA Theatre home cinema products.", "purpose_function": "It aims to deliver enveloping surround sound from a limited number of physical speakers by generating extra virtual sound sources.", "practical_application": "An installer calibrates a BRAVIA Theatre system so the mapping measures speaker positions and expands the surround image for the room.", "category": "Home Theatre Processing", "difficulty": "advanced", "achievement_id": "cad1c4e5-d4fb-4543-85f6-3fe985dcec45", "cross": [], "related_terms": ["360 Spatial Sound", "Phantom speaker", "Dolby Atmos", "DTS:X", "Soundbar"], "common_mistakes": ["Expecting it to add real channels; it synthesises virtual speakers only.", "Skipping the speaker-position measurement that the effect depends on.", "Confusing it with 360 Reality Audio, which is a music format, not home-theatre processing."], "scenario_contexts": ["Setting up a BRAVIA Theatre soundbar with wireless rear speakers.", "Calibrating a Sony AV receiver's spatial mapping for a living room.", "Comparing virtual surround against a physical 5.1 speaker layout."], "formula_symbolic": "", "formula_words": ""}, {"id": "22de7346-d3fc-4523-b570-c225f48deefa", "term": "360 Spatial Sound Personalizer", "definition": "360 Spatial Sound Personalizer is a Sony smartphone application that captures images of the user's ears with the phone camera to build an individual spatial-sound profile. The profile tailors Sony's spatial audio to that listener's hearing characteristics and is stored in a Sony account for use across compatible Sony devices, including headphones, TVs and soundbars. The name and app are trademarks of Sony; individualising the head-related transfer function is itself a general spatial-audio method.", "plain_english": "This free Sony app makes spatial sound fit your own ears. You use your phone camera to take pictures of your ears. The app builds a personal sound profile and saves it to your account. Supported Sony devices then use it for a better surround feel.", "purpose_function": "It exists because every person's ears differ; matching the spatial rendering to the individual improves how accurately sounds seem to come from around them.", "practical_application": "A user scans their ears once, and technicians then load that profile onto Sony headphones or a TV to enable personalised spatial sound.", "category": "Spatial Audio Personalization", "difficulty": "advanced", "achievement_id": "cad1c4e5-d4fb-4543-85f6-3fe985dcec45", "cross": [], "related_terms": ["360 Spatial Sound", "360 Reality Audio", "360 Spatial Sound for Gaming", "Head-related transfer function", "Binaural rendering"], "common_mistakes": ["Thinking one profile suits everyone; the scan is personal to each listener's ears.", "Assuming it works on any headphones; it requires supported Sony devices.", "Believing it replaces a music subscription; 360 Reality Audio playback still needs a compatible service."], "scenario_contexts": ["Scanning your ears to enable personalised 360 Reality Audio on Sony headphones.", "Setting up personalised spatial sound for a Sony soundbar or TV.", "Creating a profile for use across several supported Sony devices."], "formula_symbolic": "", "formula_words": ""}, {"id": "a6d3a534-399d-4839-a0fa-66175ad3ff16", "term": "360 Spatial Sound for Gaming", "definition": "360 Spatial Sound for Gaming is Sony's headphone spatial-audio feature on its INZONE gaming headsets. It renders game audio as a 360-degree sound field so players can judge the direction and distance of in-game sources, and it can be individualised through the 360 Spatial Sound Personalizer. It is used on PC via the INZONE Hub software. The name and technology are trademarks of Sony; virtual (binaural) headphone surround is itself a general concept.", "plain_english": "This Sony feature gives gamers surround sound over INZONE headphones. It helps you hear where enemies are and how far away. You can match it to your own ears with a scanning app. On a computer, you control it with Sony's INZONE Hub software.", "purpose_function": "It exists to give players precise positional audio cues over headphones, helping them locate opponents and events they cannot yet see.", "practical_application": "A player enables it in INZONE Hub and loads a personalised profile to sharpen directional cues in competitive games.", "category": "Gaming Spatial Audio", "difficulty": "advanced", "achievement_id": "cad1c4e5-d4fb-4543-85f6-3fe985dcec45", "cross": [], "related_terms": ["360 Spatial Sound", "360 Spatial Sound Personalizer", "INZONE", "Head-related transfer function", "Binaural rendering"], "common_mistakes": ["Confusing this consumer INZONE feature with 'Gaming Virtualizer by 360 Reality Audio', Sony's separate plug-in for game developers.", "Expecting it over Bluetooth; the feature relies on the USB/wired connection, not Bluetooth.", "Assuming it needs no setup; personalising it to your ears improves positional accuracy."], "scenario_contexts": ["Enabling spatial sound on INZONE headphones for a competitive FPS.", "Personalising the profile in INZONE Hub before a match.", "Judging an opponent's distance and direction purely by sound."], "formula_symbolic": "", "formula_words": ""}, {"id": "b922dee1-c6dc-492b-88f9-bcdca411d4eb", "term": "360 Virtual Mixing Environment", "definition": "360 Virtual Mixing Environment (360VME) is a Sony service and software that reproduces the acoustic field of an immersive multi-speaker studio on headphones. A personalised measurement captures how a specific engineer hears a chosen reference room; dedicated software then recreates that monitoring on headphones, supporting speaker setups up to 16 channels. Launched in 2023 through partner studios, it targets professionals producing immersive audio such as 360 Reality Audio. The name and technology are trademarks of Sony.", "plain_english": "This Sony service turns headphones into a virtual surround studio. Engineers first get measured in a real reference room. Their personal profile then makes headphones sound like that studio. This lets them mix immersive audio almost anywhere.", "purpose_function": "It provides portable, accurate immersive monitoring, so engineers are not tied to an expensive multi-speaker studio.", "practical_application": "A film or music engineer uses a 360VME profile to mix surround or immersive content on headphones between studio sessions.", "category": "Immersive Monitoring", "difficulty": "advanced", "achievement_id": "cad1c4e5-d4fb-4543-85f6-3fe985dcec45", "cross": [], "related_terms": ["360VME", "360 Reality Audio", "WalkMix Creator", "Head-related transfer function", "Immersive monitoring"], "common_mistakes": ["Expecting instant use; it requires a one-time in-studio measurement of the engineer.", "Believing it replaces treated rooms for all work; it emulates one specific reference studio.", "Confusing the monitoring tool with the 360 Reality Audio delivery format."], "scenario_contexts": ["Getting measured at a partner studio in New York, Los Angeles or Tokyo.", "Mixing immersive audio on headphones while travelling.", "Extending an immersive studio's monitoring to a second room."], "formula_symbolic": "", "formula_words": ""}, {"id": "ab5caa91-cd41-45e8-9ace-c8730e96801f", "term": "360VME", "definition": "360VME is the abbreviation for Sony's 360 Virtual Mixing Environment, a service and software that reproduces the acoustic field of an immersive multi-speaker studio over headphones. Using a personalised measurement of the individual engineer in a reference room, it recreates that studio's monitoring on headphones for immersive production such as 360 Reality Audio. The name and technology are trademarks of Sony.", "plain_english": "360VME is short for Sony's 360 Virtual Mixing Environment. It copies the sound of a real surround studio onto headphones. First, an engineer is measured in a reference studio. After that, their headphones mimic that room almost anywhere.", "purpose_function": "It lets engineers monitor immersive mixes accurately on headphones, without constant access to a costly multi-speaker room.", "practical_application": "A mixing engineer gets measured at a partner studio, then mixes immersive audio on headphones that emulate that room's speakers.", "category": "Immersive Monitoring", "difficulty": "advanced", "achievement_id": "cad1c4e5-d4fb-4543-85f6-3fe985dcec45", "cross": [], "related_terms": ["360 Virtual Mixing Environment", "360 Reality Audio", "WalkMix Creator", "Head-related transfer function", "Binaural monitoring"], "common_mistakes": ["Thinking it is a headphone EQ preset; it is a personalised studio measurement.", "Assuming any headphones give the same result; the profile is measured for a specific person and room.", "Confusing monitoring (360VME) with the delivery format (360 Reality Audio)."], "scenario_contexts": ["Booking a 360VME measurement session at a partner studio.", "Mixing immersive audio on the road using a 360VME headphone profile.", "Checking an immersive mix's translation before final delivery."], "formula_symbolic": "", "formula_words": ""}, {"id": "5771eb55-75f1-43a0-aa5a-5fcb782fb902", "term": "WalkMix Creator", "definition": "WalkMix Creator (styled 360 WalkMix Creator) is Sony's digital audio workstation plug-in for authoring 360 Reality Audio content. It lets engineers pan audio objects in a full 360-degree spherical field (up to 128 objects), monitor over headphones or virtual speaker layouts, and encode to the MPEG-H 3D Audio based 360 Reality Audio Music Format. Renamed from '360 Reality Audio Creative Suite' in January 2022, it was co-developed by Sony and Virtual Sonics (distributed via Audio Futures). The name and technology are trademarks of Sony.", "plain_english": "WalkMix Creator is Sony's tool for making 360 Reality Audio music. It runs as a plug-in inside recording software. Engineers place each sound around a 3D sphere, then export it in Sony's format. It uses object-based mixing and the shared MPEG-H standard.", "purpose_function": "It gives creators an in-DAW way to mix and encode object-based 360 Reality Audio without a dedicated immersive studio.", "practical_application": "An immersive-music engineer positions instrument objects on its 3D panner and exports MPEG-H deliverables for streaming platforms.", "category": "Immersive Authoring Tool", "difficulty": "advanced", "achievement_id": "cad1c4e5-d4fb-4543-85f6-3fe985dcec45", "cross": [], "related_terms": ["360 Reality Audio Creative Suite", "360 Reality Audio", "MPEG-H 3D Audio", "Object-based audio", "Vector Base Amplitude Panning"], "common_mistakes": ["Calling it by its old name; '360 Reality Audio Creative Suite' was renamed WalkMix Creator in 2022.", "Confusing the authoring plug-in with the 360 Reality Audio playback format.", "Assuming exported objects map to fixed channels; they carry position metadata independent of the speaker layout."], "scenario_contexts": ["Mixing an immersive music track and exporting a 360 Reality Audio deliverable.", "Monitoring an object mix over headphones before speaker playback.", "Encoding a session to different MPEG-H object counts for delivery."], "formula_symbolic": "", "formula_words": ""}, {"id": "a7d067dc-3abd-4c8e-bcc8-d7e9137b7459", "term": "ACID Loop Metadata", "definition": "ACID loop metadata is tempo, key, and stretch information embedded inside an audio file so a loop conforms automatically to a project's tempo and key. It typically stores the number of beats, a root note, and time-stretch/slice markers that ACID software reads on playback. ACID is a trademark of MAGIX (formerly Sony Creative Software, originally Sonic Foundry); the underlying approach is generic tagged-loop metadata.", "plain_english": "It is extra information saved inside a loop file. It tells the software the loop's speed, key, and beat points. The program uses that data to stretch the loop to your song. This lets loops fit together without hand-tuning.", "purpose_function": "It lets loops adapt to any project tempo and key automatically, removing manual time-stretching and pitch-shifting. This is what makes fast loop-based composition possible.", "practical_application": "A technician checks or edits this metadata, such as beat count, root note, and stretch markers, so a loop plays in time and in tune when dropped into a session.", "category": "Loop Technology", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["ACIDized Loop", "Beatmapped Track", "Groove Mapping", "Root Note", "Time Stretching"], "common_mistakes": ["Assuming the metadata changes the audio itself; it only tells the software how to stretch or transpose playback.", "Forgetting to set a root note, so the loop will not transpose to the project key.", "Confusing loop metadata with a Beatmapped file, which stores tempo for longer recordings instead."], "scenario_contexts": ["Preparing a loop library so every file drops in at the project tempo.", "Troubleshooting a loop that will not follow tempo because its beat count is wrong.", "Setting a root note so a bass loop transposes correctly with key changes."], "formula_symbolic": "", "formula_words": ""}, {"id": "4b3038db-6991-4ce1-a4bf-6e5f2a32d2b9", "term": "ACID Media Manager", "definition": "The ACID Media Manager is a built-in database tool for tagging, cataloguing, and searching audio media such as loops and one-shots. Users locate files by attributes like genre, instrument, or keyword and preview them in time with the current project. Media Manager is a component of ACID, a trademark of MAGIX (formerly Sony Creative Software); it applies a generic tagged media-library approach.", "plain_english": "It is a search tool for your sound library. You can label loops with tags like genre or instrument. Then you type a search to find the right sound fast. It also plays previews in time with your song.", "purpose_function": "It helps a user organize and quickly find sounds in large loop collections, speeding up loop-based composition.", "practical_application": "An engineer tags a loop library and searches by instrument or keyword to audition matching loops without leaving the project.", "category": "Media Management", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["ACIDized Loop", "Explorer Window", "One-Shot", "Loop Library", "Beatmapped Track"], "common_mistakes": ["Expecting search results before files are tagged or indexed into the database.", "Confusing Media Manager with the Explorer window, which only browses folders without tag-based search.", "Assuming previewed loops always match tempo when a loop lacks correct ACID metadata."], "scenario_contexts": ["Searching a large sample pack for a specific drum loop by keyword.", "Tagging a new sound-effects collection so it is searchable later.", "Auditioning several bass loops in time with the current project before choosing one."], "formula_symbolic": "", "formula_words": ""}, {"id": "cf5a46c9-7fae-4505-9561-427558484ba7", "term": "ACIDized Loop", "definition": "An ACIDized loop is an audio file saved with embedded ACID metadata, including tempo, beat count, root note, and stretch markers, so it automatically matches a project's tempo and key. The software time-stretches and transposes it on playback without altering the source file. 'ACIDized' derives from ACID, a trademark of MAGIX (formerly Sony Creative Software, originally Sonic Foundry); the method is a form of generic elastic-audio loop tagging.", "plain_english": "It is a loop file prepared to follow your song automatically. Saved information tells the program its speed and key. Drop it in and it stretches to your tempo. It also shifts to your song's key by itself.", "purpose_function": "It exists so loops from different sources play together in tempo and key, enabling fast, flexible loop-based arranging.", "practical_application": "A producer drags ACIDized drum, bass, and guitar loops onto tracks and they all lock to the project tempo instantly.", "category": "Loop Technology", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["ACID Loop Metadata", "Beatmapped Track", "One-Shot", "Time Stretching", "Groove Mapping"], "common_mistakes": ["Thinking any audio file is ACIDized; only files with saved ACID metadata follow tempo.", "Stretching a loop far beyond its natural tempo, which causes audible artifacts.", "Not setting the root note, so the loop stays at its original pitch during key changes."], "scenario_contexts": ["Building a song from mixed-source loops that must share one tempo.", "Converting a plain WAV loop into an ACIDized loop for reuse.", "Changing project tempo mid-session and hearing all loops re-stretch automatically."], "formula_symbolic": "", "formula_words": ""}, {"id": "d6100420-f2a5-4431-8d29-7f537c918135", "term": "Acoustic Mirror", "definition": "Acoustic Mirror is a convolution-based effect in Sound Forge that applies the recorded acoustic signature, or impulse response, of a real space, device, or microphone to audio. By convolving the signal with an impulse file, it reproduces that environment's reverberation and coloration. Acoustic Mirror is a trademark feature of Sound Forge, owned by MAGIX (formerly Sony Creative Software, originally Sonic Foundry); it uses generic convolution processing.", "plain_english": "It copies the sound of a real room and adds it to your audio. It works from a recording of how a space echoes, called an impulse. Your sound then seems to play in that room. It can even mimic old microphones or speakers.", "purpose_function": "It lets an engineer place dry audio into a realistic acoustic space or emulate hardware, using measured impulse responses rather than a synthetic reverb algorithm.", "practical_application": "A technician convolves a dry voice-over with a concert-hall impulse file to make it sound recorded in that hall.", "category": "Convolution Effect", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["Impulse Response", "Convolution Reverb", "Wave Hammer", "Plug-In Chainer", "Reverb"], "common_mistakes": ["Confusing convolution reverb with algorithmic reverb; Acoustic Mirror replays a measured space, not a synthetic one.", "Using a very long impulse file, which greatly increases processing time.", "Applying it to an already reverberant recording, which muddies the result."], "scenario_contexts": ["Matching dialogue re-recorded in a booth to the ambience of a location scene.", "Adding a real cathedral's reverberation to a dry choir recording.", "Emulating a vintage microphone response from its impulse file."], "formula_symbolic": "", "formula_words": ""}, {"id": "f815d4bd-72b5-48f8-835b-f4e248f30f4d", "term": "Auto Trim/Crop", "definition": "Auto Trim/Crop is a Sound Forge process that automatically removes silence or low-level audio from the start and end of a file (and optionally between phrases), based on a level threshold. It can also apply fades and tighten selections without manual editing. Auto Trim/Crop is a feature of Sound Forge, a trademark of MAGIX (formerly Sony Creative Software); it performs generic threshold-based silence trimming.", "plain_english": "It cuts silence off the beginning and end of a clip for you. You set a loudness level that counts as silence. Anything quieter gets trimmed away. This saves editing each file by hand.", "purpose_function": "It speeds up cleanup of many files by removing dead air automatically, using a level threshold instead of hand-editing.", "practical_application": "An editor batch-processes voice recordings so each file starts and ends right at the speech, with no leading or trailing silence.", "category": "Audio Editing", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["Trim/Crop", "Threshold", "Batch Processing", "Fade In/Out", "Playlist/Cutlist"], "common_mistakes": ["Setting the threshold too high, which clips off the quiet start of words.", "Setting it too low, so background noise is kept as if it were signal.", "Assuming it removes silence in the middle by default; that needs the right option enabled."], "scenario_contexts": ["Cleaning hundreds of sound-effect files before importing to a sampler.", "Trimming dead air from podcast segments in a batch.", "Preparing dialogue takes so each begins exactly at the first word."], "formula_symbolic": "", "formula_words": ""}, {"id": "18f1c013-def8-4f7a-a362-8d62854404fe", "term": "Beatmapped Track", "definition": "A Beatmapped track is a track in ACID whose audio, usually a file longer than about 30 seconds such as a full song, has had tempo information mapped to it so the software can follow or adjust its tempo. It is created with the Beatmapper and behaves differently from short ACIDized loops. Beatmapper is a feature of ACID, a trademark of MAGIX (formerly Sony Creative Software); it applies generic tempo-mapping.", "plain_english": "It is a long recording that the program has learned the beat of. You mark where the beats fall, usually for a whole song. Then the software can follow or change its tempo. This is different from short looped clips.", "purpose_function": "It lets long recordings sit in tempo with a project so loops and edits line up to the beat of a full song.", "practical_application": "A remixer beatmaps an imported full track so added loops and cuts land on its beats.", "category": "Tempo Mapping", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["Beatmapper", "ACIDized Loop", "Tempo", "Groove Mapping", "Downbeat"], "common_mistakes": ["Beatmapping short loops that should be ACIDized instead, which complicates the project.", "Placing the first downbeat marker wrong, so the whole map drifts off the beat.", "Expecting to apply grooves to a Beatmapped track; grooves cannot be applied to them."], "scenario_contexts": ["Importing a finished song to remix and aligning new parts to its beats.", "Syncing a long DJ recording to a project's tempo grid.", "Mapping a live band recording that drifts in tempo."], "formula_symbolic": "", "formula_words": ""}, {"id": "5ce4f76b-c0ff-456f-8b33-8497476fb2a5", "term": "Beatmapper", "definition": "The Beatmapper is a wizard in ACID that adds tempo information to a longer audio file (typically over 30 seconds) by having the user mark the first downbeat and the length of one measure. It then maps beats across the file, creating a Beatmapped track. Beatmapper is a feature of ACID, a trademark of MAGIX (formerly Sony Creative Software, originally Sonic Foundry); it uses generic beat/tempo mapping.", "plain_english": "It is a step-by-step tool for finding a song's beat. You mark the first strong beat and one bar's length. The tool then maps the beats through the whole file. Now the recording can follow your project's tempo.", "purpose_function": "It exists to give long recordings usable tempo data so they can be arranged and synced like loops.", "practical_application": "When a technician drags in a file over 30 seconds, the Beatmapper opens to mark the downbeat and measure so the file follows tempo.", "category": "Tempo Mapping", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["Beatmapped Track", "ACIDized Loop", "Tempo", "Downbeat", "Measure"], "common_mistakes": ["Mis-marking the downbeat, which throws the whole beat map off.", "Setting the wrong number of beats per measure for the song's time signature.", "Using the Beatmapper on short clips that are better handled as ACIDized loops."], "scenario_contexts": ["Adding tempo data to an imported full-length song before remixing.", "Preparing a long recording so a click and loops align to it.", "Correcting a beat map when added loops drift out of time."], "formula_symbolic": "", "formula_words": ""}, {"id": "aed35752-369a-453c-9a85-480a656f0d0a", "term": "Chopper", "definition": "The Chopper is a tool in ACID that dissects a loop into smaller slices and inserts those cut sections onto a track, letting the user build new rhythmic patterns, fills, and glitch or stutter effects. It operates on a single loop, using slice points and keyboard shortcuts for fast placement. Chopper is a feature of ACID, a trademark of MAGIX (formerly Sony Creative Software); it is a form of generic beat slicing.", "plain_english": "It cuts a loop into small pieces you can rearrange. You pick slices and drop them onto the track. This lets you build fills, stutters, and glitch effects. It is a fast way to make new rhythms from one loop.", "purpose_function": "It gives an arranger quick control over slicing and re-triggering parts of a loop to create variation and rhythmic effects.", "practical_application": "A producer uses the Chopper to slice a drum loop and place stutter hits for a fill before a chorus.", "category": "Loop Editing", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["ACIDized Loop", "Beatmapped Track", "Groove Mapping", "Slice", "Quantization"], "common_mistakes": ["Chopping off the beat grid, so inserted slices sound out of time.", "Expecting the Chopper to work across many tracks; it dissects one loop at a time.", "Overusing stutter slices, which clutters the groove."], "scenario_contexts": ["Building a drum fill by slicing and re-triggering a loop.", "Creating glitch and stutter effects in electronic music.", "Turning one loop into several rhythmic variations for an arrangement."], "formula_symbolic": "", "formula_words": ""}, {"id": "39405a84-9f53-48f5-bd67-ed29e67addb6", "term": "Groove Cloning", "definition": "Groove cloning in ACID is capturing the rhythmic timing, or feel, of an existing clip so it can be reused, letting a user cross-quantize the feel of one loop onto another to tighten or match the groove. The captured timing becomes a groove stored in the Groove Pool. Groove tools are features of ACID, a trademark of MAGIX (formerly Sony Creative Software); the concept is generic groove-template quantization.", "plain_english": "It copies the timing feel of one loop. You capture how its beats push or lag. Then you stamp that feel onto another loop. This makes different parts share the same groove.", "purpose_function": "It lets an arranger match the rhythmic feel across parts, or tighten loose timing, by reusing a captured groove.", "practical_application": "An engineer clones the swing of a drum loop and applies it to a bass loop so both sit in the same pocket.", "category": "Groove Quantization", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["Groove Mapping", "Groove Pool", "Quantization", "ACIDized Loop", "Chopper"], "common_mistakes": ["Confusing groove cloning with a strict grid quantize; cloning copies a feel, not a rigid grid.", "Cloning a groove from a poorly timed loop, which spreads its errors.", "Trying to clone grooves onto Beatmapped tracks, which do not accept grooves."], "scenario_contexts": ["Making a bass line share the swing of a drum groove.", "Tightening a loose loop by applying a cleaner loop's feel.", "Unifying the timing feel across several loops in a track."], "formula_symbolic": "", "formula_words": ""}, {"id": "15c2b4d7-5da6-47cf-b1b1-4ce20c0b1c5d", "term": "Groove Mapping", "definition": "Groove mapping in ACID is applying a groove, a stored pattern of timing offsets from the Groove Pool, to a loop, one-shot, or MIDI track to adjust its rhythmic timing and feel. Dragging a groove onto a track shows a groove lane indicating the applied quantization. Grooves are a feature of ACID, a trademark of MAGIX (formerly Sony Creative Software); the concept is generic groove-template quantization.", "plain_english": "It applies a saved timing pattern to a track. You drag a groove onto the loop. The loop's beats then shift to follow that feel. A lane appears to show the change.", "purpose_function": "It exists to change or tighten the rhythmic feel of parts using reusable groove templates instead of fixed grid quantizing.", "practical_application": "A producer drags a shuffle groove from the Groove Pool onto straight loops to give the whole track a swing feel.", "category": "Groove Quantization", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["Groove Cloning", "Groove Pool", "Quantization", "ACIDized Loop", "Beatmapped Track"], "common_mistakes": ["Applying grooves to Beatmapped tracks; grooves cannot be applied to them.", "Expecting the metronome to follow the groove; the metronome ignores applied grooves.", "Stacking heavy grooves that fight the music's natural feel."], "scenario_contexts": ["Adding swing to straight programmed loops.", "Matching several loops to one shared groove template.", "Loosening rigid, machine-tight loops for a more human feel."], "formula_symbolic": "", "formula_words": ""}, {"id": "f1a45dde-ff10-4f08-84d7-783bd2c3c40e", "term": "Playlist/Cutlist", "definition": "In Sound Forge, the Playlist is a list of regions arranged in a chosen order for non-destructive playback and to build a new file, while the Cutlist is the Playlist configured so listed regions are skipped (cut) during playback. Both let a user audition edits without altering the original file. Playlist/Cutlist are features of Sound Forge, a trademark of MAGIX (formerly Sony Creative Software); they apply a generic non-destructive edit-list approach.", "plain_english": "The Playlist plays chosen regions in an order you set, without changing the file. You can build a new file from that order. In Cutlist mode, the listed regions are skipped instead. Both let you try edits safely first.", "purpose_function": "They allow non-destructive arranging and trial edits of regions before committing to a rendered file.", "practical_application": "An editor arranges takes as playlist regions to preview a sequence, then renders it to a new file once satisfied.", "category": "Audio Editing", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["Region", "Auto Trim/Crop", "Trim/Crop", "Marker", "Non-Destructive Editing"], "common_mistakes": ["Forgetting the playlist is non-destructive; the source file is unchanged until you render.", "Confusing cutlist mode (skips regions) with actually deleting audio.", "Not saving the region markers the playlist depends on."], "scenario_contexts": ["Sequencing dialogue takes to preview an edit before rendering.", "Removing bad sections by skipping them in cutlist mode.", "Assembling regions into a new file for delivery."], "formula_symbolic": "", "formula_words": ""}, {"id": "89ca428a-9b5e-4d25-b2bb-d1059bfee679", "term": "Plug-In Chainer", "definition": "The Plug-In Chainer in Sound Forge lets a user combine multiple effects plug-ins into a signal chain processed in series, with control over processing order, real-time preview during playback, and the ability to save the chain as a preset. Plug-ins are processed in the listed order. The Plug-In Chainer is a feature of Sound Forge, a trademark of MAGIX (formerly Sony Creative Software); it is a generic serial effects-chain host.", "plain_english": "It runs several effects one after another on your audio. You add plug-ins and set their order. The sound passes through each in turn. You can preview it live and save the chain to reuse.", "purpose_function": "It exists to apply and audition a whole processing chain at once, since effect order changes the final sound.", "practical_application": "An engineer builds an EQ, compressor, and limiter chain, previews it, and saves it as a mastering preset.", "category": "Effects Processing", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["Wave Hammer", "Acoustic Mirror", "Signal Chain", "Preset", "DirectX Plug-In"], "common_mistakes": ["Ignoring plug-in order; effects in series sound different depending on their sequence.", "Stacking too many plug-ins, which can overload processing or over-cook the sound.", "Forgetting to bypass or remove a plug-in left in the chain by mistake."], "scenario_contexts": ["Creating a reusable mastering chain of EQ, compression, and limiting.", "Auditioning several effects together before rendering.", "Saving a favorite processing chain as a preset for future files."], "formula_symbolic": "", "formula_words": ""}, {"id": "94d3ea99-36d0-4958-bad4-42aa548be50a", "term": "Wave Hammer", "definition": "Wave Hammer is a mastering plug-in in Sound Forge that combines two stages: a compressor for dynamic-range control and a volume maximizer (a peak limiter) that raises overall loudness without clipping. It is applied to full mixes to add level and control dynamics. Wave Hammer is a trademark feature of Sound Forge, owned by MAGIX (formerly Sony Creative Software, originally Sonic Foundry); it uses generic compression and peak-limiting methods.", "plain_english": "It is a two-part tool for making a mix louder and more even. One part is a compressor that controls loud and quiet parts. The other raises the overall volume up to a safe ceiling. Together they help a track sound finished.", "purpose_function": "It exists to master a mix by controlling dynamics and maximizing loudness up to a set ceiling, all in one plug-in.", "practical_application": "An engineer places Wave Hammer on the master, compresses gently, then uses the volume maximizer to reach a target loudness without clipping.", "category": "Mastering", "difficulty": "intermediate", "achievement_id": "db6794e2-8b80-49a1-8ceb-67aea25280ba", "cross": [], "related_terms": ["Plug-In Chainer", "Compressor", "Limiter", "Loudness", "Acoustic Mirror"], "common_mistakes": ["Pushing the volume maximizer too hard, which crushes dynamics and adds distortion.", "Confusing the maximizer with a normal compressor; it is a peak limiter for loudness.", "UNSAFE: Mastering loud on monitors for long periods risks hearing damage; follow safe listening levels per OSHA 1910.95."], "scenario_contexts": ["Raising a finished mix to competitive loudness before release.", "Gently controlling dynamics on a master bus.", "Adding final level to a podcast or voice master."], "formula_symbolic": "", "formula_words": ""}, {"id": "63ae4ca7-c268-4c6d-8f7f-52250594db9d", "term": "ATRAC", "definition": "ATRAC (Adaptive Transform Acoustic Coding) is a lossy perceptual audio compression system Sony developed for the MiniDisc format. It splits the signal into three subbands using quadrature mirror filters (QMF), applies a signal-adaptive Modified Discrete Cosine Transform (MDCT), and discards spectral data rendered inaudible by psychoacoustic masking, reducing 44.1 kHz 16-bit stereo audio to roughly one-fifth of its original data rate. ATRAC is a Sony trademark; the underlying method is generic transform-based perceptual coding, the same broad concept used by MP3 and AAC.", "plain_english": "ATRAC is a way Sony shrank music to fit on MiniDiscs. It removes sounds your ears cannot hear anyway. The leftover audio is about five times smaller. This is the same basic trick that MP3 uses.", "purpose_function": "It exists to store near-CD-quality stereo audio in far less space, letting the small MiniDisc hold a full album. It relies on hearing-based masking rather than simple downsampling to decide what to remove.", "practical_application": "Technicians meet ATRAC when transferring, archiving, or playing back MiniDisc recordings on Sony decks and portable recorders. Knowing it is lossy warns against treating a MiniDisc copy as a bit-perfect master.", "category": "Perceptual Audio Codec", "difficulty": "intermediate", "achievement_id": "ab5f6383-b4af-499d-937d-c8cd9cab317f", "cross": [], "related_terms": ["ATRAC3", "ATRAC3plus", "MiniDisc", "MDCT", "Perceptual coding", "Lossy compression"], "common_mistakes": ["Believing ATRAC is lossless; it permanently discards masked audio data.", "Assuming ATRAC and ATRAC3 are the same codec, when ATRAC3 is a later, lower-bitrate design.", "Expecting a MiniDisc ATRAC copy to be a bit-perfect clone of the CD source."], "scenario_contexts": ["Archiving old MiniDisc field recordings made on a Sony portable recorder.", "Explaining to a client why a MiniDisc dub is not a master-quality copy.", "Comparing ATRAC to MP3 and AAC when teaching perceptual coding principles."], "formula_symbolic": "", "formula_words": ""}, {"id": "b709bea8-6f84-443d-891c-722a7bb2ab59", "term": "ATRAC3", "definition": "ATRAC3 is a lossy perceptual audio codec from Sony in the ATRAC family, a later-generation successor to the original MiniDisc ATRAC. Like its predecessor it uses transform coding with psychoacoustic masking, but targets lower bit rates for portable devices and Sony's SonicStage software library, and it can serve as a lossy base layer beneath ATRAC Advanced Lossless. ATRAC3 is a Sony trademark; the underlying technique is generic perceptual transform coding.", "plain_english": "ATRAC3 is a newer, smaller version of Sony's ATRAC music format. It squeezes songs harder so more fit on a device. Sony used it in its SonicStage software and portable players. Like ATRAC, it drops sounds you cannot hear.", "purpose_function": "It exists to pack more tracks into limited storage and portable players while keeping acceptable quality. It also forms one lossy core that ATRAC Advanced Lossless can rebuild to an exact copy.", "practical_application": "Technicians encounter ATRAC3 files when importing or converting libraries created in Sony's SonicStage software. Recognizing it as lossy guides correct handling during format migration.", "category": "Perceptual Audio Codec", "difficulty": "intermediate", "achievement_id": "ab5f6383-b4af-499d-937d-c8cd9cab317f", "cross": [], "related_terms": ["ATRAC", "ATRAC3plus", "ATRAC Advanced Lossless", "SonicStage", "Lossy compression", "Perceptual coding"], "common_mistakes": ["Treating ATRAC3 as lossless because Sony also offers a lossless format.", "Confusing ATRAC3 with ATRAC3plus, which is a later, more efficient codec.", "Assuming ATRAC3 files play on any device; playback needs ATRAC support."], "scenario_contexts": ["Migrating a SonicStage music library off an old Sony computer.", "Identifying an unknown Sony audio file during a studio archive cleanup.", "Explaining why an ATRAC3 file will not open in a generic media player."], "formula_symbolic": "", "formula_words": ""}, {"id": "37fdd52c-e07e-409f-b194-ea54c8cdadb2", "term": "ATRAC3plus", "definition": "ATRAC3plus (ATRAC3+) is a lossy perceptual audio codec from Sony that improves on ATRAC3 with higher coding efficiency. Sony's SonicStage software supports it at bit rates from 48 up to 320 kbps, and it is one of the lossy base formats on which ATRAC Advanced Lossless is built. ATRAC3plus is a Sony trademark; the underlying method is generic perceptual transform coding.", "plain_english": "ATRAC3plus is an improved version of Sony's ATRAC3 music format. It gives better sound at the same file size. Sony's SonicStage software could save it from 48 up to 320 kilobits per second. Higher numbers mean better quality and bigger files.", "purpose_function": "It exists to deliver better quality per kilobit than ATRAC3 across Sony's players and software. Its range of bitrate options lets users trade file size against sound quality.", "practical_application": "Technicians meet ATRAC3plus when handling files exported from SonicStage or stored on Sony portable players. The chosen bitrate tells them how heavily the audio was compressed.", "category": "Perceptual Audio Codec", "difficulty": "intermediate", "achievement_id": "ab5f6383-b4af-499d-937d-c8cd9cab317f", "cross": [], "related_terms": ["ATRAC", "ATRAC3", "ATRAC Advanced Lossless", "SonicStage", "Bit rate", "Lossy compression"], "common_mistakes": ["Assuming a higher ATRAC3plus bitrate makes the file lossless; it stays lossy.", "Confusing ATRAC3plus with ATRAC3; they are different-generation codecs.", "Expecting non-Sony players to decode ATRAC3plus files."], "scenario_contexts": ["Choosing an ATRAC3plus bitrate in SonicStage for a Sony portable player.", "Cataloguing mixed ATRAC3 and ATRAC3plus files in an old library.", "Troubleshooting playback of an ATRAC3plus file on unsupported software."], "formula_symbolic": "", "formula_words": ""}, {"id": "af01ddde-4dd5-4762-8782-adf341d3694b", "term": "ATRAC Advanced Lossless", "definition": "ATRAC Advanced Lossless is Sony's lossless audio compression technology, introduced in SonicStage 3.3, which reduces CD audio to about 30–80% of its original size with no loss of data. It uses a hybrid design: an ATRAC3 or ATRAC3plus lossy stream as a base plus additional correction data that reconstructs the exact original signal. The lossy base keeps files playable on devices that support ATRAC3/ATRAC3plus but not the lossless layer. It is a Sony trademark; the method is a generic lossy-core-plus-correction hybrid lossless approach.", "plain_english": "ATRAC Advanced Lossless is Sony's way to shrink music with zero quality loss. It stores a small lossy version plus extra data to rebuild the original exactly. Older Sony players can still play the lossy part. Sony added it in SonicStage 3.3, cutting CDs to roughly a third to four-fifths of their size.", "purpose_function": "It exists to give bit-perfect copies while staying backward compatible with players that only handle the lossy ATRAC layer. Users get archival quality without losing playback on older gear.", "practical_application": "Technicians meet it when a SonicStage library was saved in lossless form and must be migrated or decoded. Its hybrid structure explains why the same file can play in reduced quality on older devices.", "category": "Lossless Audio Codec", "difficulty": "intermediate", "achievement_id": "ab5f6383-b4af-499d-937d-c8cd9cab317f", "cross": [], "related_terms": ["ATRAC", "ATRAC3", "ATRAC3plus", "SonicStage", "Lossless compression", "Hybrid lossless"], "common_mistakes": ["Assuming the lossy base layer alone equals full lossless quality.", "Confusing ATRAC Advanced Lossless with plain ATRAC3, which is lossy.", "Thinking every Sony device plays the lossless layer; many decode only the lossy base."], "scenario_contexts": ["Recovering original-quality audio from a SonicStage lossless library.", "Explaining why a lossless Sony file also plays on an older lossy-only player.", "Planning a format migration off Sony's discontinued SonicStage ecosystem."], "formula_symbolic": "", "formula_words": ""}, {"id": "760d77f6-b587-4ceb-a31d-f4b9c987cdce", "term": "Super Bit Mapping", "definition": "Super Bit Mapping (SBM) is Sony's word-length reduction technology that converts a higher-resolution signal (such as 20-bit or 24-bit) down to 16-bit while applying psychoacoustic noise shaping. Instead of simply truncating the lower bits, it folds information from those bits into the 16-bit output and shifts the resulting quantization noise away from the frequency band where human hearing is most sensitive, preserving perceived dynamic range on 16-bit media such as CD and DAT. SBM is a Sony trademark; the underlying method is generic noise-shaped requantization.", "plain_english": "Super Bit Mapping is Sony's trick for shrinking studio audio to 16-bit cleanly. Plain cutting would add hiss and lose detail. Instead it hides the leftover noise where ears notice it least. This keeps CDs and DAT tapes sounding closer to the high-quality original.", "purpose_function": "It exists so a high-resolution recording can fit the 16-bit format of CD and DAT without obvious loss of detail or added audible noise. It maximizes usable dynamic range within 16 bits.", "practical_application": "Mastering technicians enable SBM on Sony recorders and processors when bouncing a 20-bit or 24-bit master down to a 16-bit CD or DAT. It replaces plain truncation with a noise-shaped conversion.", "category": "Mastering Technology", "difficulty": "intermediate", "achievement_id": "ab5f6383-b4af-499d-937d-c8cd9cab317f", "cross": [], "related_terms": ["Dither", "Noise shaping", "Quantization", "Bit depth", "Word length", "DAT"], "common_mistakes": ["Thinking SBM adds resolution; it only optimizes the reduction to 16 bits.", "Believing SBM makes a 16-bit file identical to the 24-bit master.", "Truncating instead of noise-shaping, which raises audible quantization noise.", "Confusing SBM with lossy data compression like ATRAC; SBM is a requantization stage."], "scenario_contexts": ["Mastering a 24-bit mix down to a 16-bit CD on a Sony workflow.", "Recording to DAT from a high-resolution source with SBM engaged.", "Explaining why a noise-shaped 16-bit bounce sounds cleaner than a truncated one."], "formula_symbolic": "", "formula_words": ""}, {"id": "d01dec00-e6c8-4283-839c-63947d276faf", "term": "Acoustic Center Sync", "definition": "Acoustic Center Sync is a Sony proprietary feature that lets a compatible Sony BRAVIA TV act as the center-channel speaker for a paired Sony sound bar or home-theater system. The TV's own screen-vibration or panel speakers reproduce center-channel audio, chiefly dialogue, so voices appear to come directly from the on-screen image. It connects through a dedicated S-Center Speaker Input and is offered on Sony TV models from 2021 onward.", "plain_english": "This Sony feature turns the TV itself into the middle speaker of a surround setup. It works with a matching Sony sound bar or receiver. Voices then seem to come straight from the person on the screen. You link the TV and sound bar with one cable to the S-Center input.", "purpose_function": "It exists to lock dialogue to the picture, so voices appear to come from the screen instead of from a sound bar below it. Using the TV as the center speaker also removes the need for a separate center speaker.", "practical_application": "An installer connects a compatible Sony sound bar to the TV's S-Center Speaker Input, enables Acoustic Center Sync in the audio menu, and confirms dialogue tracks the on-screen action.", "category": "Home Theater Audio", "difficulty": "intermediate", "achievement_id": "8e64f666-6caa-4db7-be98-340aeb6c7a78", "cross": [], "related_terms": ["Acoustic Surface Audio+", "Center Channel", "Sound Bar", "Vertical Surround Engine", "Dolby Atmos"], "common_mistakes": ["Assuming it works with any brand; it needs a compatible Sony TV and a compatible Sony audio system.", "confusing it with using the TV speakers alone, when here the TV only handles the center channel and the sound bar handles the rest.", "forgetting the dedicated S-Center cable connection, so the feature cannot be enabled."], "scenario_contexts": ["Setting up a Sony BRAVIA TV with a Sony HT-A series sound bar so dialogue comes from the screen.", "an installer wiring the S-Center Speaker Input during a living-room home-theater install.", "troubleshooting audio delay after enabling the feature so lip-sync stays correct."], "formula_symbolic": "", "formula_words": ""}, {"id": "fe460233-f4f8-4298-b18c-f87c81fdaa1f", "term": "Acoustic Surface Audio+", "definition": "Acoustic Surface Audio+ is a Sony proprietary sound technology used in certain Sony OLED TVs. Actuators mounted behind the screen vibrate the display panel itself so the surface radiates sound, joined by side-firing subwoofers for bass. On the A9F Master Series it uses three actuators and two subwoofers for a 3.2-channel system, and the panel can serve as the center speaker of a larger home-theater setup.", "plain_english": "Sony makes some OLED TVs where the screen itself makes the sound. Small vibrating parts behind the panel shake it to create audio. Extra subwoofers add deep bass. Because the sound comes from the picture, voices seem to match where people appear on screen.", "purpose_function": "It removes the need for separate front-facing TV speakers and makes sound appear to come straight from the image, improving how well the audio lines up with the picture.", "practical_application": "A technician calibrating a Sony OLED home theater can enable the TV's center-speaker mode so the vibrating screen reproduces the center channel for a connected sound bar or receiver.", "category": "TV Screen Sound", "difficulty": "intermediate", "achievement_id": "8e64f666-6caa-4db7-be98-340aeb6c7a78", "cross": [], "related_terms": ["Acoustic Center Sync", "Center Channel", "Subwoofer", "Sound Bar", "Dolby Atmos"], "common_mistakes": ["Thinking the sound comes from grilles or drivers at the edges, when the screen panel itself is the speaker.", "assuming every Sony OLED has the 'plus' version; the added center actuator and 3.2-channel layout are on specific models such as the A9F.", "expecting deep bass from the panel alone, when the side-firing subwoofers handle low frequencies."], "scenario_contexts": ["Evaluating a Sony Master Series OLED where dialogue must track on-screen characters.", "using the OLED panel as the center channel in a home-theater system.", "explaining to a client why the TV needs no visible front speaker."], "formula_symbolic": "", "formula_words": ""}, {"id": "9e5a0435-489e-48f8-9630-b257d61f0e38", "term": "Immersive Audio Enhancement", "definition": "Immersive Audio Enhancement is a Sony proprietary sound-mode setting on Sony sound bars and home-theater systems. It processes incoming audio so sound seems to come from above as well as from the horizontal plane, extending immersive playback. Sony states it also works on 2.0-channel (stereo) signals such as ordinary TV programs, not only object-based formats.", "plain_english": "This Sony setting spreads sound so it feels like it comes from above you, not just the sides. It works even with plain stereo, like normal TV shows. The aim is a more surrounding, movie-like effect. You switch it on in the sound bar's audio menu.", "purpose_function": "It exists to add a sense of height and envelopment to content that was not mixed with overhead channels, widening the perceived sound field.", "practical_application": "A technician enables Immersive Audio Enhancement on a Sony HT-A series sound bar so standard broadcasts and stereo sources gain an overhead, immersive feel.", "category": "Virtual Surround", "difficulty": "intermediate", "achievement_id": "8e64f666-6caa-4db7-be98-340aeb6c7a78", "cross": [], "related_terms": ["Vertical Surround Engine", "S-Force PRO Front Surround", "Dolby Atmos", "360 Spatial Sound Mapping", "Sound Bar"], "common_mistakes": ["Believing it adds true overhead channels, when it creates a virtual height effect through processing.", "assuming it only works with Dolby Atmos, when Sony states it also processes ordinary stereo content.", "leaving it on for critical stereo music listening, where it can change the intended balance."], "scenario_contexts": ["Watching a standard TV broadcast on a Sony sound bar with an added height effect.", "comparing sound modes during a home-theater demo for a customer.", "setting default audio processing during a residential AV install."], "formula_symbolic": "", "formula_words": ""}, {"id": "ef5ab680-a9ce-4d36-80c4-ceb6c742110d", "term": "S-Force PRO Front Surround", "definition": "S-Force PRO Front Surround is Sony's proprietary virtual surround technology. It uses digital sound-field processing to make front-facing speakers reproduce a surround effect, with audio appearing to arrive from the sides, without physical rear or side speakers. It is common on Sony sound bars and compact home-theater systems.", "plain_english": "This Sony technology creates surround sound using only the front speakers. Clever signal processing makes audio seem to come from your sides. So you get a surround feel without placing speakers behind you. It is built into many Sony sound bars.", "purpose_function": "It exists to deliver a surround-sound experience in rooms or products where installing rear speakers is impractical.", "practical_application": "A technician recommends a Sony sound bar using S-Force PRO Front Surround for a client who wants cinematic sound but cannot run wiring to rear speakers.", "category": "Virtual Surround", "difficulty": "intermediate", "achievement_id": "8e64f666-6caa-4db7-be98-340aeb6c7a78", "cross": [], "related_terms": ["Vertical Surround Engine", "Immersive Audio Enhancement", "Sound Bar", "Phantom Image", "Dolby Atmos"], "common_mistakes": ["Expecting it to match true discrete rear speakers, when it is a virtual, processed effect.", "confusing its horizontal side-surround effect with the overhead effect from Vertical Surround Engine.", "assuming the effect is identical in every room, when placement and reflections change the result."], "scenario_contexts": ["Choosing a 2.1 Sony sound bar for a bedroom where rear speakers are not possible.", "demonstrating virtual surround from a single front bar to a customer.", "configuring sound modes on a compact Sony home-theater system."], "formula_symbolic": "", "formula_words": ""}, {"id": "46138d37-9918-4fe1-9e7d-9b4a1c0a83cb", "term": "Sound Field Optimization", "definition": "Sound Field Optimization is a Sony proprietary calibration feature on Sony sound bars and home-theater systems. It uses built-in microphones to measure the relative height and position of the sound bar and any rear speakers, then adjusts the audio output to suit that layout. It supports Sony's spatial-audio processing such as 360 Spatial Sound Mapping.", "plain_english": "This Sony feature measures where your speakers sit in the room. It uses tiny built-in microphones to check their height and position. Then it tunes the sound to match that layout. This helps the surround effect stay accurate for your setup.", "purpose_function": "It exists to automatically tailor spatial-audio processing to the actual speaker positions, so virtual and height effects are placed correctly.", "practical_application": "During install, a technician runs Sound Field Optimization so the Sony system measures the sound bar and rear-speaker positions before fine-tuning surround performance.", "category": "Room Calibration", "difficulty": "intermediate", "achievement_id": "8e64f666-6caa-4db7-be98-340aeb6c7a78", "cross": [], "related_terms": ["360 Spatial Sound Mapping", "Vertical Surround Engine", "Sound Bar", "Immersive Audio Enhancement", "Rear Speakers"], "common_mistakes": ["Skipping the calibration after moving speakers, leaving the sound field mis-tuned.", "blocking the built-in microphones or running it in a noisy room, which can cause measurement to fail.", "assuming it treats room acoustics, when it optimizes for speaker position rather than full room treatment."], "scenario_contexts": ["Calibrating a Sony HT-A soundbar with wireless rear speakers after placement.", "re-running optimization after rearranging living-room furniture and speakers.", "diagnosing why 360 Spatial Sound Mapping is not performing as expected."], "formula_symbolic": "", "formula_words": ""}, {"id": "78089bdc-929c-4d87-aa02-63d3907e9a38", "term": "Vertical Surround Engine", "definition": "Vertical Surround Engine is a Sony proprietary digital sound-processing technology on Sony sound bars and home-theater systems. It enhances the surround and height channels to create a virtual overhead surround effect without physical ceiling or height speakers. It commonly works together with S-Force PRO Front Surround, which supplies the horizontal side-surround effect.", "plain_english": "This Sony technology creates the feeling of sound coming from above. It does this without any speakers on the ceiling. It processes the audio to add virtual height. It usually teams up with Sony's front-surround technology for a fuller effect.", "purpose_function": "It exists to add a virtual height dimension to surround sound, helping content feel three-dimensional even from a single sound bar.", "practical_application": "A technician enables Vertical Surround Engine on a Sony sound bar so overhead effects in movies are simulated without installing height speakers.", "category": "Virtual Surround", "difficulty": "intermediate", "achievement_id": "8e64f666-6caa-4db7-be98-340aeb6c7a78", "cross": [], "related_terms": ["S-Force PRO Front Surround", "Immersive Audio Enhancement", "Dolby Atmos", "360 Spatial Sound Mapping", "Sound Bar"], "common_mistakes": ["Thinking it needs ceiling speakers, when the height effect is virtual and processed.", "confusing its vertical, overhead effect with the horizontal side surround from S-Force PRO Front Surround.", "expecting it to equal true Dolby Atmos height channels driven by in-ceiling speakers."], "scenario_contexts": ["Enabling overhead effects on a Sony sound bar in a room with no ceiling speakers.", "comparing virtual height performance during a home-theater demonstration.", "explaining to a client the difference between virtual and physical height channels."], "formula_symbolic": "", "formula_words": ""}, {"id": "1069b1b4-d0bb-404a-8f08-9537c9921dd4", "term": "Adaptive Sound Control", "definition": "Adaptive Sound Control is a Sony proprietary feature in the Sony | Headphones Connect (Sound Connect) app that automatically switches a headphone's noise-canceling and ambient-sound settings based on the wearer's detected activity or location. It recognizes action patterns (staying, walking, running, riding a vehicle) or registered/frequently visited places and applies a matching preset. The name is a Sony trademark; the underlying method is context/activity detection using the paired phone's motion and location sensors.", "plain_english": "This is a Sony phone-app feature for its headphones. It notices if you are sitting, walking, running, or riding. Then it changes the noise settings to fit that moment. Sony owns the name. The idea is simple activity and location sensing.", "purpose_function": "It exists to change noise-canceling and ambient settings automatically as the user moves between environments, so they need not adjust settings by hand.", "practical_application": "A technician enables it in the app so a customer's headset opens up ambient sound when they start walking and blocks noise when seated.", "category": "Noise Control Feature", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Ambient Sound Mode", "Auto Noise Canceling Optimizer", "Speak-to-Chat", "Quick Attention", "Active Noise Cancellation"], "common_mistakes": ["Thinking it is a hardware chip; it runs in the Sony app using the phone's sensors.", "Confusing it with Auto NC Optimizer, which adjusts for fit and air pressure, not activity.", "Assuming it works without the paired app and its motion/location permissions."], "scenario_contexts": ["Commuter's headphones switch to ambient sound when they leave the office and start walking.", "Registering a gym location so noise canceling changes when the user arrives.", "Demonstrating hands-free setting changes during a retail product comparison."], "formula_symbolic": "", "formula_words": ""}, {"id": "96a685f5-0c6d-460c-b586-fcea55bdef58", "term": "Auto Noise Canceling Optimizer", "definition": "Auto Noise Canceling Optimizer (Auto NC Optimizer) is a Sony proprietary function that continuously and automatically optimizes a headphone's noise-canceling performance based on wearing conditions (face shape, hairstyle, glasses) and external factors such as atmospheric pressure. It runs without the wearer pressing any button. The name is a Sony trademark; the underlying method is adaptive tuning of the active-noise-canceling filter.", "plain_english": "Sony headphones fit every head a little differently. Air pressure also changes, like on a plane. This Sony feature keeps checking those conditions on its own. It then adjusts the noise blocking to stay its best, with no button press.", "purpose_function": "It exists to keep active noise cancellation working at its best as fit and air pressure change, without the user re-tuning it manually.", "practical_application": "On a flight, the headset re-optimizes noise canceling as cabin pressure changes so blocking stays effective.", "category": "Noise Control Feature", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Personal Noise Canceling Optimizer", "Active Noise Cancellation", "Dual Noise Sensor Technology", "Adaptive Sound Control", "Atmospheric Pressure"], "common_mistakes": ["Confusing it with Personal NC Optimizer, which is a one-time manual test, not continuous.", "Thinking a fluctuating noise-canceling effect is a fault; it reflects ongoing optimization.", "Expecting it to improve the ear seal; it tunes filtering, not fit."], "scenario_contexts": ["Air travel where cabin pressure shifts during climb and descent.", "A user wearing glasses whose seal differs from a bare-head fit.", "Comparing older manual-optimizer models with newer automatic ones."], "formula_symbolic": "", "formula_words": ""}, {"id": "1743953d-101a-4714-a59d-18be73a65359", "term": "Clear Bass", "definition": "Clear Bass is a Sony proprietary low-frequency level control, offered in the Sony | Headphones Connect app and on Walkman players, that adjusts bass output separately from the main equalizer bands. Sony states that raising the Clear Bass value reproduces deep bass without distortion, even at high volume. The name is a Sony trademark; the underlying method is a dedicated bass (low-frequency) equalizer adjustment.", "plain_english": "Clear Bass is a Sony bass control. It sits apart from the normal equalizer sliders. Turn it up to get deeper, stronger low sounds. Sony says the bass stays clean even when loud.", "purpose_function": "It exists to let users boost low-frequency response on its own, adding bass weight without muddying the rest of the sound.", "practical_application": "A technician tuning a customer's earbuds raises Clear Bass a few steps to add low end for bass-heavy music.", "category": "Sound Tuning", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Equalizer", "Find Your Equalizer", "ClearAudio+", "Frequency Response", "Low Frequency"], "common_mistakes": ["Treating Clear Bass as the same as the equalizer's low band; it is a separate control.", "Maxing it out and causing muddiness rather than clean bass.", "Assuming it adds subwoofer-level output on small earbuds."], "scenario_contexts": ["Adjusting bass on Sony earbuds for a customer who likes bass-heavy genres.", "Setting Clear Bass on a Walkman alongside a genre preset.", "Balancing Clear Bass against a custom equalizer profile."], "formula_symbolic": "", "formula_words": ""}, {"id": "d7ec3fad-56f5-45eb-ab18-0fae6038b004", "term": "Clear Phase", "definition": "Clear Phase is a Sony proprietary sound-processing technology that compensates for a speaker's frequency and phase characteristics to deliver more natural reproduction and clearer sound imaging. Sony applies it in devices with built-in speakers. The name is a Sony trademark; the underlying method is digital correction of loudspeaker amplitude and phase response.", "plain_english": "Small built-in speakers do not reproduce every tone evenly. Clear Phase is Sony processing that corrects those tone and timing errors. The goal is more natural sound and a clearer sense of where sounds sit. Sony owns the name.", "purpose_function": "It exists to correct the built-in frequency and phase errors of small speakers so playback sounds more balanced and natural.", "practical_application": "On a Sony phone or compact speaker, enabling Clear Phase evens out the built-in speaker's tonal balance.", "category": "Sound Tuning", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["ClearAudio+", "xLOUD", "Frequency Response", "Phase", "Digital Signal Processing"], "common_mistakes": ["Confusing Clear Phase (tonal/phase correction) with xLOUD (loudness boost).", "Expecting it to help external speakers; it targets built-in ones.", "Assuming it adds effects rather than correcting speaker response."], "scenario_contexts": ["Improving a Sony smartphone's built-in speaker sound.", "Comparing built-in speaker tuning options on a compact Sony device.", "Explaining phase correction to a student during a demo."], "formula_symbolic": "", "formula_words": ""}, {"id": "948045fb-eba8-43df-aa49-9e6b4de3d758", "term": "ClearAudio+", "definition": "ClearAudio+ is a Sony proprietary automatic sound mode that detects the content being played and applies Sony's recommended combination of audio digital-signal-processing settings for that material with a single setting. It bundles several Sony sound technologies into one automatic tuning. The name is a Sony trademark; the underlying method is preset DSP tuning selected automatically.", "plain_english": "ClearAudio+ is a one-touch Sony sound setting. It looks at what you are playing. Then it picks Sony's suggested sound adjustments for you. It bundles several Sony audio tweaks into one easy switch.", "purpose_function": "It exists to give users Sony's recommended sound tuning automatically, without adjusting individual settings by hand.", "practical_application": "A technician turns on ClearAudio+ so a non-technical customer gets balanced sound without manual equalizing.", "category": "Sound Tuning", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Clear Phase", "Clear Bass", "Equalizer", "Digital Signal Processing", "Sound Field"], "common_mistakes": ["Thinking it is a single effect; it is a bundle of Sony DSP settings.", "Hand-tuning the equalizer while ClearAudio+ is active and conflicting with it.", "Assuming it upscales files like DSEE; it selects sound settings, not upscaling."], "scenario_contexts": ["One-touch sound setup for a customer who does not want to tweak settings.", "Comparing ClearAudio+ against manual equalizer tuning.", "Enabling recommended sound on a Sony Walkman or home audio device."], "formula_symbolic": "", "formula_words": ""}, {"id": "cc9b9441-b8a8-4e9a-8ee0-166c80c318b6", "term": "DSD Remastering Engine", "definition": "The DSD Remastering Engine is a Sony proprietary playback function on certain Walkman and Signature Series players that converts a PCM audio signal into a Direct Stream Digital (DSD) signal to reproduce sound closer to analog. On the NW-ZX706/ZX707 it works only through a supported balanced connection and is disabled during Bluetooth. The name is a Sony trademark; DSD itself is a Sony–Philips format used for Super Audio CD.", "plain_english": "Music files are usually stored as PCM data. This Sony engine changes that PCM into DSD during playback. DSD is a format Sony and Philips made for Super Audio CD. Sony says the result sounds closer to analog. It works through the wired balanced output.", "purpose_function": "It exists to re-render ordinary PCM tracks as DSD during playback, aiming for a smoother, more analog-like sound on high-end Sony players.", "practical_application": "A technician setting up a Sony Walkman enables the DSD Remastering Engine and connects balanced headphones to use it.", "category": "Playback Processing", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["DSD", "Super Audio CD", "S-Master HX", "Balanced Connection", "PCM"], "common_mistakes": ["Expecting it over Bluetooth; it is disabled during a Bluetooth connection.", "Thinking DSD is Sony-only; DSD and SACD were developed by Sony and Philips.", "Assuming it adds new detail; it re-renders existing PCM, not new information."], "scenario_contexts": ["Configuring a Sony NW-ZX707 Walkman for balanced wired listening.", "Explaining PCM-to-DSD conversion to an audiophile customer.", "Troubleshooting why the engine is greyed out when Bluetooth is on."], "formula_symbolic": "", "formula_words": ""}, {"id": "574a9af8-c944-422a-b3fd-f28a94ac7cc4", "term": "DSEE", "definition": "DSEE (Digital Sound Enhancement Engine) is Sony's proprietary upscaling technology that restores high-frequency content lost when audio is compressed, so lower-resolution files sound closer to high-resolution audio. Sony notes it is intended for compressed files, not for high-resolution files that need no upscaling. The name is a Sony trademark; the underlying method is audio bandwidth extension.", "plain_english": "When music is compressed, high-frequency detail is lost. DSEE is Sony technology that fills those high tones back in. This makes compressed files sound closer to high-quality audio. Sony owns the name. It is not used on files that are already high resolution.", "purpose_function": "It exists to improve the sound of compressed audio by rebuilding high-frequency detail removed during compression.", "practical_application": "A technician turns on DSEE on a Sony device so a customer's MP3s and streamed tracks sound fuller.", "category": "Playback Processing", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["DSEE HX", "DSEE Extreme", "DSEE Ultimate", "Hi-Res Audio", "Audio Compression"], "common_mistakes": ["Using it on high-resolution files, which Sony says do not need upscaling.", "Believing it restores the exact original data; it estimates the lost content.", "Confusing the DSEE family variants, which differ in method and capability."], "scenario_contexts": ["Improving streamed or MP3 audio on Sony headphones.", "Explaining upscaling limits to a customer expecting true hi-res.", "Comparing sound with DSEE on and off."], "formula_symbolic": "", "formula_words": ""}, {"id": "eaf76b30-2d6a-4de6-9355-378b862452f2", "term": "DSEE Extreme", "definition": "DSEE Extreme is a Sony proprietary version of its Digital Sound Enhancement Engine that uses Edge-AI (on-device artificial intelligence) to upscale compressed digital music in real time, restoring high-range sound lost in compression. The name is a Sony trademark; the underlying method is AI-based audio bandwidth extension.", "plain_english": "DSEE Extreme is a smarter version of Sony's upscaling. It uses on-device artificial intelligence, called Edge-AI. It rebuilds lost high tones in compressed music as it plays. Sony owns the name.", "purpose_function": "It exists to improve compressed audio more accurately than basic DSEE by using AI to predict and restore lost detail in real time.", "practical_application": "A technician enables DSEE Extreme on a Sony headset so a customer's streaming music gains restored high-frequency detail.", "category": "Playback Processing", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["DSEE", "DSEE HX", "DSEE Ultimate", "Hi-Res Audio", "Edge-AI"], "common_mistakes": ["Assuming AI recreates the exact original recording; it estimates the lost content.", "Confusing it with DSEE HX, which does not use AI.", "Expecting it to help files that are already high resolution."], "scenario_contexts": ["Upscaling compressed streaming on WH-1000XM series headphones.", "Comparing DSEE HX and DSEE Extreme for a customer.", "Demonstrating restored detail on low-bitrate tracks."], "formula_symbolic": "", "formula_words": ""}, {"id": "d191c524-99df-42c0-8539-7913697dd5fa", "term": "DSEE HX", "definition": "DSEE HX is a Sony proprietary upscaling technology that, when compressed audio is played, replaces lost high frequencies in real time to give near high-resolution sound quality. It is a variant of Sony's Digital Sound Enhancement Engine. The name is a Sony trademark; the underlying method is real-time audio bandwidth extension without AI.", "plain_english": "DSEE HX is a Sony upscaling feature. As compressed music plays, it adds back missing high tones right away. The result is close to high-resolution sound. Sony owns the name.", "purpose_function": "It exists to raise the perceived quality of compressed audio toward high-resolution by restoring lost high-frequency content during playback.", "practical_application": "A technician enables DSEE HX on a Sony Walkman so compressed tracks sound closer to hi-res.", "category": "Playback Processing", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["DSEE", "DSEE Extreme", "DSEE Ultimate", "Hi-Res Audio", "Audio Compression"], "common_mistakes": ["Thinking DSEE HX uses AI; the AI versions are Extreme and Ultimate.", "Applying it to hi-res files that do not need upscaling.", "Expecting true hi-res data rather than an estimate."], "scenario_contexts": ["Upscaling compressed music on older Sony hi-res players.", "Explaining the difference from DSEE Extreme.", "A/B testing DSEE HX on and off with MP3s."], "formula_symbolic": "", "formula_words": ""}, {"id": "c6e0960c-c437-4fbc-9879-004bee6d5b67", "term": "DSEE Ultimate", "definition": "DSEE Ultimate is Sony's most advanced Digital Sound Enhancement Engine variant, using Edge-AI (on-device artificial intelligence) to upscale compressed audio — and, on supported devices, streaming content — in real time to reproduce quality closer to the pre-compression original. The name is a Sony trademark; the underlying method is AI-based, dynamic audio bandwidth extension.", "plain_english": "DSEE Ultimate is Sony's top upscaling feature. It uses on-device artificial intelligence. It rebuilds lost detail in compressed and streamed music as it plays. Sony owns the name.", "purpose_function": "It exists to give the highest-quality Sony upscaling, using AI to restore detail across more content types, including streaming, in real time.", "practical_application": "A technician turns on DSEE Ultimate on a newer Sony headset to upscale a customer's streaming service audio.", "category": "Playback Processing", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["DSEE", "DSEE HX", "DSEE Extreme", "Hi-Res Audio", "Edge-AI"], "common_mistakes": ["Assuming it recreates the exact original master; it estimates lost content with AI.", "Confusing it with non-AI DSEE HX.", "Expecting every device to support streaming upscaling."], "scenario_contexts": ["Upscaling streamed music on a WH-1000XM series headset.", "Comparing DSEE Extreme and DSEE Ultimate for a customer.", "Demonstrating AI upscaling on low-bitrate audio."], "formula_symbolic": "", "formula_words": ""}, {"id": "892328c6-a0cc-464e-a2c2-81b7c34e66c7", "term": "Digital Sound Enhancement Engine", "definition": "Digital Sound Enhancement Engine is the full name of Sony's DSEE, a proprietary upscaling technology that restores high-frequency detail lost during audio compression so compressed files sound closer to high-resolution audio. Later versions (DSEE Extreme, DSEE Ultimate) add on-device AI. The name is a Sony trademark; the underlying method is audio bandwidth extension.", "plain_english": "Digital Sound Enhancement Engine is the full name of Sony's DSEE. It fills in high tones that compression removes. This makes compressed music sound fuller and closer to high quality. Sony owns the name.", "purpose_function": "It exists as Sony's family of upscaling technologies for improving compressed audio playback quality.", "practical_application": "A technician recognizes this as the full form of DSEE when reading a Sony device's specification sheet.", "category": "Playback Processing", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["DSEE", "DSEE HX", "DSEE Extreme", "DSEE Ultimate", "Hi-Res Audio"], "common_mistakes": ["Not realizing this is simply the full name of DSEE.", "Assuming all versions use AI; the original and HX do not.", "Using it on hi-res files that need no upscaling."], "scenario_contexts": ["Reading a Sony spec sheet that spells out the acronym.", "Explaining to a student what DSEE stands for.", "Identifying the technology family across Sony product lines."], "formula_symbolic": "", "formula_words": ""}, {"id": "3307734a-0ab5-482b-aff6-e19d5288f830", "term": "Dual Noise Sensor Technology", "definition": "Dual Noise Sensor Technology is a Sony proprietary active-noise-canceling approach that uses two microphones per earcup — one feed-forward (outside) and one feedback (inside) — to capture ambient noise, which the noise-canceling processor (such as Sony's QN1) then cancels. The name is a Sony trademark; the dual feed-forward/feedback microphone arrangement is a standard hybrid active-noise-canceling design.", "plain_english": "Sony puts two tiny microphones on each earcup. One faces outward and one faces inward. Together they pick up outside noise. Sony's processor then makes an opposite signal to cancel it. This two-microphone setup is a common noise-canceling design.", "purpose_function": "It exists to sense ambient noise from two points so the processor can cancel a wider range of noise more accurately.", "practical_application": "A technician explains that each earcup's inner and outer mics feed the QN1 processor to cancel cabin and traffic noise.", "category": "Noise Control Feature", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Active Noise Cancellation", "QN1 Processor", "Auto Noise Canceling Optimizer", "Feed-forward", "Feedback"], "common_mistakes": ["Thinking the mics are only for calls; here they sense noise for cancellation.", "Confusing hybrid (dual) ANC with feed-forward-only designs.", "Assuming 'dual' means stereo mics rather than feed-forward plus feedback."], "scenario_contexts": ["Explaining hybrid ANC on Sony WI-1000XM2 or WH-1000XM3/XM4.", "Comparing dual-sensor with later multi-microphone systems.", "Teaching feed-forward versus feedback microphone roles."], "formula_symbolic": "", "formula_words": ""}, {"id": "8419f24d-ac14-4f71-b8c1-7cabd77cee06", "term": "Find Your Equalizer", "definition": "Find Your Equalizer is a Sony proprietary feature in the Sony | Headphones Connect (Sound Connect) app that helps users discover a preferred sound balance by listening to and choosing between sound options during playback, then saving the result as a custom equalizer preset. The name is a Sony trademark; the underlying method is a guided listening/preference-selection equalizer.", "plain_english": "Find Your Equalizer is a Sony app feature. It plays different sound settings for you to compare. You pick the ones you like best. The app saves your choice as a custom equalizer. Sony owns the name.", "purpose_function": "It exists to help users set an equalizer they like by ear, instead of adjusting frequency bands manually.", "practical_application": "A technician walks a customer through Find Your Equalizer to build a personalized sound profile in the app.", "category": "Sound Tuning", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Equalizer", "Clear Bass", "ClearAudio+", "Custom Preset", "Frequency Response"], "common_mistakes": ["Expecting a measurement or hearing test; it is a preference comparison.", "Not saving the result, so the custom preset is lost.", "Assuming it changes hardware rather than an app equalizer setting."], "scenario_contexts": ["Personalizing sound for a customer in a retail demo.", "Creating a custom equalizer preset without manual band tweaking.", "Comparing preference-based tuning to a graphic equalizer."], "formula_symbolic": "", "formula_words": ""}, {"id": "875b0d3a-b6d8-4f47-9fb4-3ff0d9018c28", "term": "Focus on Voice", "definition": "Focus on Voice is a Sony proprietary Ambient Sound Mode setting that suppresses unwanted background noise while letting announcements and people's voices pass through, so the wearer can hear speech while still listening to music. The name is a Sony trademark; the underlying method is voice-band passthrough/filtering within ambient sound mode.", "plain_english": "Focus on Voice is a Sony headphone setting. It is part of ambient sound mode. It quiets background noise but lets voices and announcements through. So you can hear people talk while music still plays. Sony owns the name.", "purpose_function": "It exists to let users hear voices and announcements clearly through their headphones without fully stopping their music or removing the headset.", "practical_application": "A commuter enables Focus on Voice to catch train announcements while keeping music on.", "category": "Noise Control Feature", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Ambient Sound Mode", "Speak-to-Chat", "Quick Attention", "Adaptive Sound Control", "Active Noise Cancellation"], "common_mistakes": ["Confusing it with Speak-to-Chat, which auto-pauses music when you talk.", "Expecting it to cancel noise; it selectively passes voices through.", "Assuming it works with full noise canceling on; it is an ambient-sound setting."], "scenario_contexts": ["Hearing station announcements while listening on a commute.", "Catching a colleague's question without pausing audio.", "Setting ambient sound to prioritize speech in an office."], "formula_symbolic": "", "formula_words": ""}, {"id": "468d6954-2f62-46a0-b148-237386032418", "term": "Hi-Res Audio Wireless", "definition": "Hi-Res Audio Wireless is a certification and logo, owned by the Japan Audio Society, for products and Bluetooth codecs capable of transmitting high-resolution audio wirelessly. Sony's LDAC codec satisfies the Hi-Res Audio Wireless requirement at its 990 kbps transfer rate. The logo is a Japan Audio Society trademark, not Sony's; Sony products display it when they meet the standard.", "plain_english": "Hi-Res Audio Wireless is a quality label for wireless audio. The Japan Audio Society owns this label, not Sony. It marks Bluetooth gear that can send high-resolution sound. Sony's LDAC earns the label at its top speed of 990 kbps.", "purpose_function": "It exists to certify and label Bluetooth products and codecs that meet the Japan Audio Society's high-resolution wireless audio requirements.", "practical_application": "A technician points to the Hi-Res Audio Wireless logo to confirm a Sony headset can receive high-resolution audio over LDAC.", "category": "Standards & Certification", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["LDAC", "Hi-Res Audio", "Bluetooth", "Japan Audio Society", "Audio Codec"], "common_mistakes": ["Thinking the logo is Sony's; it belongs to the Japan Audio Society.", "Assuming any Bluetooth link is hi-res; it requires a qualifying codec like LDAC.", "Confusing wired Hi-Res Audio certification with the wireless version."], "scenario_contexts": ["Verifying a headset supports hi-res streaming over Bluetooth.", "Explaining codec requirements to a customer.", "Checking certification logos on Sony packaging."], "formula_symbolic": "", "formula_words": ""}, {"id": "e76ef3f6-4b9c-478e-8ec8-6852a2d42d00", "term": "LDAC", "definition": "LDAC is an audio coding technology (codec) developed by Sony for transmitting audio, including high-resolution audio, over Bluetooth. It supports transfer rates up to 990 kbps — roughly three times the data of the standard SBC codec — and adjusts automatically among 330/660/990 kbps. The name is a Sony trademark, though LDAC is also included in the Android Open Source Project; it is a high-bitrate Bluetooth codec.", "plain_english": "LDAC is a Sony method for sending audio over Bluetooth. It can carry more data than the standard Bluetooth codec, up to 990 kbps. That lets it send high-resolution sound wirelessly. Sony owns the name. It changes speed to keep the connection stable.", "purpose_function": "It exists to send higher-quality audio over Bluetooth than the standard SBC codec, enabling wireless high-resolution playback.", "practical_application": "A technician enables LDAC and sets audio quality priority so a Sony headset streams at up to 990 kbps.", "category": "Audio Codec", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Hi-Res Audio Wireless", "Bluetooth", "Audio Codec", "SBC", "Hi-Res Audio"], "common_mistakes": ["Assuming LDAC is always lossless; it is a high-bitrate lossy codec.", "Expecting 990 kbps in all conditions; it drops the rate when the link is weak.", "Thinking only one side needs it; both source and receiver must support LDAC."], "scenario_contexts": ["Pairing an Android phone and Sony headset for hi-res streaming.", "Troubleshooting rate drops caused by interference.", "Comparing LDAC with SBC or aptX codecs."], "formula_symbolic": "", "formula_words": ""}, {"id": "584c4572-df99-4288-aa24-0d672b566bf4", "term": "Personal Noise Canceling Optimizer", "definition": "Personal Noise Canceling Optimizer (Personal NC Optimizer) is a Sony proprietary function that analyzes the individual wearer's conditions — such as face shape, hairstyle, and whether glasses are worn — and optimizes noise-canceling performance for that person. It is typically run on demand rather than continuously. The name is a Sony trademark; the underlying method is a personalized calibration of the active-noise-canceling filter.", "plain_english": "Everyone's head and fit are a little different. This Sony feature runs a quick test. It checks your face shape, hair, and glasses. Then it tunes the noise blocking to suit you. Sony owns the name.", "purpose_function": "It exists to tailor noise canceling to an individual's fit so cancellation performs its best for that specific wearer.", "practical_application": "A technician runs the Personal NC Optimizer test after fitting a customer's headphones and their glasses.", "category": "Noise Control Feature", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Auto Noise Canceling Optimizer", "Active Noise Cancellation", "Dual Noise Sensor Technology", "Adaptive Sound Control", "Ear Tip Fit"], "common_mistakes": ["Confusing it with Auto NC Optimizer, which runs continuously and also senses air pressure.", "Running it without glasses on when glasses are normally worn.", "Expecting it to fix a poor ear seal; it tunes filtering, not fit."], "scenario_contexts": ["Calibrating noise canceling for a customer who wears glasses.", "One-time optimization after a hairstyle or fit change.", "Comparing personalized versus default noise canceling."], "formula_symbolic": "", "formula_words": ""}, {"id": "c6713381-0d46-4262-ab02-8a7cbdb4972b", "term": "Precise Voice Pickup Technology", "definition": "Precise Voice Pickup Technology is a Sony proprietary call-microphone system that combines multiple beamforming microphones with an AI-based noise-reduction algorithm to isolate the user's voice from background noise during calls. On the WH-1000XM5 Sony describes four beamforming microphones. The name is a Sony trademark; the underlying method is microphone beamforming plus noise-reduction signal processing.", "plain_english": "Precise Voice Pickup is a Sony system for clearer phone calls. It uses several small microphones aimed to catch your voice. Software then removes background noise using artificial intelligence. Sony owns the name.", "purpose_function": "It exists to make the user's voice clearer on calls by focusing microphones on the mouth and filtering out surrounding noise.", "practical_application": "A technician demonstrates clear call pickup on a noisy street using a Sony headset's Precise Voice Pickup.", "category": "Voice & Call Feature", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Beamforming", "Noise Reduction", "Speak-to-Chat", "Microphone Array", "Active Noise Cancellation"], "common_mistakes": ["Confusing call-microphone pickup with noise canceling for listening.", "Assuming more microphones always help; placement and processing matter.", "Expecting perfect voice isolation in very loud environments."], "scenario_contexts": ["Taking a call outdoors in wind or traffic.", "Comparing call clarity between headset models.", "Explaining beamforming microphones to a customer."], "formula_symbolic": "", "formula_words": ""}, {"id": "2e1718ec-66fd-431d-b30f-5e45908b0c8e", "term": "Quick Attention", "definition": "Quick Attention (Quick Attention Mode) is a Sony proprietary function that instantly lowers music, call, and ringtone volume to let ambient sound through while the wearer holds a hand over the touch sensor on the right unit; releasing restores normal playback. The name is a Sony trademark; the underlying method is a momentary ambient-passthrough gesture control.", "plain_english": "Quick Attention lets you hear around you fast. Cover the right earcup's touch panel with your hand. The music turns down so outside sound comes through. Take your hand away to go back to normal. Sony owns the name.", "purpose_function": "It exists to let users briefly hear their surroundings — like an announcement or a quick word — without removing the headphones or changing settings.", "practical_application": "At an airport gate, a user covers the touch panel to catch a boarding announcement, then releases it.", "category": "Noise Control Feature", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Ambient Sound Mode", "Speak-to-Chat", "Focus on Voice", "Touch Sensor", "Adaptive Sound Control"], "common_mistakes": ["Confusing it with Speak-to-Chat, which triggers automatically when you talk.", "Forgetting it is momentary and only active while the hand is held.", "Tapping instead of covering the whole touch panel."], "scenario_contexts": ["Hearing a gate announcement quickly without pausing.", "Responding to a brief question at a desk.", "Checking surroundings while crossing a street."], "formula_symbolic": "", "formula_words": ""}, {"id": "843cc3d0-ef50-4d07-823c-4ed3e70baf1c", "term": "S-Master", "definition": "S-Master is Sony's proprietary full-digital amplifier technology that amplifies the digital audio signal directly instead of first converting it to analog, reducing distortion and noise while improving power efficiency and allowing smaller, cooler designs. The name is a Sony trademark; it is a switching (Class-D style, pulse-based) digital amplifier implementation.", "plain_english": "Most amplifiers turn digital music into analog before boosting it. Sony's S-Master boosts the digital signal directly instead. This lowers distortion and noise and uses less power. Smaller, cooler designs become possible. Sony owns the name.", "purpose_function": "It exists to amplify audio with less distortion and higher efficiency by keeping the signal digital as long as possible in the amplifier stage.", "practical_application": "A technician identifies S-Master as the amplifier stage when reading a Sony player or home audio unit's specifications.", "category": "Amplification", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["S-Master HX", "Class-D Amplifier", "Digital Amplifier", "Distortion", "Signal-to-Noise Ratio"], "common_mistakes": ["Thinking there is no digital-to-analog step; conversion still happens at the output.", "Assuming digital amps sound worse; S-Master targets low distortion.", "Confusing S-Master with S-Master HX, which is tuned for hi-res audio."], "scenario_contexts": ["Reading the amplifier specification on a Sony device.", "Explaining digital amplifiers to a student.", "Comparing efficiency of digital and analog amp stages."], "formula_symbolic": "", "formula_words": ""}, {"id": "0afb60a8-9604-4fb0-8a8b-beec525baf4c", "term": "S-Master HX", "definition": "S-Master HX is a variant of Sony's S-Master full-digital amplifier technology developed for High-Resolution Audio, reducing distortion and noise across wider frequency ranges. Because it amplifies the digital signal directly rather than converting to analog first, Sony states it maintains the purity of the original signal for more faithful reproduction. The name is a Sony trademark; it is a digital (switching/Class-D) amplifier optimized for hi-res.", "plain_english": "S-Master HX is Sony's digital amplifier made for high-resolution audio. It boosts the digital signal directly. This keeps distortion and noise low across a wide range of tones. The goal is sound that stays true to the original. Sony owns the name.", "purpose_function": "It exists to amplify high-resolution audio faithfully, keeping distortion and noise low over a wide frequency range.", "practical_application": "A technician notes S-Master HX in a Sony hi-res Walkman's specifications when explaining its amplifier.", "category": "Amplification", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["S-Master", "Hi-Res Audio", "Digital Amplifier", "DSD Remastering Engine", "Distortion"], "common_mistakes": ["Confusing S-Master HX with the base S-Master, which is not hi-res tuned.", "Assuming no analog output stage exists at all.", "Thinking the amplifier alone guarantees hi-res; the whole signal chain matters."], "scenario_contexts": ["Specifying a Sony hi-res player's amplifier.", "Comparing S-Master and S-Master HX models.", "Explaining hi-res amplification to a customer."], "formula_symbolic": "", "formula_words": ""}, {"id": "25f62708-5c76-4c43-acbd-34ddb939014f", "term": "Speak-to-Chat", "definition": "Speak-to-Chat is a Sony proprietary function that automatically pauses or mutes playback and switches to ambient sound when it detects the wearer speaking, letting them hold a conversation without removing the headphones; it ends after the wearer stops talking for a set time (about 15 seconds by default). The name is a Sony trademark; the underlying method is voice-activity detection triggering ambient passthrough.", "plain_english": "Speak-to-Chat listens for your own voice. When you start talking, it pauses the music by itself. It then lets outside sound in so you can chat. It turns off again after you stop talking for a while. Sony owns the name.", "purpose_function": "It exists to let users start a conversation hands-free, without pressing buttons or taking the headphones off.", "practical_application": "A user orders coffee and the headset auto-pauses music when they begin to speak.", "category": "Voice & Call Feature", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Quick Attention", "Focus on Voice", "Ambient Sound Mode", "Precise Voice Pickup Technology", "Adaptive Sound Control"], "common_mistakes": ["Not knowing humming or coughing can trigger it accidentally.", "Confusing it with Quick Attention, which is a manual hand gesture.", "Expecting instant re-start; it waits a timeout before resuming."], "scenario_contexts": ["Talking to a cashier without removing headphones.", "A quick hands-free chat at the office.", "Adjusting the detection timeout in the app."], "formula_symbolic": "", "formula_words": ""}, {"id": "8a1055c1-98dd-439a-8621-ad6569279f74", "term": "Voice Zoom", "definition": "Voice Zoom is a Sony proprietary television sound feature that lets the viewer raise or lower the level of voices (such as commentary or dialogue) independently of the ambient/background audio. The name is a Sony trademark; the underlying method is dialogue/voice-band level adjustment separate from other sound.", "plain_english": "Voice Zoom is a Sony TV sound feature. It lets you turn voices up or down on their own. Background sound stays where it is. So you can make speech easier to hear. Sony owns the name.", "purpose_function": "It exists to help viewers hear dialogue or commentary clearly by adjusting voice level separately from background sound.", "practical_application": "A technician uses Voice Zoom on a Sony TV to raise commentary over crowd noise during a sports broadcast.", "category": "Voice & Call Feature", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Dialogue Enhancement", "Focus on Voice", "Ambient Sound", "Center Channel", "Sound Field"], "common_mistakes": ["Confusing this TV feature with headphone voice features.", "Expecting perfect separation; voices and background can overlap.", "Assuming it raises overall volume rather than voice level."], "scenario_contexts": ["Boosting commentary during a sports broadcast.", "Helping a viewer who finds dialogue hard to follow.", "Balancing speech and effects on a Sony TV."], "formula_symbolic": "", "formula_words": ""}, {"id": "bb2bb01c-a552-4f97-8605-9248b726b592", "term": "Wide Area Tap", "definition": "Wide Area Tap is a Sony proprietary control method, used on earbuds such as LinkBuds, that detects taps on the face or the area around the ear using built-in acceleration sensors, rather than requiring the user to tap the earbud itself. The name is a Sony trademark; the underlying method is accelerometer-based tap detection.", "plain_english": "Wide Area Tap lets you control earbuds by tapping near your ear. You tap your face or cheek, not the tiny earbud. Motion sensors feel the taps and act on them. Sony owns the name.", "purpose_function": "It exists to give a larger, easier control area for small earbuds by sensing taps around the ear instead of on the bud.", "practical_application": "A technician shows a customer how to tap the cheek to play or pause LinkBuds.", "category": "Control Interface", "difficulty": "intermediate", "achievement_id": "f1f2f3a6-5cbc-4ffc-8241-9a9ddc4ccfb1", "cross": [], "related_terms": ["Touch Sensor", "Accelerometer", "Quick Attention", "LinkBuds", "Gesture Control"], "common_mistakes": ["Tapping the earbud instead of the area around the ear.", "Assuming it uses a touch surface; it uses motion sensors.", "Tapping too softly for the accelerometer to detect."], "scenario_contexts": ["Controlling Sony LinkBuds by tapping the cheek.", "Explaining accelerometer tap detection to a customer.", "Adjusting tap sensitivity in the app."], "formula_symbolic": "", "formula_words": ""}, {"id": "66d8378c-3f02-4003-a1ca-57f77bb0ecf6", "term": "Cross Remote", "definition": "Cross Remote is Sony's proprietary function for the DWX digital wireless series that lets an operator centrally monitor and remotely control up to 82 transmitters. It carries transmitter status (remaining battery, RF level, transmitter name) and control parameters (RF power output, attenuator level, low-cut filter) over a dedicated wireless control network, separate from the UHF audio path, using the RMU-01 remote control unit. Cross Remote is a trademark of Sony Corporation; the underlying approach is generic centralized remote telemetry and control applied to wireless microphone systems.", "plain_english": "Cross Remote is a Sony feature for its DWX digital wireless mic gear. It lets one operator watch many transmitters from a central point. You can see each pack's battery, radio signal, and name. You can also change settings without touching the pack. Sony owns this name.", "purpose_function": "It exists so one engineer can manage a large wireless microphone rig from a central point, checking status and adjusting parameters without physically reaching each bodypack or handheld.", "practical_application": "On a large theatrical or broadcast production, a technician uses Cross Remote with the RMU-01 unit to watch battery and RF levels across dozens of transmitters and change their settings remotely.", "category": "Wireless Remote Control", "difficulty": "intermediate", "achievement_id": "173a5d7e-a84d-4b90-9038-81d5ad73f08a", "cross": [], "related_terms": ["DWX", "Wireless Studio", "WiDIF-HP", "Bodypack Transmitter", "RF Level", "Frequency Coordination"], "common_mistakes": ["Assuming Cross Remote carries the audio; audio rides the separate WiDIF-HP UHF link while Cross Remote carries only status and control data.", "Blaming audio dropouts on Cross Remote by confusing the low-power control network with the UHF audio band.", "Forgetting the RMU-01 remote control unit is required and sold separately for full Cross Remote control."], "scenario_contexts": ["Musical theatre with dozens of body-mics where each performer's battery must be tracked live.", "Broadcast studio adjusting transmitter RF power and low-cut filter remotely between segments.", "House of worship centrally monitoring RF health across a large wireless microphone pool."], "formula_symbolic": "", "formula_words": ""}, {"id": "ee5006a8-f4bf-459a-91be-d1c059dfd559", "term": "DWX", "definition": "DWX is Sony's professional digital wireless microphone series, transmitting 24-bit/48-kHz uncompanded digital audio over the UHF television band using Sony's proprietary WiDIF-HP interface. It supports up to 12 simultaneous channels in a 6-MHz TV channel (up to 16 in an 8-MHz TV channel), with system latency around 1.2 to 1.5 ms and dynamic range greater than 106 dB. DWX is a trademark of Sony Corporation; the underlying approach, digital UHF radio transmission without companding, is a generic digital-wireless method.", "plain_english": "DWX is Sony's line of professional digital wireless microphone gear. It sends sound as digital data over UHF radio, the same band as broadcast TV. The sound stays clear because it is not squeezed and stretched like older analog systems. Sony owns the DWX name.", "purpose_function": "It exists to deliver studio-quality, low-latency wireless audio for live stage, theatre and broadcast without the noise and level artifacts caused by analog companding.", "practical_application": "A technician deploys DWX transmitters (bodypack, plug-on, handheld) with DWR rack receivers, coordinates channels within the available UHF TV spectrum, and monitors them using Wireless Studio software.", "category": "Digital Wireless System", "difficulty": "intermediate", "achievement_id": "173a5d7e-a84d-4b90-9038-81d5ad73f08a", "cross": [], "related_terms": ["WiDIF-HP", "Cross Remote", "Wireless Studio", "Companding", "UHF Band", "Diversity Reception"], "common_mistakes": ["Treating DWX like analog wireless and expecting a compander; DWX uses uncompanded digital audio, so companding assumptions do not apply.", "UNSAFE: Ignoring UHF TV spectrum coordination and local regulations, causing interference with licensed TV broadcast or public-safety services.", "Packing more channels than the 12-per-6-MHz (or 16-per-8-MHz) guidance allows and then getting dropouts."], "scenario_contexts": ["Large theatre production needing many clean, low-latency wireless microphone channels.", "Live broadcast where digital audio quality and RF reliability are both critical.", "Corporate or house-of-worship install coordinating DWX channels around local TV stations."], "formula_symbolic": "", "formula_words": ""}, {"id": "aab675e2-0e35-4600-aa65-ffe9fcaef067", "term": "Wireless Studio", "definition": "Wireless Studio is Sony's PC control software for the DWX digital wireless series, used to monitor and remotely control receivers and their paired transmitters over an IP network. It supports up to 82 channels and access by up to six computers, and provides a channel-plan adviser, an RF-level and quality-level status recorder, and spectrum scanning performed through the receivers. Wireless Studio is a trademark of Sony Corporation; functionally it is generic networked wireless-system management and coordination software.", "plain_english": "Wireless Studio is Sony software for its DWX wireless microphone systems. It runs on a computer linked to the receivers by a network. You can watch signal strength and battery on many channels at once. It also helps you pick clear radio channels and spot interference. Sony owns this software.", "purpose_function": "It exists to give engineers centralized, networked oversight of large DWX deployments, coordinating frequencies, logging RF health, and adjusting transmitter settings from a computer.", "practical_application": "A technician connects DWR receivers to a network switch, runs Wireless Studio, scans the spectrum to build a clean channel plan, then watches RF strength and battery across all channels during a show.", "category": "Wireless Control Software", "difficulty": "intermediate", "achievement_id": "173a5d7e-a84d-4b90-9038-81d5ad73f08a", "cross": [], "related_terms": ["DWX", "Cross Remote", "Frequency Coordination", "Spectrum Scan", "RF Level", "Diversity Reception"], "common_mistakes": ["Assuming Wireless Studio replaces on-site RF coordination; its scan reflects the receivers' location, so scan where the antennas actually are.", "Placing receivers on a busy or mismatched network subnet, so the software cannot discover or control them.", "Confusing Wireless Studio (networked PC monitoring and control) with Cross Remote (transmitter telemetry via the RMU-01)."], "scenario_contexts": ["Festival RF technician building a channel plan across dozens of DWX channels before doors open.", "Broadcast engineer logging RF levels and quality over a multi-hour live event.", "Install technician remotely checking wireless system health from a control room."], "formula_symbolic": "", "formula_words": ""}, {"id": "22352ab7-660b-4eae-8d31-dd44e52a2ee8", "term": "EXTRA BASS", "definition": "EXTRA BASS is a proprietary Sony sound-enhancement feature and product line (trademark owned by Sony) that emphasizes low-frequency output. Sony's help documentation describes it as boosting the low tones of the audio, with the natural sound (reduced bass) available when it is off. The underlying method is standard low-frequency (bass) equalization/boost, in EXTRA BASS hardware often combined with dedicated woofers or passive radiators, and is not unique to Sony.", "plain_english": "EXTRA BASS is a Sony setting that makes low sounds stronger. It boosts the bass so drums and beats feel bigger. It does not add new sound. It just turns up the low notes that are already there. Sony owns this name.", "purpose_function": "It exists to give listeners a stronger, more prominent low end on demand, lifting bass energy that small or portable speakers otherwise under-reproduce.", "practical_application": "A technician setting up or demonstrating a Sony portable speaker toggles EXTRA BASS to show its low-end lift, and explains it is equalization, not added content, when a customer expects 'more' bass detail.", "category": "Bass Enhancement", "difficulty": "advanced", "achievement_id": "f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37", "cross": [], "related_terms": ["MEGA BASS", "ULT Power Sound", "Equalization", "Passive radiator", "Woofer", "Frequency response"], "common_mistakes": ["Thinking EXTRA BASS adds bass information that is not in the recording; it only boosts existing low frequencies.", "Confusing EXTRA BASS with MEGA BASS and ULT POWER SOUND; all three are Sony bass-boost brands from different product eras.", "Assuming the effect sounds identical on every track; Sony notes its noticeability depends on the music.", "UNSAFE: Running heavy bass boost at high volume for long sessions raises sound-pressure exposure and hearing-damage risk."], "scenario_contexts": ["Setting up a Sony EXTRA BASS portable speaker at a retail demo.", "Explaining to a customer why bass sounds louder but not more detailed with EXTRA BASS on.", "Measuring a speaker's true frequency response with EXTRA BASS disabled."], "formula_symbolic": "", "formula_words": ""}, {"id": "c8e38640-745b-491f-89b2-dfe05666997e", "term": "LIVE SOUND Mode", "definition": "LIVE SOUND is a proprietary Sony sound-effect mode (trademark owned by Sony) selectable on certain Sony wireless speakers. Sony's help documentation characterizes it as producing a more 'realistic' sound. It is implemented with digital signal processing (DSP) sound-field/spatial enhancement rather than a physical change to the drivers, a technique common across audio products and not unique to Sony.", "plain_english": "LIVE SOUND is a Sony sound mode. It uses digital processing to make music feel wider and more open. Sony says it gives a more realistic sound. The trick is software, not a new speaker. Sony owns this name.", "purpose_function": "It exists to make stereo playback feel wider and more immersive from a single speaker, using DSP to alter the perceived sound field.", "practical_application": "A technician selects LIVE SOUND on a Sony wireless speaker to give background music a wider, more open feel, while noting the effect varies with the source material.", "category": "Sound Field Processing", "difficulty": "advanced", "achievement_id": "f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37", "cross": [], "related_terms": ["EXTRA BASS", "Digital signal processing", "Sound field", "Stereo widening", "Frequency response", "Immersive Audio Enhancement"], "common_mistakes": ["Assuming LIVE SOUND physically changes the drivers; it is a DSP sound-field effect.", "Expecting a strong surround effect on every track; Sony notes the effect can be subtle depending on the music.", "Confusing LIVE SOUND with true multichannel or 360 spatial audio formats."], "scenario_contexts": ["Choosing a sound-effect mode on a Sony SRS-XB wireless speaker.", "Playing background music and switching to LIVE SOUND for a wider feel.", "A/B comparing LIVE SOUND, EXTRA BASS, and STANDARD modes for a customer."], "formula_symbolic": "", "formula_words": ""}, {"id": "661ce786-53ce-41a0-b11b-e3448f9851c0", "term": "MEGA BASS", "definition": "MEGA BASS is a Sony trademark for a bass-emphasis (bass-boost) feature historically provided on Sony portable and compact audio players. It boosts the low-frequency range of the playback signal. The underlying method is standard low-frequency equalization, originally an analog boost circuit and later implemented in DSP, and is not unique to Sony.", "plain_english": "MEGA BASS is an older Sony bass-boost feature. You find it on Sony cassette, disc, and pocket players. It lifts the low notes so music sounds punchier. It only boosts bass that is already in the track. Sony owns this name.", "purpose_function": "It exists to add perceived low-end weight on small portable players whose tiny transducers naturally roll off bass.", "practical_application": "A technician servicing or explaining legacy Sony portable players identifies the MEGA BASS control as a bass-boost switch and checks it is off when measuring the player's flat frequency response.", "category": "Bass Enhancement", "difficulty": "advanced", "achievement_id": "f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37", "cross": [], "related_terms": ["EXTRA BASS", "ULT Power Sound", "Bass boost", "Equalization", "Loudness"], "common_mistakes": ["Thinking MEGA BASS is the same feature as EXTRA BASS; MEGA BASS is Sony's older portable-player branding.", "Believing MEGA BASS reveals hidden bass; it only boosts the low-frequency range already present.", "UNSAFE: Leaving strong bass boost on at high listening levels for long periods increases hearing-exposure risk."], "scenario_contexts": ["Servicing or demonstrating a legacy Sony cassette or CD Walkman with a MEGA BASS switch.", "Explaining why measured response is not flat until MEGA BASS is switched off."], "formula_symbolic": "", "formula_words": ""}, {"id": "8f5852bd-db78-4962-aec0-3ae37180696f", "term": "Mica Reinforced Cellular Diaphragm", "definition": "Mica Reinforced Cellular (MRC) is a Sony trademark for a loudspeaker diaphragm (cone) material in which mica mineral flakes reinforce a molded polymer, often in a cellular/honeycomb structure. Sony's technical materials state the resulting cone has high flexural rigidity for low-distortion output and wide frequency response. The underlying principle—adding mineral filler to a polymer to raise the cone's stiffness-to-mass ratio and push cone-breakup higher—is a standard loudspeaker cone-material technique, not unique to Sony.", "plain_english": "This is a speaker cone made of plastic mixed with mica, a mineral. The mica makes the cone stiffer but still light. A stiff, light cone moves cleanly and adds less distortion. Sony uses this cone in some speakers. Sony owns this name.", "purpose_function": "The mica reinforcement exists to make the cone stiffer and lighter so it moves as a rigid piston, reducing cone flexing (breakup) and the distortion it causes.", "practical_application": "A technician identifying a driver's cone material recognizes MRC as a mica-filled polymer cone and expects good rigidity and damping when assessing or replacing it.", "category": "Transducer Design", "difficulty": "advanced", "achievement_id": "f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37", "cross": [], "related_terms": ["Diaphragm", "Cone breakup", "Woofer", "Polypropylene cone", "X-Balanced Speaker Unit", "Frequency response"], "common_mistakes": ["Thinking the mica cone is metal or ceramic; it is a mica-mineral-filled polymer.", "Assuming more rigidity always means better sound; damping and mass balance also matter.", "Confusing the cellular/honeycomb polymer structure with a metal honeycomb panel."], "scenario_contexts": ["Identifying the cone material when inspecting a Sony car or bookshelf speaker.", "Choosing a replacement driver and matching cone stiffness characteristics.", "Explaining to a student why a stiffer, lighter cone lowers distortion."], "formula_symbolic": "", "formula_words": ""}, {"id": "7772e48e-3178-4cfa-8a5c-aebcc0b275cc", "term": "Sound Diffusion Processor", "definition": "Sound Diffusion Processor is a Sony trademark for a digital-signal-processing (DSP) feature used in certain compact Sony wireless speakers. Sony states it 'expands sound in any space' using its DSP technology so a small, often single-driver speaker fills a wider area. The underlying method is DSP sound-field/spatial widening, a technique not unique to Sony.", "plain_english": "This is a Sony software feature inside some small speakers. It spreads the sound out so it fills more of the room. One small speaker can then sound wider. The work is done by digital processing, not extra speakers. Sony owns this name.", "purpose_function": "It exists to broaden the perceived sound stage of a compact, often mono, speaker so it fills a room rather than sounding like a single point source.", "practical_application": "A technician setting up a compact Sony speaker leaves the Sound Diffusion Processor active for wider room coverage, and understands it is DSP when the speaker measures differently on- versus off-axis.", "category": "Sound Field Processing", "difficulty": "advanced", "achievement_id": "f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37", "cross": [], "related_terms": ["Digital signal processing", "Sound field", "Stereo widening", "LIVE SOUND Mode", "Mono", "Off-axis response"], "common_mistakes": ["Thinking the Sound Diffusion Processor adds real surround channels; it is DSP widening of one speaker's output.", "Expecting the same width everywhere; the effect depends on the room and listening position.", "Confusing it with physical acoustic diffusers used in room treatment."], "scenario_contexts": ["Setting up a compact Sony SRS-XB100 speaker for room-filling background sound.", "Explaining why a single small speaker sounds wider than expected.", "Measuring on-axis versus off-axis differences caused by the DSP."], "formula_symbolic": "", "formula_words": ""}, {"id": "1e77c0d5-7712-42c0-b283-c54785862995", "term": "ULT Power Sound", "definition": "ULT POWER SOUND is a proprietary Sony bass-emphasis feature (trademark owned by Sony), activated by a dedicated ULT button on Sony's ULT-series audio products. Sony's help documentation defines two levels: ULT1, which emphasizes deep bass, and ULT2, which emphasizes a greater sense of power. It boosts low-frequency output; the underlying method is low-frequency equalization combined with the product's woofers and radiators, and is not unique to Sony.", "plain_english": "ULT POWER SOUND is a Sony bass-boost feature. A button adds deep, powerful low sound. ULT1 lifts deep bass. ULT2 adds even more power. It boosts low notes; it does not add new sound. Sony owns this name.", "purpose_function": "It exists to let users instantly add deep, powerful bass with one button, for bass-forward genres and party listening.", "practical_application": "A technician demonstrating a Sony ULT speaker uses the ULT button to switch between ULT1 and ULT2, and warns that heavy bass boost at high volume raises distortion and hearing-exposure risk.", "category": "Bass Enhancement", "difficulty": "advanced", "achievement_id": "f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37", "cross": [], "related_terms": ["EXTRA BASS", "MEGA BASS", "Equalization", "Woofer", "Passive radiator", "Sound field"], "common_mistakes": ["Treating ULT1 and ULT2 as identical; ULT1 emphasizes deep bass while ULT2 adds more overall power.", "Thinking ULT POWER SOUND is a new driver technology; it is a bass-emphasis EQ mode using the product's woofers and radiators.", "UNSAFE: Using maximum bass boost at high volume for long periods raises distortion and hearing-exposure risk."], "scenario_contexts": ["Demonstrating the ULT button on a Sony ULT FIELD or ULT TOWER speaker.", "Switching between ULT1 and ULT2 for different music genres.", "Advising a user on safe listening levels when heavy bass boost is engaged."], "formula_symbolic": "", "formula_words": ""}, {"id": "0f6cb66a-f0f1-4301-934a-0c7273b97c9b", "term": "X-Balanced Speaker Unit", "definition": "X-Balanced Speaker Unit is a Sony trademark for a loudspeaker driver that uses a non-circular diaphragm instead of a conventional circular one. Sony states this maximizes the diaphragm (speaker) area to raise sound pressure for deeper, punchier bass and reduces driver excursion for lower distortion and clearer vocals. The underlying principle—optimizing diaphragm geometry to increase radiating area and reduce excursion for a given output—is a standard transducer-design approach, not unique to Sony, and is unrelated to 'balanced' (differential) audio wiring.", "plain_english": "This is a Sony speaker driver with a non-round shape. The odd shape fits more cone into the same space. More cone area means louder, deeper sound. It also moves less far, which lowers distortion. Sony owns this name. It has nothing to do with balanced cables.", "purpose_function": "It exists to squeeze more radiating area and lower distortion from a driver within a small enclosure, improving loudness and clarity where a round driver would be limited.", "practical_application": "A technician comparing Sony speakers explains that an X-Balanced unit's non-round diaphragm gives higher sound pressure and lower distortion from the same box, and corrects customers who think it means a balanced audio input.", "category": "Transducer Design", "difficulty": "advanced", "achievement_id": "f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37", "cross": [], "related_terms": ["Diaphragm", "Driver excursion", "Sound pressure level", "Total harmonic distortion", "Mica Reinforced Cellular Diaphragm", "Woofer"], "common_mistakes": ["Assuming 'X-Balanced' refers to a balanced (differential) audio input; it describes the diaphragm shape.", "Thinking it implies multiple drivers; it refers to one non-circular diaphragm design.", "Believing the shape alone guarantees better sound regardless of the rest of the system."], "scenario_contexts": ["Comparing Sony X-Series wireless speakers for a customer.", "Explaining how a non-round diaphragm raises sound pressure and lowers distortion in a small enclosure.", "Correcting a student who confuses X-Balanced with balanced cabling."], "formula_symbolic": "", "formula_words": ""}, {"id": "f5e1afb5-84e0-4764-b724-959e767c3da9", "term": "4K Analogue Enhancement", "definition": "A proprietary Solid State Logic analogue processing feature that combines a high-frequency EQ boost with gain-dependent harmonic distortion (predominantly second-order) to add presence and thickness. It is voiced to emulate the tonal character of the SSL 4000-series console and is applied entirely in the analogue domain. 'SSL' and '4K' are trademarks of Solid State Logic; the underlying method is generic high-shelf EQ combined with harmonic saturation (an exciter-type enhancer).", "plain_english": "This is a Solid State Logic feature that adds high-end sparkle and gentle warmth. It copies the sound of SSL's famous 4000 mixing desk. You switch it on with one button. It works on the real analogue signal, not with software.", "purpose_function": "It exists to give recordings the forward, exciting tone associated with the SSL 4000-series console, adding air and harmonic richness without a separate outboard processor.", "practical_application": "A technician engages 4K on an SSL 2 or SSL 2+ interface while tracking vocals or acoustic guitar to add sheen and body before the signal reaches the DAW.", "category": "Harmonic Saturation", "difficulty": "intermediate", "achievement_id": "52bf9944-db6d-4d98-9155-cbf456c60de8", "cross": [], "related_terms": ["4K Mode", "Variable Harmonic Drive", "Harmonic Distortion", "High-Shelf EQ", "SuperAnalogue"], "common_mistakes": ["Assuming '4K' means a 4 kHz setting or a video/sample-rate spec; it names the SSL 4000-series console.", "Thinking the effect is digital DSP; it is generated in the analogue signal path.", "Leaving 4K engaged on already-bright sources, which can add harshness or excess sibilance.", "Believing it is only a treble EQ; it also adds harmonic distortion."], "scenario_contexts": ["Recording vocals through an SSL 2+ and switching in 4K for added air and presence.", "Tracking acoustic guitar and using 4K to thicken the sound before mixing.", "A student comparing a clean take to a 4K take to hear analogue harmonic enhancement."], "formula_symbolic": "", "formula_words": ""}, {"id": "45bba68f-0a2f-4212-ad1e-35f7b7d9dfa0", "term": "4K Mode", "definition": "The engaged state of Solid State Logic's 4K analogue enhancement, selected by a front-panel switch (labelled 'Legacy 4K' on current interfaces). When active it applies a high-frequency EQ lift plus gain-dependent second-order harmonic distortion, voiced after the SSL 4000-series console, entirely in the analogue domain. 'SSL' and '4K' are trademarks of Solid State Logic; the method is generic high-shelf EQ plus harmonic saturation.", "plain_english": "This is the setting you turn on to use SSL's 4K sound. One switch adds high-end shine and gentle warmth. It mimics SSL's classic 4000 mixing desk. The change happens in the analogue circuit, not in software.", "purpose_function": "It lets an engineer add the SSL 4000-series analogue enhancement character instantly with a single switch, instead of using external gear or plug-ins.", "practical_application": "A technician flips the 4K switch on an SSL 2 or SSL 2+ interface to audition the enhanced tone against the clean signal while recording.", "category": "Harmonic Saturation", "difficulty": "intermediate", "achievement_id": "52bf9944-db6d-4d98-9155-cbf456c60de8", "cross": [], "related_terms": ["4K Analogue Enhancement", "Variable Harmonic Drive", "Harmonic Distortion", "High-Shelf EQ", "SuperAnalogue"], "common_mistakes": ["Reading '4K' as 4 kHz or a resolution spec instead of the 4000-series console.", "Expecting dramatic distortion; the effect is subtle thickening plus a high-end lift.", "Using it to fix a dull source rather than as gentle enhancement.", "Assuming it can be automated per-parameter; it is a single on/off analogue mode."], "scenario_contexts": ["Engaging 4K Mode while recording a spoken-word vocal to add polish.", "A/B testing 4K Mode on and off during tracking to teach analogue enhancement.", "Leaving 4K Mode off for a clean, uncoloured reference recording."], "formula_symbolic": "", "formula_words": ""}, {"id": "b50d5e3b-b5c0-4865-8ade-2d8241bd04d5", "term": "ActiveAnalogue", "definition": "A proprietary Solid State Logic control technology, used in the SSL Oracle console, that keeps the audio processing and summing entirely analogue while adding a digital control layer for full recall of gain, pan, routing and processing settings. It pairs an all-analogue (SuperAnalogue-derived) signal path with instant, session-recallable electronic control. 'ActiveAnalogue' and 'SSL' are trademarks of Solid State Logic; the underlying concept is a digitally controlled, recallable analogue console.", "plain_english": "This is SSL technology for a mixing desk that sounds fully analogue. A computer remembers and resets every control for you. So you can reload a past session in seconds. The audio still passes through real analogue parts.", "purpose_function": "It exists so engineers keep classic analogue sound and summing while gaining instant total recall, removing the slow manual reset that limits traditional analogue consoles.", "practical_application": "An engineer on an SSL Oracle recalls a snapshot to jump from tracking to mixing, restoring all analogue channel settings automatically.", "category": "Analogue Signal Path", "difficulty": "intermediate", "achievement_id": "52bf9944-db6d-4d98-9155-cbf456c60de8", "cross": [], "related_terms": ["SuperAnalogue", "SuperAnalogue Signal Path", "Total Recall", "Analogue Summing", "Digitally Controlled Amplifier (DCA)"], "common_mistakes": ["Assuming the audio is converted to digital; only the control layer is digital and the audio path stays analogue.", "Confusing it with SSL's older Total Recall, which only stored settings for manual resetting.", "Thinking it changes the tone; it controls and recalls the existing analogue path.", "Believing recall adds latency to the audio; the analogue signal is not delayed."], "scenario_contexts": ["Recalling a full mix instantly on an SSL Oracle between two artists in one day.", "Assigning a motorised fader to control a different processing path via snapshots.", "Teaching how digitally controlled analogue consoles differ from in-the-box mixing."], "formula_symbolic": "", "formula_words": ""}, {"id": "ce712a23-0ef6-41db-8730-5eb69314adb3", "term": "Asymmetric Drive", "definition": "A drive mode on Solid State Logic PureDrive mic preamps that shapes harmonic saturation so that even-order harmonics (especially the 2nd) dominate, giving more pronounced colouration and a softening of transients than the odd-harmonic 'Classic Drive' mode. 'Asymmetric Drive' is a Solid State Logic feature name; the underlying method is asymmetric waveform clipping, which generically produces even-order harmonic distortion.", "plain_english": "This is a setting on SSL PureDrive preamps that adds warmth. It boosts mostly even harmonics, which sound smooth and thick. It also softens sharp attacks a little. Use it when you want obvious, rich colour.", "purpose_function": "It exists to give a thicker, more coloured tone than the subtler odd-harmonic drive, letting engineers emphasise even-order warmth and gently tame transients.", "practical_application": "A technician selects Asymmetric Drive on a PureDrive preamp to thicken a thin vocal or soften an aggressive percussion transient during tracking.", "category": "Harmonic Saturation", "difficulty": "intermediate", "achievement_id": "52bf9944-db6d-4d98-9155-cbf456c60de8", "cross": [], "related_terms": ["PureDrive", "PureDrive Mode", "Classic Drive", "Variable Harmonic Drive", "Harmonic Distortion"], "common_mistakes": ["Assuming more drive always means harsh odd harmonics; this mode emphasises even harmonics.", "Overusing it on transient-rich sources and losing punch as transients soften.", "Confusing it with a distortion pedal; the effect is level-dependent preamp saturation.", "Thinking 'asymmetric' refers to stereo imbalance rather than waveform asymmetry."], "scenario_contexts": ["Choosing Asymmetric Drive to add body to a lead vocal on an SSL PureDrive.", "Softening the transient of a plucked bass for a smoother tone.", "Comparing Classic and Asymmetric Drive to hear odd- versus even-harmonic character."], "formula_symbolic": "", "formula_words": ""}, {"id": "684c635d-c046-4174-bc88-0040616d9531", "term": "PureDrive", "definition": "A proprietary Solid State Logic mic-preamp technology, built on the SuperAnalogue signal path, that adds variable harmonic drive: it blends 2nd- and 3rd-order harmonics to move from a clean, transparent tone to warm or harmonically rich, driven textures. It evolved from SSL's VHD (Variable Harmonic Drive) technology and appears in the Pure Drive Quad and Octo preamps. 'PureDrive' and 'SSL' are trademarks of Solid State Logic; the underlying method is a harmonic-saturation microphone preamplifier.", "plain_english": "This is an SSL microphone preamp design. It can sound very clean and clear. It can also add warmth or heavy grit when you want it. You blend gentle and edgy harmonics to taste.", "purpose_function": "It exists to give one preamp a wide tonal range, from transparent capture to characterful saturation, so engineers do not need separate clean and coloured units.", "practical_application": "A technician records a source clean in Clean mode, then engages a drive mode on a PureDrive Octo to add harmonic character while tracking.", "category": "Harmonic Saturation", "difficulty": "intermediate", "achievement_id": "52bf9944-db6d-4d98-9155-cbf456c60de8", "cross": [], "related_terms": ["PureDrive Mode", "Asymmetric Drive", "Classic Drive", "Variable Harmonic Drive", "SuperAnalogue"], "common_mistakes": ["Assuming it is only a distortion box; in Clean mode it is a linear, low-noise SuperAnalogue preamp.", "Thinking drive is the same as level; the drive amount is level/gain dependent.", "Confusing PureDrive with VHD; PureDrive evolved from VHD but adds SuperAnalogue clarity and switchable modes.", "Overdriving the input and blaming the microphone for the added harmonics."], "scenario_contexts": ["Recording a clean acoustic guitar, then adding subtle drive on a vocal.", "Using a PureDrive Octo across a drum kit for harmonic glue.", "A student learning how harmonic drive differs from simple clean gain."], "formula_symbolic": "", "formula_words": ""}, {"id": "fb498455-6707-4df3-82c1-3a4ec661294c", "term": "PureDrive Mode", "definition": "The harmonic-drive operating state of a Solid State Logic PureDrive mic preamp, engaged as an alternative to Clean mode. In this state the preamp adds level-dependent harmonic saturation; on the hardware the driven options are labelled 'Classic Drive' (predominantly odd harmonics, matching the SSL Origin console) and 'Asymmetric Drive' (predominantly even harmonics). 'PureDrive' is a Solid State Logic trademark; the underlying method is switchable harmonic-saturation preamp gain.", "plain_english": "This is the driven setting on an SSL PureDrive preamp. It adds warmth and colour instead of a clean sound. The amount grows as you push the level higher. You pick between smoother or edgier harmonics.", "purpose_function": "It exists to let an engineer switch a transparent preamp into a coloured, harmonically rich one, shaping tone right at the input stage.", "practical_application": "A technician switches out of Clean into a drive mode on a PureDrive to add analogue character while recording a source.", "category": "Harmonic Saturation", "difficulty": "intermediate", "achievement_id": "52bf9944-db6d-4d98-9155-cbf456c60de8", "cross": [], "related_terms": ["PureDrive", "Asymmetric Drive", "Classic Drive", "Clean Mode", "Variable Harmonic Drive"], "common_mistakes": ["Expecting a single button labelled 'PureDrive'; the driven modes are labelled Classic Drive and Asymmetric Drive.", "Assuming the drive level is fixed; it depends on the input gain/level.", "Leaving drive engaged on material meant to be captured cleanly.", "Confusing odd-harmonic Classic Drive with even-harmonic Asymmetric Drive."], "scenario_contexts": ["Switching from Clean to a drive mode to warm up a DI bass.", "Auditioning Classic versus Asymmetric drive on a vocal.", "Teaching the difference between clean gain and driven, saturated gain."], "formula_symbolic": "", "formula_words": ""}, {"id": "e3658dc1-d6da-4488-8d5a-af8208c8ade5", "term": "SuperAnalogue", "definition": "A proprietary Solid State Logic analogue circuit design, introduced with the 9000-series consoles, that removes electrolytic capacitors from the direct audio path using DC-coupled stages to achieve very low noise, low harmonic distortion, wide bandwidth and low phase shift. 'SuperAnalogue' and 'SSL' are trademarks of Solid State Logic; the underlying method is generic DC-coupled, capacitor-free low-distortion audio circuit design.", "plain_english": "This is an SSL way of building analogue circuits. It leaves out certain capacitors that can colour the sound. The result is very clean, quiet, wide-range audio. It also keeps timing and detail accurate.", "purpose_function": "It exists to pass audio as transparently as possible, preserving detail and phase accuracy for high-resolution recording and mixing.", "practical_application": "An engineer relies on SuperAnalogue channels for clean, low-noise tracking where uncoloured, faithful capture matters.", "category": "Analogue Signal Path", "difficulty": "intermediate", "achievement_id": "52bf9944-db6d-4d98-9155-cbf456c60de8", "cross": [], "related_terms": ["SuperAnalogue Signal Path", "ActiveAnalogue", "DC-Coupled Circuit", "Total Harmonic Distortion (THD)", "Variable Harmonic Drive"], "common_mistakes": ["Thinking 'SuperAnalogue' adds colour; it is designed to be transparent, not to distort.", "Assuming all SSL gear is SuperAnalogue; it names a specific 9000-series-era design.", "Confusing it with the coloured SSL 4000-series sound; SuperAnalogue aims for neutrality.", "Believing 'DC-coupled' just means more bass; it means removing series signal-path capacitors that cause colouration and phase shift."], "scenario_contexts": ["Choosing a SuperAnalogue channel strip for a clean orchestral recording.", "Comparing SuperAnalogue transparency to the coloured 4000-series sound.", "Explaining why a capacitor-free path reduces phase shift."], "formula_symbolic": "", "formula_words": ""}, {"id": "ea6f4458-6f9c-4665-8f61-131c0baa659c", "term": "SuperAnalogue Signal Path", "definition": "The audio signal chain built with Solid State Logic's SuperAnalogue design: DC-coupled stages with no electrolytic capacitors in the direct signal path. This yields very low noise and harmonic distortion, wide bandwidth extending above the audible range, low phase shift across the audio band, and high headroom. It was introduced with SSL's 9000-series consoles. 'SuperAnalogue' and 'SSL' are trademarks of Solid State Logic; the concept is a capacitor-free, DC-coupled low-distortion signal path.", "plain_english": "This is the actual route audio takes through SSL's SuperAnalogue circuits. It leaves out capacitors that can smear the sound. It is very quiet and handles very loud signals. It stays flat well beyond what we can hear.", "purpose_function": "It exists to move audio from input to output with minimal noise, distortion and phase shift, so the recording stays faithful to the source.", "practical_application": "A technician uses the SuperAnalogue path when tracking wide-dynamic sources that need clean headroom and low noise.", "category": "Analogue Signal Path", "difficulty": "intermediate", "achievement_id": "52bf9944-db6d-4d98-9155-cbf456c60de8", "cross": [], "related_terms": ["SuperAnalogue", "ActiveAnalogue", "DC-Coupled Circuit", "Equivalent Input Noise (EIN)", "Headroom"], "common_mistakes": ["Assuming high headroom means you should record hotter; still leave margin for peaks.", "Thinking the above-audible response colours the sound; it mainly reduces in-band phase shift.", "Confusing transparency with a lack of usefulness; the path is intentionally neutral.", "Ignoring gain staging because noise is low; poor gain staging still degrades results."], "scenario_contexts": ["Recording a loud brass section that needs clean headroom.", "Measuring equivalent input noise to verify a low-noise SuperAnalogue preamp.", "Explaining why a capacitor-free path improves phase linearity."], "formula_symbolic": "", "formula_words": ""}, {"id": "f7e14ef5-a594-4ced-b6ce-9e33da3df74f", "term": "VHD", "definition": "Solid State Logic's Variable Harmonic Drive: an all-analogue circuit that adds level-dependent harmonic distortion, blending 2nd- and 3rd-order harmonics as input gain rises. At low settings it gives gentle valve-style warmth or a slight transistor edge; at high gain it produces intense, trashy, transistor-like distortion. 'VHD' and 'SSL' are trademarks of Solid State Logic; the underlying method is a variable harmonic-saturation (harmonic-distortion) generator.", "plain_english": "This is SSL's way of adding harmonic colour to sound. Turn it up gently for warmth. Push it hard for gritty, aggressive distortion. You can dial between smooth and edgy character.", "purpose_function": "It exists to let engineers add controllable harmonic character at the preamp stage, from subtle warmth to heavy saturation, without outboard effects.", "practical_application": "A technician raises VHD while tracking a vocal or bass to add warmth, or drives it hard for a deliberately dirty tone.", "category": "Harmonic Saturation", "difficulty": "intermediate", "achievement_id": "52bf9944-db6d-4d98-9155-cbf456c60de8", "cross": [], "related_terms": ["Variable Harmonic Drive", "VHD Pre", "VHD+ Pre", "PureDrive", "Harmonic Distortion"], "common_mistakes": ["Assuming VHD is a clean gain control; it deliberately adds harmonic distortion.", "Expecting only warmth; high settings produce aggressive, trashy distortion.", "Confusing 2nd-harmonic (valve-like) with 3rd-harmonic (transistor-like) character.", "Driving it hard by accident and blaming the source or converter."], "scenario_contexts": ["Adding gentle VHD warmth to a clean vocal.", "Cranking VHD for a gritty rock bass tone.", "Teaching the difference between even and odd harmonic character."], "formula_symbolic": "", "formula_words": ""}, {"id": "b5cfed11-499d-497f-9929-c9e0baa17d7f", "term": "VHD Pre", "definition": "A Solid State Logic microphone/line preamplifier built around the VHD (Variable Harmonic Drive) circuit, offering an all-analogue path with a control that blends 2nd- and 3rd-order harmonic distortion, from clean warmth to heavy saturation. It appeared as the multi-channel XLogic Alpha VHD Pre. 'VHD' and 'SSL' are trademarks of Solid State Logic; the underlying method is a harmonic-saturation microphone preamplifier.", "plain_english": "This is an SSL microphone preamp box. It boosts quiet mic signals to a usable level. It also adds SSL's harmonic colour when you want it. You control how clean or dirty it sounds.", "purpose_function": "It exists to provide clean gain plus optional harmonic character in one preamp, so engineers can shape tone at the input stage.", "practical_application": "A technician plugs a microphone into a VHD Pre, sets the gain, then adds harmonic drive to taste while tracking.", "category": "Harmonic Saturation", "difficulty": "intermediate", "achievement_id": "52bf9944-db6d-4d98-9155-cbf456c60de8", "cross": [], "related_terms": ["VHD", "VHD+ Pre", "Variable Harmonic Drive", "PureDrive", "Microphone Preamplifier"], "common_mistakes": ["Treating the VHD control like a clean trim; it adds distortion.", "Forgetting to set base gain before adding drive.", "Assuming it is transparent by default; the character depends on the VHD setting.", "Confusing the original VHD Pre with the later VHD+ Pre, which adds features."], "scenario_contexts": ["Recording vocals through a VHD Pre with a touch of harmonic warmth.", "Using several VHD Pre channels for drum overheads.", "Comparing a clean preamp to a VHD Pre for tonal character."], "formula_symbolic": "", "formula_words": ""}, {"id": "d2e9c002-cab5-42ae-81c7-aecd1d337508", "term": "VHD+ Pre", "definition": "The updated 500-series Solid State Logic VHD preamplifier module. Like the original VHD Pre it uses the Variable Harmonic Drive circuit, with a control that blends 2nd- to 3rd-order harmonics, but it adds a front-panel line/instrument input with a switchable high-impedance (Hi-Z) setting, an 18 dB/octave variable high-pass filter (roughly 15 Hz to 500 Hz), and up to +75 dB of gain with a plus/minus 20 dB trim. 'VHD' and 'SSL' are trademarks of Solid State Logic; the underlying method is a harmonic-saturation mic/line preamplifier.", "plain_english": "This is the newer version of SSL's VHD preamp. It fits a 500-series rack. It adds a front input for instruments and a filter to cut low rumble. You still dial in warm or gritty harmonics.", "purpose_function": "It exists to bring VHD harmonic drive to the 500-series format, with an added line/DI input and high-pass filter for more versatile recording.", "practical_application": "A technician racks a VHD+ Pre in a 500-series chassis and plugs a bass into the front Hi-Z input, adding drive for tone.", "category": "Harmonic Saturation", "difficulty": "intermediate", "achievement_id": "52bf9944-db6d-4d98-9155-cbf456c60de8", "cross": [], "related_terms": ["VHD Pre", "VHD", "Variable Harmonic Drive", "500 Series", "High-Pass Filter"], "common_mistakes": ["Assuming the '+' only means more gain; it also adds a line/DI input and a filter.", "Forgetting to select Hi-Z when plugging in a passive instrument.", "Leaving the high-pass filter off and capturing unwanted low-end rumble.", "Confusing it with the original VHD Pre, which lacks these features."], "scenario_contexts": ["Recording a DI bass through the VHD+ Pre front input.", "Using the high-pass filter to remove stage rumble on a live capture.", "Adding harmonic drive to a vocal in a 500-series rack."], "formula_symbolic": "", "formula_words": ""}, {"id": "538611af-4100-4b93-970c-11c1f7673c03", "term": "Variable Harmonic Drive", "definition": "The full name of Solid State Logic's VHD circuit: an all-analogue, level-dependent harmonic-distortion generator that blends 2nd- and 3rd-order harmonics as gain increases, ranging from gentle valve-style warmth to intense transistor-like distortion. It is used across SSL's VHD, VHD+ and PureDrive products. 'Variable Harmonic Drive' and 'SSL' are trademarks of Solid State Logic; the underlying method is variable harmonic saturation (mixing even- and odd-order harmonic distortion).", "plain_english": "This is the full name for SSL's VHD feature. It adds harmonic colour to audio. You can pick smooth warmth or harsh grit. The effect grows as you turn it up.", "purpose_function": "It exists to give engineers one adjustable way to add harmonic character, from subtle to extreme, at the analogue input stage.", "practical_application": "A technician uses Variable Harmonic Drive on a preamp to warm a vocal, or to intentionally distort a bass.", "category": "Harmonic Saturation", "difficulty": "intermediate", "achievement_id": "52bf9944-db6d-4d98-9155-cbf456c60de8", "cross": [], "related_terms": ["VHD", "VHD Pre", "VHD+ Pre", "PureDrive", "Harmonic Distortion"], "common_mistakes": ["Reading 'drive' as clean gain; it adds harmonic distortion.", "Assuming a fixed sound; the harmonic blend and amount change with gain.", "Confusing even-order (warm) with odd-order (edgy) harmonics.", "Expecting the same control layout on every SSL product that uses it."], "scenario_contexts": ["Explaining what the VHD acronym stands for to a student.", "Dialling warmth into a clean vocal with Variable Harmonic Drive.", "Pushing it hard for an aggressive, saturated tone."], "formula_symbolic": "", "formula_words": ""}, {"id": "a8ee2258-9fa9-49a6-8a4b-dd81bff745ec", "term": "A-FADA", "definition": "A-FADA (Analogue Faders Follow DAW Automation) is a Solid State Logic automation mode for AWS and Duality consoles in which the console's motorised analogue faders are driven directly by automation data written in a DAW. The audio stays in the analogue signal path while level moves are stored and replayed by the workstation rather than by the console's onboard automation computer. The name is an SSL trademark; the underlying method is standard DAW fader automation applied to motorised analogue faders.", "plain_english": "A-FADA is a Solid State Logic feature for some mixing desks. The letters stand for Analogue Faders Follow DAW Automation. A DAW is the recording software on a computer. The desk's motorised faders move by themselves. They follow the volume moves you record in the software. The sound still passes through the analogue desk, not the computer.", "purpose_function": "It lets engineers keep an all-analogue mix signal path while using the familiar, editable automation tools of a DAW to record and replay fader moves. It exists to bridge analogue console sound with digital automation workflows.", "practical_application": "On an AWS or Duality, the engineer switches faders to A-FADA and writes level automation in the DAW; the physical faders then replay those moves on playback. This lets the analogue mix be recalled and edited later.", "category": "SSL Automation", "difficulty": "intermediate", "achievement_id": "fd008675-c891-4fe3-9917-a760eae2345d", "cross": [], "related_terms": ["Delta-Control", "AWSomation", "Total Recall", "Motorised Fader", "DAW Automation", "Mix Pass"], "common_mistakes": ["Thinking A-FADA processes the audio digitally; the audio stays analogue and only the fader control data lives in the DAW.", "Confusing A-FADA with Delta-Control; A-FADA drives the analogue faders from DAW data, while Delta-Control records console moves as a DAW plug-in.", "Leaving the DAW track in the wrong automation mode, so fader moves are not written or get overwritten."], "scenario_contexts": ["Mixing a song on an SSL Duality while keeping recallable, editable fader automation in the DAW.", "Recalling an analogue mix days later by replaying stored DAW fader data through the console.", "Riding a vocal level with graphical edits in the DAW that then move the physical console fader."], "formula_symbolic": "", "formula_words": ""}, {"id": "e60f0a4a-8f21-4dca-b7e2-92eaeb8e3a90", "term": "AWSomation", "definition": "AWSomation is Solid State Logic's onboard mix automation system for the AWS-series analogue workstation consoles (AWS 900 and 900+ SE). It records, stores and replays fader level moves and switch/mute events as mix passes using the console's motorised faders, and its stored data is managed through SSL's Logictivity software. The name is an SSL trademark; the underlying method is conventional console mix-pass automation.", "plain_english": "AWSomation is the built-in automation on Solid State Logic's AWS mixing desks. Automation means the desk remembers your volume and mute moves. It saves them as a 'mix pass' and plays them back later. The desk uses motorised faders that move on their own. You manage the saved mixes with SSL's computer software.", "purpose_function": "It exists so engineers can build a mix over several passes, storing and recalling fader and mute moves on an analogue console without relying on an external DAW. It brings DAW-style automation to an analogue desk.", "practical_application": "An engineer creates a mix pass, rides faders and mutes, then re-runs the pass to refine moves while the motorised faders replay the stored automation. Saved mix data is archived and reloaded via Logictivity.", "category": "SSL Automation", "difficulty": "intermediate", "achievement_id": "fd008675-c891-4fe3-9917-a760eae2345d", "cross": [], "related_terms": ["A-FADA", "Total Recall", "Mix Pass", "Motorised Fader", "Delta-Control", "Automation Mode"], "common_mistakes": ["Confusing AWSomation with Total Recall; AWSomation records dynamic fader and mute moves, while Total Recall stores static control positions for manual reset.", "Assuming AWSomation writes automation into a DAW; it is the console's own onboard system managed through Logictivity.", "Choosing the wrong automation mode (for example absolute instead of Trim), which overwrites existing moves."], "scenario_contexts": ["Automating a full mix on an AWS 900+ SE across several passes.", "Trimming an already-automated vocal level using an automation trim mode.", "Archiving and reloading stored mix data through the Logictivity software."], "formula_symbolic": "", "formula_words": ""}, {"id": "1b61095a-f233-42c0-85f4-33fde1d14279", "term": "Delta-Control", "definition": "Delta-Control (delta-Ctrl) is a Solid State Logic automation system for Duality and AWS consoles, supplied as a native plug-in (AAX/RTAS/AU/VST/VST3) that lets the analogue console be automated as though it were a DAW plug-in. Console fader, mute and switch movements are recorded into the DAW's automation lanes over high-speed Ethernet and, on playback, are converted back into control messages that move the physical console while the audio passes through unprocessed. The name is an SSL trademark; the underlying method is standard DAW plug-in automation applied to an analogue console.", "plain_english": "Delta-Control is a Solid State Logic feature for some mixing desks. It adds a plug-in inside your recording software. The plug-in records the desk's fader and mute moves onto the software's timeline. On playback it moves the real faders again. The sound still passes through the analogue desk, not the plug-in.", "purpose_function": "It lets engineers store and edit analogue-console automation inside the DAW timeline, so console mixes become fully recallable and editable like plug-in automation. It exists to fold an analogue desk into a modern DAW workflow.", "practical_application": "The engineer inserts a Delta-Control plug-in on a DAW track, links it to a console channel, and records fader and mute moves that later replay on the physical console. Existing DAW fader data can be pasted in to drive the console.", "category": "SSL Automation", "difficulty": "intermediate", "achievement_id": "fd008675-c891-4fe3-9917-a760eae2345d", "cross": [], "related_terms": ["A-FADA", "AWSomation", "Total Recall", "Mix Pass", "Motorised Fader", "DAW Automation"], "common_mistakes": ["Believing the audio is processed by the plug-in; the plug-in only carries control data, and the audio stays in the analogue path.", "Confusing Delta-Control with A-FADA; they are related, but Delta-Control records console moves as DAW plug-in automation.", "Leaving the DAW automation mode inconsistent (for example read versus write), so moves are lost or not replayed."], "scenario_contexts": ["Automating an SSL Duality mix entirely within the Pro Tools timeline.", "Editing recorded console fader rides graphically in the DAW.", "Recalling a past analogue mix by replaying stored Delta-Control automation through the console."], "formula_symbolic": "", "formula_words": ""}, {"id": "5312fba2-a879-4e58-81a5-aacddf626349", "term": "Ultimation", "definition": "Ultimation is Solid State Logic's moving-fader mix automation system, introduced in the early 1990s for SSL 4000-series (and later) consoles and used with the G-series Studio Computer. It develops SSL's earlier VCA-based automation by adding a motor-driven (moving) fader to each channel, so automated level moves are both stored electronically and physically shown and replayed on the faders. The name is an SSL trademark; the underlying method is motorised-fader mix automation combined with VCA control.", "plain_english": "Ultimation is Solid State Logic's automation for its 4000 mixing desks. It arrived in the early 1990s. Older SSL desks changed volume using hidden electronic circuits called VCAs. Ultimation added faders with small motors. The faders now move by themselves to show and replay your volume changes.", "purpose_function": "It gives engineers automated mixing with the visual and hands-on feedback of faders that physically move, improving on earlier VCA-only automation where the fader knobs stayed still. This makes it easy to see and grab the current level.", "practical_application": "On an SSL 4000 with a G-series computer, an engineer writes fader moves that the motorised faders then replay, and can grab a moving fader mid-mix to update a level. The fader position always shows the automated level.", "category": "SSL Automation", "difficulty": "intermediate", "achievement_id": "fd008675-c891-4fe3-9917-a760eae2345d", "cross": [], "related_terms": ["Total Recall", "VCA", "Motorised Fader", "Mix Pass", "AWSomation", "Automation Mode"], "common_mistakes": ["Confusing Ultimation with Total Recall; Ultimation replays dynamic fader moves, while Total Recall only stores static control settings for manual reset.", "Assuming all SSL automation uses moving faders; earlier G-series automation was VCA-based with non-moving faders.", "Thinking the motor changes the sound; the motor only positions the fader and does not process the audio by itself."], "scenario_contexts": ["Mixing on a classic SSL 4000 G+ where the faders move to replay automation.", "Grabbing a moving fader mid-mix to update a level and dropping back into automation.", "Reviewing an automated mix visually as the motorised faders show each stored move."], "formula_symbolic": "", "formula_words": ""}, {"id": "3776ffdc-24aa-42d7-9e11-a4d1ab6a4c86", "term": "AWS delta", "definition": "The AWS delta (styled AWS δelta) is a Solid State Logic hybrid mixing console that pairs a compact 24-fader SuperAnalogue analogue mixer with an integrated digital audio workstation (DAW) control surface. It is sold as the AWS 924 (24 channels) and AWS 948 (48 summing channels), providing 24 SuperAnalogue mic preamps, SSL channel EQ and dynamics, and a stereo bus compressor based on the G-Series design. The δelta system is SSL's proprietary layer that lets the console's faders and mix bus be automated as a native DAW plug-in. 'AWS', 'δelta' and 'SuperAnalogue' are SSL trademarks; the underlying method is generic analogue summing combined with DAW control-surface integration.", "plain_english": "The AWS delta is a small analogue mixing desk made by Solid State Logic. It also works as a control surface for your recording software. You get 24 studio-quality mic inputs and classic SSL sound processing. The 'delta' part lets the desk's fader moves be saved inside your software.", "purpose_function": "It exists to blend hands-on analogue mixing with software control, so an engineer can track, mix and automate from one compact console instead of a separate mixer and controller.", "practical_application": "A studio engineer records through the SuperAnalogue preamps, mixes on the analogue bus, and uses δelta plug-ins to recall fader automation inside Pro Tools or Logic.", "category": "Hybrid Analogue Console", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["Duality Fuse", "SuperAnalogue", "δelta control", "Centre section", "Bus compressor", "In-line console"], "common_mistakes": ["Thinking the AWS is a fully digital console; the audio path is analogue and only the control and automation layer is digital.", "Assuming δelta records the audio itself; it automates fader and bus levels as DAW data, not the analogue signal.", "Confusing the 24-fader frame with channel count; the AWS 948 offers 48 summing channels across the same 24 faders."], "scenario_contexts": ["A commercial studio tracks a band through 24 SuperAnalogue preamps while controlling Pro Tools from the same surface.", "An engineer recalls a previous session's fader automation using the δelta plug-in during a mix revision.", "A producer sums DAW stems through the analogue mix bus for added depth before mastering."], "formula_symbolic": "", "formula_words": ""}, {"id": "862a9d92-4748-438c-82ab-f029cea46981", "term": "BiG SiX", "definition": "The BiG SiX is a Solid State Logic desktop SuperAnalogue mixer with a built-in class-compliant USB audio interface. It provides four mono SuperAnalogue mic-preamp channels plus stereo line channels (up to 18 inputs at mixdown), each mono channel carrying a one-knob channel compressor and a three-band E-Series-style EQ, and a G-Series-style stereo bus compressor on the main mix bus. The USB interface runs 16 channels at 24-bit/96 kHz. 'BiG SiX' and 'SuperAnalogue' are SSL trademarks; it is an expanded version of the SSL SiX and uses a conventional split (non-in-line) desktop mixer topology rather than a large-format in-line console.", "plain_english": "The BiG SiX is a small SSL mixing desk that sits on your desktop. It has four studio-grade mic inputs and several line inputs. It also works as a USB sound card for your computer. It gives you SSL's compressor and EQ sound in a compact, portable box.", "purpose_function": "It exists to bring SSL analogue processing and a USB interface into small studios and hybrid setups, letting users record, mix and connect to a computer from one desktop unit.", "practical_application": "A project-studio engineer records vocals through the SuperAnalogue preamps, shapes them with the channel compressor and EQ, and streams audio to and from a DAW over USB.", "category": "Desktop Analogue Mixer", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["SiX", "SuperAnalogue", "Bus compressor", "Channel strip", "USB audio interface", "AWS delta"], "common_mistakes": ["Treating BiG SiX like an in-line large-format console; it is a compact split-format desktop mixer.", "Overlooking that its USB interface is class-compliant, so it runs on macOS and Windows without extra drivers.", "Assuming the bus compressor matches the channel compressor; the mix bus uses a fixed-ratio G-Series-style design."], "scenario_contexts": ["A songwriter tracks and sums a mix through BiG SiX while recording stems into a DAW over USB.", "A podcast host uses its mic preamps and compressor for clean, level voice recording.", "A hybrid mixer routes DAW tracks out to the analogue bus for SSL summing, then back over USB."], "formula_symbolic": "", "formula_words": ""}, {"id": "e8d60072-3cf6-496a-9c1e-9533532ae644", "term": "Duality Fuse", "definition": "The Duality Fuse is a Solid State Logic large-format SuperAnalogue mixing console with a dual-path channel architecture (separate channel/record and monitor signal paths), integrated δelta DAW control, and a built-in Fusion analogue colouration processor in the centre section. Each channel offers dual SuperAnalogue and VHD (Variable Harmonic Drive) mic preamps, the classic SSL channel strip (switchable EQ, filters, compressor/gate), and routing to three stereo mix busses and 24 track busses. 'Duality', 'Fuse', 'Fusion', 'SuperAnalogue' and 'δelta' are SSL trademarks; the separate channel/monitor paths, centre section and bus routing are generic console concepts, not unique to SSL.", "plain_english": "The Duality Fuse is a large SSL studio mixing console. Each channel has two signal paths, one for recording and one for monitoring. It includes SSL's famous EQ, compressors and mic preamps. A built-in 'Fusion' processor adds analogue warmth and colour to your mix.", "purpose_function": "It exists to give large studios a full analogue console with recallable settings and tight DAW integration, plus onboard colour processing for finished-sounding mixes.", "practical_application": "A mix engineer routes DAW returns across the console's channel and monitor paths, processes the mix bus through Fusion, and automates levels with δelta.", "category": "Large-format Analogue Console", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["AWS delta", "SuperAnalogue", "δelta control", "VHD", "Bus compressor", "Centre section"], "common_mistakes": ["Thinking Fusion is a plug-in; it is an onboard analogue colouration processor in the centre section.", "Confusing the channel path and monitor path, which carry different sources during tracking.", "Assuming the console is digital because it recalls settings; the audio path stays fully analogue."], "scenario_contexts": ["A commercial studio tracks a session using dual mic preamps and separate monitor paths.", "An engineer mixes in the box but sums and colours the final bus through the console and Fusion.", "A facility recalls a client's console settings via δelta for a revision session."], "formula_symbolic": "", "formula_words": ""}, {"id": "019fb1bf-c404-4ae4-ad49-73a83df9dd5c", "term": "ORIGIN", "definition": "ORIGIN is a Solid State Logic analogue in-line mixing console for hybrid production, available in 16- and 32-channel frames. It uses a traditional in-line architecture in which each channel has large and small faders feeding separate channel and monitor paths, PureDrive discrete mic preamps with switchable clean/drive character, the SSL E-Series four-band EQ, 16 track busses, and the SSL stereo bus compressor; it has no digital total recall or fader automation. 'ORIGIN', 'PureDrive' and 'SuperAnalogue' are SSL trademarks, while the in-line topology, channel/monitor paths and bus routing are generic console-design concepts.", "plain_english": "ORIGIN is an all-analogue SSL mixing console for studios. Each channel has two faders and two signal paths. It uses SSL's classic EQ and bus compressor for that signature sound. It has no computer recall, so you set it by hand like a classic desk.", "purpose_function": "It exists to offer a pure analogue SSL console at a smaller size and price, pairing hands-on mixing with a modern DAW-based workflow.", "practical_application": "An engineer tracks through PureDrive preamps and mixes on the analogue bus, patching 500-series modules into the modular centre section as needed.", "category": "Analogue In-line Console", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["Oracle", "In-line console", "Channel path", "Monitor path", "Bus compressor", "PureDrive"], "common_mistakes": ["Expecting total recall; ORIGIN is a manual analogue console with no digital automation.", "Confusing the large and small faders, which control the channel and monitor paths.", "Assuming PureDrive is only clean; its Drive mode adds gain-dependent harmonic saturation."], "scenario_contexts": ["A studio tracks a live band through 32 channels of analogue SSL processing.", "A mix engineer sums DAW stems through the mix bus and SSL bus compressor.", "An educator teaches in-line signal flow using ORIGIN's channel and monitor paths."], "formula_symbolic": "", "formula_words": ""}, {"id": "bfbf9795-76dc-4104-8918-5dddcccbaa3a", "term": "Oracle", "definition": "Oracle is a Solid State Logic fully analogue in-line mixing console, offered in 24- and 48-channel formats, that adds ActiveAnalogue technology for near-instant total recall of its analogue settings. Each channel provides PureDrive mic preamps, an SSL four-band EQ with switchable E/G curves, separate channel and monitor paths, and routing to multiple stereo mix and track busses; the centre section includes THE BUS+ VCA bus compressor with dynamic EQ, and SSL 360 software lets faders switch between analogue and DAW control. 'Oracle', 'ActiveAnalogue', 'PureDrive' and 'THE BUS+' are SSL trademarks; the in-line architecture, channel/monitor paths and VCA bus compression are generic console concepts.", "plain_english": "Oracle is a large all-analogue SSL mixing console. Its audio stays analogue, but a control system recalls your settings in seconds. This gives you classic sound with the speed of a digital desk. It uses SSL's PureDrive preamps and its famous EQ and bus compressor.", "purpose_function": "It exists to combine pure analogue sound with fast, recallable setups, solving the slow reset problem of traditional analogue consoles.", "practical_application": "A mix engineer loads a client's session in seconds via ActiveAnalogue, then mixes on analogue channels while switching some faders to DAW control.", "category": "Analogue In-line Console", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["ORIGIN", "Duality Fuse", "In-line console", "PureDrive", "Bus compressor", "Centre section"], "common_mistakes": ["Thinking Oracle is digital; the signal path is analogue and only the recall and control is digital.", "Assuming recall restores audio; ActiveAnalogue resets the analogue controls, not stored sound.", "Confusing THE BUS+ centre-section processor with a per-channel compressor."], "scenario_contexts": ["A busy mix room switches between multiple client sessions using fast total recall.", "An engineer mixes through analogue channels while controlling the DAW from the same faders.", "A facility bus-compresses the main mix using THE BUS+ with its dynamic EQ."], "formula_symbolic": "", "formula_words": ""}, {"id": "6b5bf2aa-94ec-4ce9-a6f3-fdc9ed7f537b", "term": "SiX", "definition": "SiX is a Solid State Logic compact desktop analogue mixer with two full SuperAnalogue channel strips (each with a mic/line preamp, a one-knob channel compressor and a two-band EQ), plus stereo line and external inputs, two stereo cue sends, and a two-knob stereo bus compressor whose circuit topology derives from the SL 4000 G-Series console. At mixdown it offers up to twelve channels of SSL analogue summing. 'SiX' and 'SuperAnalogue' are SSL trademarks; it uses a conventional small-format (non-in-line) topology, and the mix bus applies the generic VCA bus-compression method.", "plain_english": "SiX is a small SSL mixer that fits on your desk. It has two studio-quality channels with mic inputs, compression and EQ. Its main bus uses SSL's classic G-Series compressor sound. You can also use it to sum up to twelve channels for mixdown.", "purpose_function": "It exists to bring core SSL analogue sound to small, portable setups, working both as a recording front end and as an analogue summing mixer.", "practical_application": "An engineer records two mics through SiX's channel strips, then uses it to sum DAW stems through the analogue bus and G-Series bus compressor.", "category": "Desktop Analogue Mixer", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["BiG SiX", "SuperAnalogue", "Bus compressor", "Channel strip", "Summing mixer", "Cue send"], "common_mistakes": ["Expecting a built-in USB audio interface; the original SiX has none, unlike the BiG SiX.", "Assuming all inputs have full processing; only the two mono channels carry the compressor and EQ.", "Thinking the bus compressor is variable-ratio; it is a fixed-ratio G-Series-style design."], "scenario_contexts": ["A mobile engineer tracks a two-mic session on location with SiX.", "A producer sums a mix of DAW stems through SiX for analogue depth.", "A podcaster records voices and uses the channel compressor to even out levels."], "formula_symbolic": "", "formula_words": ""}, {"id": "6dde24ba-26e1-4e6d-94da-8d725195bb4c", "term": "Super 9000", "definition": "The Super 9000 is a Solid State Logic all-analogue channel strip in a rackmount (19-inch) format, derived from the channel path of the SL 9000 SuperAnalogue console. It combines a SuperAnalogue mic/line/instrument preamp with a switchable VHD (Variable Harmonic Drive) circuit for 2nd/3rd-order harmonic colour, a four-band EQ switchable between the 9000-series ('pink knob' 292) and E-Series ('black knob' 242) curves, high- and low-pass filters, and a 9000-series channel compressor plus a gate/expander. 'Super 9000', 'SuperAnalogue' and 'VHD' are SSL trademarks; the underlying channel-strip concept (preamp, EQ and dynamics in series) is generic.", "plain_english": "The Super 9000 is a single SSL channel strip in a rack box. It has one high-quality mic input, EQ, a compressor and a gate. The sound comes from SSL's 9000-series studio console. You use it to record or process one track at a time with classic SSL tone.", "purpose_function": "It exists to put the sound of SSL's 9000-series console channel into a standalone unit, giving users that processing without a full console.", "practical_application": "An engineer tracks a lead vocal through the Super 9000's preamp, EQ and compressor to print an SSL-flavoured sound to the DAW.", "category": "Analogue Channel Strip", "difficulty": "intermediate", "achievement_id": "b62d9de2-a107-4fa9-aad0-07a9955b49c4", "cross": [], "related_terms": ["SuperAnalogue", "VHD", "Channel strip", "SSL EQ", "Bus compressor", "Duality Fuse"], "common_mistakes": ["Calling the Super 9000 a console; it is a single-channel rackmount channel strip.", "Ignoring the EQ curve switch, which toggles between 9000-series and E-Series voicings.", "Assuming VHD is unwanted distortion; it is a deliberate harmonic-colour control."], "scenario_contexts": ["A vocalist's take is recorded through the Super 9000 for an SSL front-end sound.", "An engineer processes a single stem through the strip during mixdown.", "A project studio uses it as a high-quality preamp and dynamics stage into a DAW."], "formula_symbolic": "", "formula_words": ""}, {"id": "796a6bae-eaeb-4372-bf32-abbca24f9255", "term": "BLITZER", "definition": "Blitzer is a software compressor plug-in from Solid State Logic (SSL), the trademark owner. It models the behaviour of several classic analogue compressors, offering multiple selectable compression curves across ten ratios, plus harmonic drive, a parallel wet/dry mix, transient shaping and a detection side-chain. The name is proprietary; the underlying methods are generic valve, optical, FET and VCA compression emulated in the digital domain.", "plain_english": "Blitzer is a compressor plug-in made by Solid State Logic, or SSL. A compressor evens out the loud and quiet parts of a sound. Blitzer copies the tone of several old hardware compressors. You pick a style, then add drive or blend for extra colour.", "purpose_function": "It gives engineers many classic compression characters in one plug-in, so they can control level and add analogue-style colour to individual tracks or a whole mix.", "practical_application": "A technician loads Blitzer on vocals, drums or room mics to control dynamics, then uses the Mix control for parallel compression or Drive to add saturation.", "category": "Compressor Plug-in", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["SSL Bus Compressor", "Parallel Compression", "VCA Compressor", "Side-chain", "Makeup Gain", "Ratio"], "common_mistakes": ["Assuming Blitzer is one modelled unit rather than several compressor characters in a single plug-in", "Engaging the most aggressive BLITZ (max-drive) setting on a full mix and adding unwanted distortion", "Running Mix at 100% and losing the dry blend when parallel compression was intended"], "scenario_contexts": ["Adding aggressive, coloured compression to a drum room mic", "Gently glueing a mix bus with a low ratio and a parallel Mix blend", "Adding harmonic drive to a flat vocal so it sits better in a mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "49012b69-67f8-49d8-94d8-d60685b965cb", "term": "Fusion HF Compressor", "definition": "The SSL Fusion HF Compressor is a software plug-in from Solid State Logic (SSL), the trademark owner, that emulates the high-frequency smoothing (HF compressor) circuit of the SSL Fusion analogue stereo processor. It applies dynamic gain reduction only to high frequencies above an adjustable crossover, taming harshness rather than compressing the full spectrum. The underlying method is generic frequency-selective (high-frequency) compression.", "plain_english": "This is a plug-in from Solid State Logic, or SSL. It copies the high-frequency part of SSL's Fusion hardware. It only squashes harsh, bright sounds, not the whole signal. Engineers use it to make a sharp, brittle top end sound smoother.", "purpose_function": "It exists to smooth harsh or brittle high frequencies on stems, mixes and masters while leaving the lower frequencies untouched.", "practical_application": "A technician sets the crossover (X-Over) frequency and threshold so only the harsh highs are compressed, then blends the result with the Mix control for gentle top-end rounding.", "category": "Frequency-Selective Compression", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["De-esser", "Multiband Compression", "Crossover", "Threshold", "Parallel Compression", "SSL Bus Compressor"], "common_mistakes": ["Setting the crossover too low so wanted midrange is dulled", "Confusing it with a de-esser aimed only at vocal sibilance", "Expecting full-band level control from a high-frequency-only compressor"], "scenario_contexts": ["Smoothing harsh cymbals on a drum bus", "Rounding a bright vocal without dulling its body", "Taming digital harshness on the mix bus during mastering"], "formula_symbolic": "", "formula_words": ""}, {"id": "0c5dea8e-be45-46e1-8201-b817c00c5c36", "term": "G-Series Bus Compressor", "definition": "The G-Series Bus Compressor is the VCA-based stereo bus compressor from the centre section of Solid State Logic's (SSL) SL 4000 G Series mixing console. It uses fixed-step attack times (0.1, 0.3, 1, 3, 10 and 30 ms), release times (0.1, 0.3, 0.6, 1.2 s and Auto) and ratios of 2:1, 4:1 and 10:1, with a side-chain high-pass filter. Solid State Logic owns the trademark; the underlying method is generic VCA bus compression.", "plain_english": "This is the stereo bus compressor from SSL's large mixing desks. SSL is short for Solid State Logic. It sits across a whole mix and gently controls its overall level. Engineers use its fixed switches to 'glue' a mix together.", "purpose_function": "It applies gentle, cohesive gain reduction across a stereo mix so separate tracks blend into one solid-sounding whole.", "practical_application": "A technician places it on the mix bus, chooses a low ratio, a moderate attack and Auto release, then sets the threshold for a few decibels of gain reduction.", "category": "Bus Compression", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["SSL Bus Compressor", "VCA Compressor", "SSL Glue", "SiX Bus Compressor", "Side-chain", "Makeup Gain"], "common_mistakes": ["Using a very fast attack that kills transients and dulls the mix", "Applying too much gain reduction so the mix pumps unnaturally", "Leaving the side-chain high-pass filter off so bass triggers the whole compressor"], "scenario_contexts": ["Glueing a stereo mix on the master bus", "Compressing a drum bus for punch and cohesion", "Adding energy to a rock mix with a 4:1 ratio and a fast release"], "formula_symbolic": "", "formula_words": ""}, {"id": "b0128db8-9ab5-46de-8163-3efa5b7ce90a", "term": "G3 MultiBusComp", "definition": "The SSL G3 MultiBusComp is a software plug-in from Solid State Logic (SSL), the trademark owner, that extends the G-Series bus compressor into a three-band multiband compressor. It splits the signal into low, mid and high bands at adjustable crossover points (roughly 20 Hz to 20 kHz) and applies independent G-Series-style bus compression to each band. The underlying method is generic multiband compression built on VCA bus compression.", "plain_english": "This is a plug-in from Solid State Logic, or SSL. It takes SSL's classic mix compressor and splits it into three. One part works on low sounds, one on middle sounds, one on high sounds. Engineers can control each frequency range on its own.", "purpose_function": "It lets an engineer compress low, mid and high frequencies separately, so loud events in one band do not force gain changes on the others.", "practical_application": "A technician sets the crossover points, then compresses a boomy low band harder than the mids and highs to control bass without dulling vocals or cymbals.", "category": "Multiband Compression", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["G-Series Bus Compressor", "Multiband Compression", "Crossover", "SSL Glue", "VCA Compressor", "Side-chain"], "common_mistakes": ["Setting crossover points that split an instrument awkwardly and cause phasey artefacts", "Over-compressing one band so the overall tonal balance shifts", "Treating it like a single-band bus compressor and ignoring the per-band controls"], "scenario_contexts": ["Controlling a heavy low end on a mix bus while leaving vocals open", "Mastering a mix that needs different compression per frequency range", "Adding punch to the mids without squashing the cymbals"], "formula_symbolic": "", "formula_words": ""}, {"id": "43f88107-80ae-4282-84b8-62b72db1b2d3", "term": "LMC", "definition": "LMC stands for Listen Mic Compressor, an aggressive fixed compressor that originated in the listen/talkback microphone circuit of Solid State Logic (SSL) 4000-series consoles. Its heavy, fast compression famously shaped the big, ambient gated drum sound on Phil Collins' 'In the Air Tonight'. Solid State Logic owns the trademark for its plug-in versions; the underlying method is a fixed-parameter, high-ratio compressor.", "plain_english": "LMC means Listen Mic Compressor. It came from the talkback mic on SSL mixing desks. SSL is short for Solid State Logic. This mic used very heavy, fast compression. Engineers later used that sound as an effect, most famously on Phil Collins' drums.", "purpose_function": "It was built to make quiet talkback speech clearly audible, but its extreme compression became a creative effect for big, aggressive drum and room sounds.", "practical_application": "A technician sends drums or room mics through an LMC plug-in to get an exaggerated, punchy, 'exploding' ambient sound.", "category": "Effect Compressor", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["LMC+", "SSL Bus Compressor", "Parallel Compression", "Noise Gate", "Room Microphone", "Ratio"], "common_mistakes": ["Expecting gentle, transparent compression from an effect designed to be aggressive", "Using it for subtle control on a lead vocal instead of as an effect", "Forgetting to gate the heavily compressed room mic, leaving noise up between hits"], "scenario_contexts": ["Recreating the Phil Collins gated drum ambience", "Smashing a drum room mic for a parallel blend", "Adding aggressive character to a drum loop or break"], "formula_symbolic": "", "formula_words": ""}, {"id": "f0c1918a-289e-4e97-8f7b-ab53f23afa7d", "term": "LMC+", "definition": "LMC+ is a software plug-in from Solid State Logic (SSL), the trademark owner, that is an enhanced version of the classic Listen Mic Compressor from the centre section of the SL 4000E console. It keeps the original aggressive fixed compression and adds creative tools such as a wet/dry Mix, high- and low-pass filters, an external side-chain, and Scoop and Split modes. The underlying method is a fixed-parameter, high-ratio compressor.", "plain_english": "LMC+ is a plug-in from Solid State Logic, or SSL. It is a bigger version of SSL's old Listen Mic Compressor. That compressor made a heavy, aggressive sound. LMC+ keeps that sound and adds blending, filters and other controls.", "purpose_function": "It gives engineers the classic aggressive Listen Mic Compressor effect plus modern controls for blending, filtering and side-chaining.", "practical_application": "A technician uses LMC+ on drums or room mics for big ambience, then dials the Mix control for parallel compression and uses the filters to shape the effect.", "category": "Effect Compressor", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["LMC", "Parallel Compression", "Side-chain", "SSL Bus Compressor", "High-pass Filter", "Noise Gate"], "common_mistakes": ["Running Mix at 100% and losing the dry signal when parallel blend was intended", "Expecting transparent control from an effect-style compressor", "Ignoring the side-chain filters and letting low end over-trigger the compression"], "scenario_contexts": ["Parallel-crushing a drum bus for punch", "Creating big, gated room ambience", "Adding aggressive movement to synths or loops"], "formula_symbolic": "", "formula_words": ""}, {"id": "8c1b5cf7-0504-4c16-9a68-787aab375f94", "term": "SSL Bus Compressor", "definition": "SSL Bus Compressor is the general name for Solid State Logic's (SSL) VCA-based stereo bus compressor, first built into the centre section of the SSL 4000-series consoles and later sold as outboard units, 500-series modules and plug-ins. It uses stepped attack and release times, ratios of 2:1, 4:1 and 10:1, and a side-chain high-pass filter. Solid State Logic owns the trademark; the underlying method is generic VCA bus compression.", "plain_english": "This is Solid State Logic's stereo mix compressor. Solid State Logic is usually shortened to SSL. It started inside SSL's big mixing desks. Now it also comes as hardware boxes and plug-ins. Engineers put it across a whole mix to control and blend it.", "purpose_function": "It provides gentle, musical compression across a stereo mix or sub-group so many separate tracks sound like one cohesive whole.", "practical_application": "A technician patches it across the mix or drum bus, sets a low ratio and Auto release, then adjusts the threshold for a few decibels of gain reduction.", "category": "Bus Compression", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["G-Series Bus Compressor", "SSL Glue", "VCA Compressor", "SiX Bus Compressor", "Makeup Gain", "Side-chain"], "common_mistakes": ["Over-compressing so the mix pumps and loses punch", "Using too fast an attack and dulling transients", "Leaving the side-chain high-pass off so bass triggers excess gain reduction"], "scenario_contexts": ["Master-bus glue during mixing", "Tightening a drum bus", "Sub-group compression on backing vocals"], "formula_symbolic": "", "formula_words": ""}, {"id": "f7d2b17c-0869-429e-a130-e128b4d2743e", "term": "SSL Glue", "definition": "'SSL Glue' is an informal industry term for the cohesive, blending effect produced by Solid State Logic's (SSL) VCA-based stereo bus compressor, in which gentle bus compression makes separate tracks sound like one unified whole. 'Glue' is a generic descriptor for this effect rather than a distinct SSL product name, and third-party 'glue' compressors not made by SSL also exist. Solid State Logic owns the bus-compressor trademark; the underlying method is generic VCA bus compression.", "plain_english": "'Glue' describes how a mix compressor makes separate tracks sound joined together. Engineers link this effect to Solid State Logic, or SSL, bus compressors. But 'glue' is a nickname, not one single SSL product. Other companies also sell 'glue' compressors.", "purpose_function": "The term explains why engineers use gentle bus compression: to bind many separate tracks into one cohesive, solid-sounding mix.", "practical_application": "A technician chasing 'glue' puts an SSL-style bus compressor on the mix bus and applies a few decibels of gentle gain reduction.", "category": "Bus Compression", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["SSL Bus Compressor", "G-Series Bus Compressor", "VCA Compressor", "SiX Bus Compressor", "Parallel Compression", "Makeup Gain"], "common_mistakes": ["Thinking 'glue' is a specific SSL product rather than a described effect", "Adding heavy compression to force glue and instead making the mix pump", "Assuming only SSL gear can create the effect when any gentle bus compression can"], "scenario_contexts": ["Applying subtle bus compression for mix cohesion", "Explaining why a mix sounds disjointed without bus compression", "Choosing a bus compressor to 'glue' a drum group"], "formula_symbolic": "", "formula_words": ""}, {"id": "4967befd-905e-4665-81c6-bfc3013065bd", "term": "SiX Bus Compressor", "definition": "The SiX Bus Compressor is the master-bus compressor built into Solid State Logic's (SSL) SiX desktop mixer. It uses the same circuit topology as the SL 4000 G Series console bus compressor, with a fixed 4:1 ratio, carefully selected (program-dependent) attack and release times, a first-order side-chain high-pass filter at approximately 50 Hz, a threshold (T/HOLD) control and make-up gain. Solid State Logic owns the trademark; the underlying method is generic VCA bus compression.", "plain_english": "This is the mix compressor built into SSL's small SiX mixer. SSL is short for Solid State Logic. It copies the compressor from SSL's big consoles. It is simplified, with one main threshold knob. Engineers use it to glue their final stereo mix.", "purpose_function": "It gives the compact SiX mixer the classic G-Series bus-compression 'glue' with a simplified, easy-to-use control set.", "practical_application": "A technician turns the threshold (T/HOLD) control until the meter shows a few decibels of gain reduction, then sets make-up gain to match levels on the SiX master bus.", "category": "Bus Compression", "difficulty": "intermediate", "achievement_id": "d42dcf1d-a730-488c-9633-28e1218563a4", "cross": [], "related_terms": ["G-Series Bus Compressor", "SSL Bus Compressor", "SSL Glue", "VCA Compressor", "Makeup Gain", "Side-chain"], "common_mistakes": ["Pushing the threshold too far so the mix pumps", "Not level-matching with make-up gain when comparing bypassed and active", "Assuming the ratio is adjustable when SiX uses a fixed 4:1"], "scenario_contexts": ["Glueing a stereo mix on the SiX master bus", "Adding cohesion during a live tracking session on SiX", "Bus-compressing a submix routed through SiX"], "formula_symbolic": "", "formula_words": ""}, {"id": "86be573e-ec25-4292-9c0e-06fefa413302", "term": "Black Knob EQ", "definition": "The Black Knob EQ (Solid State Logic's 242 equaliser) is one of two four-band channel equaliser circuits fitted to the SSL SL 4000 E console. Compared with the earlier Brown Knob (02) circuit it uses a steeper 18 dB/octave high-pass filter, a wider boost/cut range (about plus or minus 18 dB), and a narrower, more surgical mid-band response. Its shelving and parametric behaviours are generic EQ methods, but the specific circuit and the name are proprietary to Solid State Logic.", "plain_english": "The Black Knob EQ is a tone control built into a famous Solid State Logic mixing desk. Solid State Logic owns this design. It has four bands you can boost or cut. Its knobs are black, and it works in a tight, precise way. Engineers often pick it for vocals and clean shaping.", "purpose_function": "It shapes a signal's tone by boosting or cutting chosen frequency ranges on an SSL console channel. Solid State Logic offered it as a sharper, wider-range alternative to the original Brown Knob circuit.", "practical_application": "A technician selects the black-knob 242 EQ on an SSL E-series channel, or its plug-in emulation, for precise, narrow boosts and cuts on vocals and acoustic instruments.", "category": "SSL EQ", "difficulty": "intermediate", "achievement_id": "07df90cd-38fa-4737-8b35-b63864c78de1", "cross": [], "related_terms": ["Brown Knob EQ", "E Series EQ", "G Series EQ", "Parametric EQ", "Shelving EQ", "High-Pass Filter"], "common_mistakes": ["Assuming the black-knob and brown-knob EQs are identical; they use different filter slopes, ranges and Q.", "Thinking 'Black Knob' is a separate product rather than one EQ circuit option in the SSL E-series channel strip.", "Confusing the SSL E-series black-knob (242) EQ with the later G-series (384) EQ."], "scenario_contexts": ["Choosing the black-knob 242 EQ on an SSL 4000 E channel to make a surgical presence boost on a lead vocal.", "Switching a plug-in emulation of the SSL E-series channel from brown-knob to black-knob mode.", "Explaining to a trainee why the black-knob 18 dB/octave high-pass filter removes low rumble more steeply than the brown-knob filter."], "formula_symbolic": "", "formula_words": ""}, {"id": "fc70293e-a00b-4532-9acf-d40d12c20352", "term": "Brown Knob EQ", "definition": "The Brown Knob EQ (Solid State Logic's 02 equaliser) is the original four-band channel equaliser circuit fitted to the SSL SL 4000 E console. It uses a 12 dB/octave high-pass filter and roughly plus or minus 15 dB of boost/cut, giving a broader, more musical response often favoured on drums and bass. Its shelving and parametric behaviours are generic EQ methods, but the circuit and the name are proprietary to Solid State Logic.", "plain_english": "The Brown Knob EQ is a tone control on an early Solid State Logic mixing desk. Solid State Logic owns this design. It was the first version, and its knobs are brown. It boosts and cuts over wide frequency areas. Engineers often use it on drums and bass for a full, gritty sound.", "purpose_function": "It boosts or cuts selected frequency ranges to shape tone, using a broad, musical curve. It was SSL's original E-series channel EQ, later joined by the black-knob 242 version.", "practical_application": "A technician picks the brown-knob 02 EQ on an SSL E-series channel, or its plug-in emulation, when reshaping drums or bass with broad, characterful boosts and cuts.", "category": "SSL EQ", "difficulty": "intermediate", "achievement_id": "07df90cd-38fa-4737-8b35-b63864c78de1", "cross": [], "related_terms": ["Black Knob EQ", "E Series EQ", "G Series EQ", "Parametric EQ", "Shelving EQ", "High-Pass Filter"], "common_mistakes": ["Believing the brown-knob EQ is lower quality than the black-knob; they are simply different voicings.", "Forgetting the brown-knob high-pass filter is 12 dB/octave, gentler than the black-knob's 18 dB/octave.", "Confusing the brown-knob (02) E-series EQ with the G-series (384) EQ."], "scenario_contexts": ["Selecting the brown-knob 02 EQ to add broad weight and grit to a drum bus.", "Switching a plug-in SSL channel to brown-knob mode for a more vintage, musical bass tone.", "Comparing brown-knob and black-knob modes to hear the difference in Q and boost range."], "formula_symbolic": "", "formula_words": ""}, {"id": "5df9eaaf-9716-4f47-bcb5-ff9d0e05bdda", "term": "E Series EQ", "definition": "The E Series EQ is the four-band channel equaliser of the Solid State Logic SL 4000 E console, introduced in the early 1980s. It provides high and low bands switchable between shelving and bell shapes, two fully parametric mid bands, and a high-pass filter. It shipped in two circuit versions, the original Brown Knob (02) and the later Black Knob (242); both build on generic shelving and parametric EQ methods and are proprietary to Solid State Logic.", "plain_english": "The E Series EQ is the tone-shaping section on a classic Solid State Logic mixing desk. Solid State Logic owns this design. It has four bands, covering low, low-mid, high-mid and high sounds. Two of the bands are very flexible. It came in two versions, called the brown knob and the black knob.", "purpose_function": "It lets an engineer boost or cut chosen frequency bands to balance and shape each channel's tone. It helped define the sound of the SSL 4000 E, a widely used 1980s recording console.", "practical_application": "A technician uses the E-series EQ on an SSL console channel, or its plug-in copies, to carve tone on individual tracks during recording and mixing.", "category": "SSL EQ", "difficulty": "intermediate", "achievement_id": "07df90cd-38fa-4737-8b35-b63864c78de1", "cross": [], "related_terms": ["Black Knob EQ", "Brown Knob EQ", "G Series EQ", "Channel Strip", "Parametric EQ", "Shelving EQ"], "common_mistakes": ["Thinking the E-series EQ has only one voicing; it shipped in brown-knob and black-knob versions.", "Assuming the two mid bands are shelving; they are fully parametric with variable Q.", "Confusing the E-series EQ with the later G-series (384) EQ."], "scenario_contexts": ["Setting up an SSL 4000 E channel strip to EQ a snare during tracking.", "Loading an SSL E-series channel plug-in to add the classic 1980s console tone.", "Teaching students the four bands and shelf/bell switching of the E-series EQ."], "formula_symbolic": "", "formula_words": ""}, {"id": "85b5e962-2ecd-42bf-8ecb-ff938d158b28", "term": "G Series EQ", "definition": "The G Series EQ (Solid State Logic's 384 equaliser) is the four-band channel equaliser of the SSL SL 4000 G console, introduced in the late 1980s. It has high and low shelving bands and two fully parametric mid bands whose boost/cut amount interacts with the selected Q, giving a generally smooth, broad, musical response. It relies on generic shelving and parametric EQ methods and is proprietary to Solid State Logic.", "plain_english": "The G Series EQ is the tone control on a later Solid State Logic mixing desk. Solid State Logic owns this design. It has four bands, with two flexible middle bands. Its sound is often smooth and broad. Many engineers use it to gently shape a group or a whole mix.", "purpose_function": "It boosts or cuts selected frequencies to shape tone, favouring smooth, broad curves. It followed the E-series EQ as SSL's channel equaliser on the 4000 G console.", "practical_application": "A technician reaches for the G-series EQ, in hardware or plug-in form, for musical, broad tone shaping on buses, groups, and mixes.", "category": "SSL EQ", "difficulty": "intermediate", "achievement_id": "07df90cd-38fa-4737-8b35-b63864c78de1", "cross": [], "related_terms": ["E Series EQ", "Black Knob EQ", "Brown Knob EQ", "Parametric EQ", "Shelving EQ", "Q (Bandwidth)"], "common_mistakes": ["Assuming the G-series EQ is just a renamed E-series; its curves and Q behaviour differ.", "Expecting narrow, surgical cuts by default; the G-series leans toward broader, smoother shaping.", "Forgetting that on the G-series EQ the boost/cut amount and the Q interact."], "scenario_contexts": ["Using an SSL 4000 G channel EQ to add gentle air and weight to a mix bus.", "Loading an SSL G-EQ plug-in for broad, musical tone shaping on a group.", "Comparing E-series and G-series EQ curves to choose the right tool for a source."], "formula_symbolic": "", "formula_words": ""}, {"id": "91dc0261-74b1-4b69-8335-75f2207382d9", "term": "UltraViolet EQ", "definition": "The UltraViolet EQ (SSL UV EQ) is a stereo, four-section 500-series equaliser from Solid State Logic with a minimum-phase design. Its low and high shelving section is taken from the Fusion Violet EQ, and it adds two fully parametric mid bands with a 'Focus' mode that narrows Q and extends boost/cut to about plus or minus 18 dB, plus an 18 dB/octave high-pass filter. It uses generic shelving and parametric EQ methods; the circuit and the name are proprietary to Solid State Logic.", "plain_english": "The UltraViolet EQ is a tone-shaping unit made by Solid State Logic, who own the design. It works in stereo and fits a 500-series rack. It has smooth low and high controls taken from SSL's Fusion unit. It also has two flexible middle bands. A 'Focus' button makes those bands sharper for precise work.", "purpose_function": "It shapes stereo tone with broad shelving bands plus two precise parametric mid bands. Solid State Logic built it to extend the Fusion's Violet shelving EQ with added mid-band control for mixing and mastering.", "practical_application": "A mix or mastering engineer patches the UltraViolet EQ across a stereo bus to add broad tone with the shelves and make focused mid-band corrections.", "category": "SSL EQ", "difficulty": "intermediate", "achievement_id": "07df90cd-38fa-4737-8b35-b63864c78de1", "cross": [], "related_terms": ["Violet EQ", "Shelving EQ", "Parametric EQ", "High-Pass Filter", "Minimum-Phase EQ", "Q (Bandwidth)"], "common_mistakes": ["Confusing the UltraViolet EQ with the two-band Violet EQ; UltraViolet adds two parametric mid bands.", "Assuming it is mono; the UltraViolet is a stereo 500-series module.", "Forgetting that the 'Focus' mode changes both the Q and the available boost/cut range."], "scenario_contexts": ["Using the UltraViolet EQ across a stereo mix bus for gentle shelf boosts and a focused mid cut.", "Adding air with the high shelf inherited from the Fusion Violet section during mastering.", "Engaging Focus mode to make a narrow, surgical correction on a stereo programme."], "formula_symbolic": "", "formula_words": ""}, {"id": "7df27886-afd3-4c09-b354-206c46ce9195", "term": "Violet EQ", "definition": "The Violet EQ is a two-band, minimum phase-shift shelving equaliser designed by Solid State Logic for its Fusion analogue stereo processor, and later offered as a plug-in. It provides a switchable low shelf (30/50/70/90 Hz) and high shelf (8/12/16/20 kHz) of up to plus or minus 9 dB, plus an 18 dB/octave high-pass filter with a resonance-adding 'Fat' option. Shelving EQ itself is a generic method, but this circuit and the name are proprietary to Solid State Logic, which describes it as its first new analogue EQ design in more than 25 years.", "plain_english": "The Violet EQ is a simple tone control from Solid State Logic, who own the design. It is part of their Fusion stereo processor. It has two controls, one for low sounds and one for high sounds. Each one boosts or cuts gently. It is meant for smooth, musical changes across a whole stereo mix.", "purpose_function": "It adds broad, musical low and high shelf adjustments to a stereo signal. SSL created it to give the Fusion processor a gentle, mix-wide tone-shaping stage.", "practical_application": "A mix or mastering engineer uses the Violet EQ, in hardware or plug-in form, across the stereo bus to add subtle weight and air without surgical control.", "category": "SSL EQ", "difficulty": "intermediate", "achievement_id": "07df90cd-38fa-4737-8b35-b63864c78de1", "cross": [], "related_terms": ["UltraViolet EQ", "Shelving EQ", "High-Pass Filter", "Minimum-Phase EQ", "Parametric EQ", "E Series EQ"], "common_mistakes": ["Expecting parametric mid-band control; the Violet EQ is only two shelving bands.", "Confusing the Violet EQ with the mid-band-equipped UltraViolet EQ.", "Overlooking the 'Fat' option, which adds low-end resonance when the high-pass filter is engaged."], "scenario_contexts": ["Adding gentle low-end weight and high-end air to a stereo mix with the Fusion Violet EQ.", "Using the Violet EQ plug-in on a mix bus for broad tonal balance.", "Engaging the 'Fat' option with the high-pass filter to keep low-end punch while removing rumble."], "formula_symbolic": "", "formula_words": ""}, {"id": "4e017903-ef30-4a22-bff1-0da3684183ad", "term": "Blacklight", "definition": "Blacklight is Solid State Logic's proprietary high-bandwidth digital audio link that multiplexes several MADI streams onto a single optical fibre. Blacklight II carries 256 bidirectional audio channels at 96 kHz - equivalent to eight MADI connections - down one multimode fibre between an SSL Live console and its MADI concentrator or stageboxes. The name is an SSL trademark; the underlying method is optical multiplexing of the AES10 (MADI) digital audio interface.", "plain_english": "Blacklight is an SSL system for sending lots of audio down one fibre-optic cable. One Blacklight II link carries 256 audio channels at once. That equals eight normal MADI cables in a single fibre. It connects an SSL Live mixing desk to the gear on stage.", "purpose_function": "It exists to move very large channel counts between console and stage over one lightweight fibre, cutting the cabling needed compared with running many separate MADI coax lines.", "practical_application": "A technician runs a single Blacklight fibre from the SSL Live console to a MADI concentrator or stagebox rack, gaining hundreds of I/O channels without pulling multiple copper MADI cables.", "category": "Digital Audio Transport", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["MADI", "SSL Live", "Stagebox", "Optical fibre", "AES10", "MADI Concentrator"], "common_mistakes": ["Thinking Blacklight is an open standard - it is SSL proprietary and not interoperable with other brands", "Confusing Blacklight fibre with generic MADI over coax; Blacklight multiplexes several MADI streams onto one fibre", "Assuming any fibre lead works - Blacklight II uses multimode fibre with specific connectors"], "scenario_contexts": ["Linking an SSL Live console to a stage MADI concentrator over one fibre run", "Building a large festival I/O system needing 256 channels between FOH and stage", "Reducing snake weight by replacing multiple MADI coax runs with a single optical link"], "formula_symbolic": "", "formula_words": ""}, {"id": "0643e5e1-86c2-40a4-925a-7d1499b06eb1", "term": "Eyeconix", "definition": "Eyeconix is Solid State Logic's on-screen channel identification feature on SSL Live consoles that shows a graphic icon or bitmap image (for example a drum kit, guitar or vocal mic) beside each channel. The images help operators recognise sources at a glance and are stored within automation scenes. Eyeconix is an SSL trademark for what is generically a graphical channel-labelling system.", "plain_english": "Eyeconix puts a small picture next to each channel on an SSL Live desk. A drum channel can show a drum icon, for example. This helps the engineer spot the right channel fast. The pictures are saved with the show's scenes.", "purpose_function": "It exists to speed up visual channel identification during a busy live mix, so an operator finds a source by picture instead of reading a text label.", "practical_application": "An engineer assigns an image to each input while patching a show, then uses the icons to grab the correct channel quickly during the performance.", "category": "Console Interface", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SSL Live", "Channel strip", "Scene (automation)", "Channel naming", "Fader tile"], "common_mistakes": ["Treating Eyeconix as decoration - it is a working identification aid tied to scenes", "Forgetting that icon assignments are stored per scene and can change with automation", "Assuming it replaces proper channel naming rather than complementing it"], "scenario_contexts": ["Labelling a large input list with instrument icons before a festival set", "Quickly locating a specific channel during a fast-changing live mix", "Recalling a scene where channel icons update along with the show"], "formula_symbolic": "", "formula_words": ""}, {"id": "245ec19b-da3f-4704-85b3-a060f0e3bbb4", "term": "Live Query", "definition": "Query, accessed by the 'Q' button on each SSL Live path, is a console function that instantly shows every signal routed to and from a selected channel or bus in one view. For an input channel it gathers the auxes, stems and masters it feeds plus any controlling VCAs; for a mix bus it gathers all contributing channels and any buses it feeds. Send levels can be adjusted while in Query, so it doubles as a fast way to check routing or build a monitor mix.", "plain_english": "Query is a button marked 'Q' on each SSL Live channel. Press it and the desk shows everything routed to and from that channel. You see all its sends and sources in one place. You can even adjust send levels there, which is handy for monitor mixes.", "purpose_function": "It exists to make complex routing visible and editable from one path, so an engineer can trace or change signal flow without hunting through menus.", "practical_application": "A monitor engineer presses Q on a vocal channel to see and tweak every aux send it feeds, quickly shaping a performer's monitor mix.", "category": "Console Workflow", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SSL Live", "Aux send", "VCA", "Bus routing", "Stem", "Query Assign"], "common_mistakes": ["Thinking Query searches for channels by name - it shows routing for a selected path, not a text search", "Overlooking that send levels can be edited directly in Query mode", "Confusing the 'fed from' and 'feeding' relationships shown by the colour-coded Q buttons"], "scenario_contexts": ["Checking which buses a vocal is feeding before a scene change", "Building a monitor mix by adjusting aux sends inside Query", "Troubleshooting why a channel is not reaching a master or matrix output"], "formula_symbolic": "", "formula_words": ""}, {"id": "133261a2-d343-4c6f-afc9-910cbe486ec1", "term": "SOLSA", "definition": "SOLSA (SSL On/Off Line Setup Application) is Solid State Logic's free companion software for the SSL Live console range. Offline it lets an engineer build and edit a complete show file - console architecture, fader layers, I/O and stagebox routing, scenes, effects and channel processing - on a PC with no hardware present. Online, over a wired or wireless network, it gives real-time remote control of the console. SSL states it 'is not a software console': it has no audio processing and passes no audio.", "plain_english": "SOLSA is free SSL software for SSL Live desks. Offline, it lets you build a whole show on a laptop before you reach the venue. Online, it remote-controls the real console over a network. It does not process or play audio itself. The name stands for SSL On/Off Line Setup Application.", "purpose_function": "It exists so engineers can prepare shows in advance and control the console remotely, saving setup time and adding a second control position.", "practical_application": "An engineer builds the full show file at home in SOLSA, loads it onto the console at the venue, then uses SOLSA on a laptop to tweak monitors from the stage.", "category": "Console Software", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SSL Live", "Show file", "Scene (automation)", "Remote Tile", "T-SOLSA", "Tempest"], "common_mistakes": ["Believing SOLSA mixes audio - it has no processing and passes no audio", "Assuming offline files will not transfer - SOLSA show files load onto the physical console", "Confusing SOLSA (SSL Live) with T-SOLSA (System T)"], "scenario_contexts": ["Programming a festival show file offline the week before the gig", "Remote-controlling the console from a laptop at the mix position", "Handing a prepared show file to a house engineer to load on an SSL Live desk"], "formula_symbolic": "", "formula_words": ""}, {"id": "3096d08a-ef94-46cc-b7a3-34cba452920e", "term": "SSL Live", "definition": "SSL Live is Solid State Logic's range of large-format digital live-sound mixing consoles, first introduced in 2013 (models include the L100 through L650). The consoles run on SSL's Tempest processing engine at 96 kHz, providing flexible audio 'paths', touchscreen control, motorised faders and extensive I/O over MADI, Dante and Blacklight. 'SSL Live' is a Solid State Logic product name.", "plain_english": "SSL Live is Solid State Logic's family of digital mixing desks for live shows. They first came out in 2013. They run on SSL's Tempest engine at 96 kHz. They use touchscreens, moving faders, and connect to many inputs and outputs.", "purpose_function": "It exists to mix live concerts, theatre and events, giving engineers flexible routing, processing and scene recall for front-of-house or monitors.", "practical_application": "A front-of-house engineer mixes a touring band on an SSL Live L550, recalling scenes and using its onboard processing and effects.", "category": "Live Console", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Tempest", "SOLSA", "Blacklight", "TaCo", "MADI", "Dante"], "common_mistakes": ["Confusing SSL Live consoles with SSL's studio consoles such as Duality or Origin", "Assuming all models share identical path counts - capacity varies by model", "Thinking SSL Live is only for front-of-house; it is used for monitors too"], "scenario_contexts": ["Mixing front-of-house for a touring concert", "Running monitors for a festival stage", "Mixing a musical or theatre production with scene recall"], "formula_symbolic": "", "formula_words": ""}, {"id": "9315472d-9802-4f3f-b5c5-0eabce245915", "term": "SSL On/Off Line Setup Application", "definition": "SSL On/Off Line Setup Application is the full name of SOLSA, Solid State Logic's free companion software for the SSL Live console range. Offline it builds and edits a complete show file - console architecture, layers, I/O and stagebox routing, scenes, effects and processing - on a PC; online it gives real-time remote control of the console over a wired or wireless network. It contains no audio processing and passes no audio.", "plain_english": "This is the full name of SOLSA, SSL's free setup software. Offline, it lets you build a show on a computer before the gig. Online, it remote-controls the SSL Live console over a network. It does not process or pass any audio itself.", "purpose_function": "It exists so engineers can prepare shows in advance and control the SSL Live console remotely, without needing the surface present to do the setup.", "practical_application": "An engineer preps routing and scenes in the application offline, then connects over the venue network to control the console from a laptop.", "category": "Console Software", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SOLSA", "SSL Live", "Show file", "Scene (automation)", "T-SOLSA"], "common_mistakes": ["Not realising this is simply the full name of SOLSA", "Believing it processes audio - it does not", "Confusing it with System T's T-SOLSA"], "scenario_contexts": ["Preparing a show file offline before load-in", "Remote-controlling the console over Wi-Fi at the mix position", "Editing routing and scenes away from the console surface"], "formula_symbolic": "", "formula_words": ""}, {"id": "fa46f0b1-af81-434d-b795-9a2156529508", "term": "System T", "definition": "System T is Solid State Logic's IP-networked broadcast audio production platform. It replaces traditional fixed routing with a Dante Audio-over-IP network (with AES67 support) and processes audio on Tempest Engines built on SSL's Optimal Core Processing. Control is via modular or fixed surfaces (S300 to S500M), desktop controllers and the software Tempest Control App. 'System T' is a Solid State Logic product name; the networking is standards-based Dante/AES67.", "plain_english": "System T is SSL's audio system for broadcast, such as TV and radio. It sends audio over a computer network using Dante instead of old fixed wiring. Its Tempest engines do the processing. Engineers control it with mixing surfaces or software.", "purpose_function": "It exists to give broadcasters a scalable, networked mixing and routing system that can run across a whole facility, remotely, or in the cloud.", "practical_application": "A broadcast engineer mixes a live sports programme on a System T S500 surface, with audio routed over Dante and processed on a Tempest Engine.", "category": "Broadcast System", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["Tempest", "Dante", "AES67", "T-SOLSA", "Tempest Control App", "Audio-over-IP"], "common_mistakes": ["Thinking System T uses proprietary networking - it runs on standard Dante/AES67 IP audio", "Confusing System T (broadcast) with SSL Live (touring/live consoles)", "Assuming the surface does the processing - the Tempest Engine does"], "scenario_contexts": ["Mixing a live television sports broadcast", "Networked audio routing across a broadcast facility", "Remote or cloud production using a Virtual Tempest Engine"], "formula_symbolic": "", "formula_words": ""}, {"id": "de629789-3626-49b4-927f-fbaa0b306e31", "term": "T-SOLSA", "definition": "T-SOLSA is the System T version of SSL's On/Off Line Setup Application - free software that mirrors the System T console's functionality without audio processing, used to prepare productions offline and to remote-control the system. Solid State Logic's newer Tempest Control App has since replaced the T-SOLSA package. 'T-SOLSA' is a Solid State Logic product name.", "plain_english": "T-SOLSA is SSL's setup software for System T. It copies the console's features on a computer but does not process audio. Engineers use it to plan shows offline and to control the system remotely. SSL's newer Tempest Control App has replaced it.", "purpose_function": "It exists to let broadcast engineers build and remote-control System T productions without needing the hardware surface present.", "practical_application": "A broadcast engineer preps a show's routing and layout in T-SOLSA offline, then uses it to remote-control the System T during the production.", "category": "Console Software", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["System T", "SOLSA", "Tempest Control App", "Tempest", "Dante"], "common_mistakes": ["Confusing T-SOLSA (System T) with SOLSA (SSL Live)", "Believing T-SOLSA processes audio - it mirrors control only", "Not knowing the Tempest Control App now replaces T-SOLSA"], "scenario_contexts": ["Preparing a broadcast show file offline", "Remote-controlling a System T from a laptop", "Migrating older T-SOLSA workflows to the Tempest Control App"], "formula_symbolic": "", "formula_words": ""}, {"id": "1a00d4bd-421e-4c18-9587-83554110c434", "term": "TaCo", "definition": "TaCo (Tablet Control) is Solid State Logic's wireless tablet app for the SSL Live console range, introduced in 2016. Running on iPad or Android, it lets performers or a monitor engineer control individual aux/monitor mixes or view all mixes on one screen; an Engineer Mode adds remote control of channel processing. 'TaCo' is an SSL product name and is distinct from the System T 'Tempest Control App'.", "plain_english": "TaCo, short for Tablet Control, is an SSL app for iPad or Android. It links wirelessly to an SSL Live desk. Performers or engineers use it to set their own monitor mixes. An Engineer Mode also lets you adjust channel processing from the tablet.", "purpose_function": "It exists to give performers and roaming engineers hands-on wireless control of monitor mixes and channel settings away from the console surface.", "practical_application": "A musician on stage uses TaCo on an iPad to tweak their own in-ear monitor mix while the monitor engineer works elsewhere.", "category": "Remote Control App", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SSL Live", "Aux send", "Monitor mix", "SOLSA", "In-ear monitor"], "common_mistakes": ["Confusing TaCo (Tablet Control, SSL Live) with the Tempest Control App (System T)", "Assuming TaCo replaces the console - it is a remote control aid", "Forgetting Engineer Mode is needed to reach channel processing, not just aux sends"], "scenario_contexts": ["A performer adjusting their own in-ear mix from the stage", "A monitor engineer walking the stage with a tablet", "Giving band members limited control of their aux mixes during soundcheck"], "formula_symbolic": "", "formula_words": ""}, {"id": "ac3d1161-e4c1-4648-a772-47cf1dc33ed3", "term": "Tempest", "definition": "Tempest is Solid State Logic's audio processing engine used in the SSL Live consoles and in System T. It uses SSL's patented Optimal Core Processing (OCP) running on standard/industrial CPU hardware to give 64-bit internal processing at 96 kHz, configured as flexible audio 'paths' rather than fixed channels. 'Tempest' is a Solid State Logic trademark; generically it is a CPU-based DSP mixing engine.", "plain_english": "Tempest is the processing engine inside SSL Live and System T. It runs the mixing on ordinary computer processors instead of the special fixed audio chips (DSP) most digital desks use. It works in 64-bit at 96 kHz. Its power is shared out as flexible 'paths' you assign as needed.", "purpose_function": "It exists to deliver large, flexible channel and bus counts from general-purpose processors, so resources can be assigned as paths instead of fixed channel strips.", "practical_application": "An engineer sets how many input and bus paths a show needs, and the Tempest engine allocates its processing to match.", "category": "Processing Engine", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SSL Live", "System T", "Optimal Core Processing", "Audio path", "Tempest Control App", "Blacklight"], "common_mistakes": ["Calling Tempest a control surface - it is the processing engine behind the surface", "Assuming fixed channel counts - resources are assigned as flexible paths", "Confusing the Tempest engine (hardware/DSP) with the Tempest Control App (software)"], "scenario_contexts": ["Setting path counts for a large festival mix", "Understanding where SSL Live and System T do their DSP processing", "Sizing the engine (for example TE1 vs TE2, or T25 vs T80) for a production"], "formula_symbolic": "", "formula_words": ""}, {"id": "a3844161-bcf0-43ea-988c-e88f8870afdd", "term": "Bus Compressor 2", "definition": "Bus Compressor 2 is a Solid State Logic plug-in that models the stereo VCA (voltage-controlled amplifier) bus compressor from the centre section of the 1980s SSL 4000 G-Series console. It keeps the classic threshold, ratio, attack, release and make-up controls, and adds a sidechain high-pass filter, a wet/dry mix control for parallel compression, external sidechain input, and selectable oversampling. Bus (VCA) compression is a generic method; this circuit model and the name are proprietary to Solid State Logic.", "plain_english": "Bus Compressor 2 is a plug-in copy of a famous Solid State Logic desk compressor. Solid State Logic owns the design. You put it on a whole mix or a group to glue the sounds together. It squeezes the loudest parts so the mix feels tighter. Version 2 adds a filter, a blend knob, and cleaner processing.", "purpose_function": "It controls the level of a stereo mix or group so the parts sound tighter and more cohesive. Solid State Logic offers it to bring the sound of its hardware G-Series bus compressor into a computer session.", "practical_application": "A mix engineer places Bus Compressor 2 on the master or a drum bus, sets a slow attack and auto release, and dials in a few decibels of gain reduction for glue.", "category": "SSL Dynamics", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["The Bus+", "Channel Strip 2", "SSL 360 Plug-In Mixer", "X-Comp", "VCA Compressor", "Sidechain"], "common_mistakes": ["Setting the attack too fast, which flattens transients and kills punch on a drum bus.", "Ignoring the sidechain high-pass filter, so heavy bass triggers unwanted pumping.", "Assuming it is a unique effect rather than a VCA bus compressor model with SSL character."], "scenario_contexts": ["Adding 2 to 3 dB of glue compression across a full mix bus.", "Using the mix control for parallel compression on a drum group.", "Engaging the sidechain high-pass filter to stop a loud kick from pumping the whole mix."], "formula_symbolic": "", "formula_words": ""}, {"id": "e783d005-7b29-4367-929a-9a5ff89c4d0b", "term": "Channel Strip 2", "definition": "Channel Strip 2 is a Solid State Logic plug-in that models the channel processing of the SSL 9000-series (XL 9000 K) recording console, combining a high- and low-pass filter section, a four-band EQ (equaliser) and a dynamics section with compressor and gate/expander in one strip. It integrates with the SSL 360 Plug-in Mixer for console-style control from SSL hardware. Console channel EQ plus dynamics is a generic method; this model and the name are proprietary to Solid State Logic.", "plain_english": "Channel Strip 2 is a plug-in copy of one channel from a Solid State Logic mixing desk. Solid State Logic owns the design. It puts a tone control, a compressor and a gate on a single track. You use it to shape and control one instrument or voice. It works with SSL hardware controllers for hands-on mixing.", "purpose_function": "It gives one track the filtering, EQ and dynamics of a classic SSL console channel in a single plug-in. Solid State Logic offers it so engineers can shape and control individual tracks with a familiar console workflow.", "practical_application": "A technician inserts Channel Strip 2 on a vocal or snare, filters out rumble, shapes tone with the EQ, then tames peaks with the built-in compressor.", "category": "SSL Channel Strip", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Bus Compressor 2", "SSL 360 Plug-In Mixer", "SSL 360 Link", "E Series EQ", "G Series EQ", "Drumstrip"], "common_mistakes": ["Boosting many EQ bands heavily instead of making small, focused moves.", "Forgetting the gate section, then leaving noisy silences on a recorded track.", "Treating it as a generic strip and ignoring the E/G EQ voicings it models."], "scenario_contexts": ["Shaping a lead vocal with the EQ and compressor on one channel.", "Controlling a full mix's individual tracks from an SSL UF8 or UC1 through the Plug-in Mixer.", "Using the high-pass filter to remove low rumble from a guitar track before EQ."], "formula_symbolic": "", "formula_words": ""}, {"id": "aa2eb93e-3025-4d9e-a39e-f8c96f795ab9", "term": "Drumstrip", "definition": "Drumstrip is a Solid State Logic plug-in built for shaping drum and percussion tracks, combining several processors in one strip: a transient shaper, a gate/expander, separate high- and low-frequency enhancers that add harmonics, and a Listen Mic Compressor derived from a classic SSL console circuit. The module order can be rearranged. Transient shaping, gating and harmonic enhancement are generic methods; this combination and the name are proprietary to Solid State Logic.", "plain_english": "Drumstrip is a plug-in made for drums and percussion. Solid State Logic owns the design. It packs several drum tools into one window. You can boost the attack of a hit, cut unwanted noise, and add extra low or high sparkle. It also has a punchy compressor for a big drum sound.", "purpose_function": "It reshapes the attack, decay, tone and level of drums using tools tuned for percussion. Solid State Logic offers it so engineers can add punch, control ring, and add spectral detail without stacking many separate plug-ins.", "practical_application": "A technician uses Drumstrip's transient shaper to add attack to a dull snare, the gate to tighten the tail, and the enhancers to add high-end snap.", "category": "SSL Channel Strip", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Channel Strip 2", "Vocalstrip", "Transient Shaper", "Gate", "Listen Mic Compressor", "X-Comp"], "common_mistakes": ["Overusing the transient shaper, which makes drums sound clicky and unnatural.", "Confusing the harmonic enhancers with ordinary EQ; they add new harmonics, not just level.", "Setting the gate thresholds badly, so soft hits get chopped off."], "scenario_contexts": ["Adding attack and snap to a flat-sounding snare drum.", "Tightening a roomy tom by shortening its decay with the gate.", "Enhancing the high end of a dull overhead mic without a separate EQ."], "formula_symbolic": "", "formula_words": ""}, {"id": "03b27d6d-eea7-4c7c-9c99-a5be95b27eb1", "term": "Duende", "definition": "Duende is a discontinued Solid State Logic hardware DSP (digital signal processing) unit, first released in 2006, that connected to a computer over FireWire (later PCIe) and hosted SSL plug-ins by running their processing on its own SHARC DSP chips instead of the host computer's CPU. It shipped with SSL Duende plug-ins such as the Channel Strip and Bus Compressor. DSP acceleration hardware is a generic concept; the Duende product and name are proprietary to Solid State Logic.", "plain_english": "Duende is an older Solid State Logic hardware box for running plug-ins. Solid State Logic owns the design. It plugged into a computer and did the audio math itself. This took the load off the computer's main processor. It let engineers run many SSL effects at once without slowing the computer.", "purpose_function": "It offloaded plug-in processing onto dedicated chips so a computer could run many SSL effects without overloading its main processor. Solid State Logic built it to bring its console-style processing into the computer studio.", "practical_application": "In the late 2000s an engineer connected a Duende unit over FireWire and ran SSL Channel Strip and Bus Compressor plug-ins on its chips during large mixes.", "category": "SSL Platform", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Duende Native", "SSL Native", "Channel Strip 2", "Bus Compressor 2", "DSP", "Plug-in"], "common_mistakes": ["Thinking Duende is a plug-in; it is a hardware DSP unit that hosts plug-ins.", "Assuming its plug-ins run on any computer without the hardware or a native version.", "Confusing the DSP-based Duende with the later CPU-based SSL Native range."], "scenario_contexts": ["Running SSL plug-ins on a laptop with limited processing power using the Duende hardware.", "Building a mix with many SSL Channel Strip instances hosted on Duende DSP.", "Explaining to students how early DSP accelerators offloaded plug-in processing from the CPU."], "formula_symbolic": "", "formula_words": ""}, {"id": "f7a7e4df-4df8-4938-a700-efe2c5f989fa", "term": "Duende Native", "definition": "Duende Native is Solid State Logic's software version of its Duende plug-ins that runs entirely on the host computer's CPU, in standard VST, AU and AAX formats, with no dedicated DSP hardware required. It was the CPU-hosted counterpart to the DSP-based Duende units and the forerunner of the later SSL Native range. Native (host-processed) plug-ins are a generic concept; these specific plug-ins and the name are proprietary to Solid State Logic.", "plain_english": "Duende Native is the software-only version of Solid State Logic's Duende effects. Solid State Logic owns the design. It runs on the computer itself, so you do not need the extra hardware box. You just install it in your recording software. It later became known as SSL Native.", "purpose_function": "It lets engineers run SSL's Duende plug-ins on an ordinary computer without buying the DSP hardware. Solid State Logic offered it to make its processing available to any host that supports common plug-in formats.", "practical_application": "An engineer installs Duende Native plug-ins in a DAW (digital audio workstation) and runs SSL Channel Strip and Bus Compressor entirely on the computer's processor.", "category": "SSL Platform", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Duende", "SSL Native", "Channel Strip 2", "Bus Compressor 2", "Plug-in", "VST"], "common_mistakes": ["Expecting it to need the Duende hardware; the native version runs on the CPU alone.", "Confusing Duende Native with the DSP-based Duende hardware unit.", "Overloading a weak computer by running too many native instances at once."], "scenario_contexts": ["Running SSL plug-ins on a modern laptop with no DSP hardware attached.", "Migrating a session from DSP-based Duende to the CPU-based native versions.", "Teaching the difference between DSP-hosted and native plug-in processing."], "formula_symbolic": "", "formula_words": ""}, {"id": "9cbaed50-4f0a-496a-953b-3246531b272b", "term": "FlexVerb", "definition": "FlexVerb is a Solid State Logic algorithmic reverb plug-in offering four core reverb algorithms — Room, Hall, Plate and Chamber — each in Small, Medium and Large sizes, with early reflections and reverb tail selectable independently. It adds three-band reverb-time multipliers, a six-band parametric EQ on the reverb signal, and an input sidechain compressor. Algorithmic reverb is a generic method; this design and the name are proprietary to Solid State Logic.", "plain_english": "FlexVerb is a reverb plug-in from Solid State Logic. Solid State Logic owns the design. Reverb adds a sense of space, like a room or a hall. FlexVerb offers several room types in small, medium and large sizes. You can mix an early space with a long tail, and even duck the reverb under the vocal.", "purpose_function": "It adds artificial room, hall, plate or chamber ambience to a signal and shapes that space with EQ and dynamics. Solid State Logic offers it as a flexible, mix-ready reverb for both quick results and detailed sound design.", "practical_application": "A mix engineer adds FlexVerb to a vocal, chooses a large hall tail, then uses its sidechain compressor so the reverb ducks while the vocal is loud.", "category": "SSL Reverb", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["PlateVerb", "Reverb", "Early Reflections", "Sidechain", "Parametric EQ", "SSL Native"], "common_mistakes": ["Adding too much reverb, which pushes a vocal back and muddies the mix.", "Ignoring the reverb EQ, so the tail masks other instruments with unwanted frequencies.", "Assuming early reflections and tail must match; FlexVerb lets you mix different ones."], "scenario_contexts": ["Placing a lead vocal in a large hall while keeping it clear with the sidechain compressor.", "Combining small-room early reflections with a large plate tail for a creative space.", "Using the reverb EQ to darken a bright reverb tail on a snare drum."], "formula_symbolic": "", "formula_words": ""}, {"id": "b3f8066e-a9a0-45a5-b796-4014729209b4", "term": "PlateVerb", "definition": "PlateVerb is a Solid State Logic algorithmic reverb plug-in that emulates a classic studio plate reverb using two bespoke algorithms for early and late reflections that model the sonic, mechanical and damping behaviour of a metal plate. It provides diffusion, decay time (about 100 ms to 3 s), size, low/high damping, a Colour control for different plate characters, and ducking with internal or external sidechain. Plate reverb emulation is a generic method; this design and the name are proprietary to Solid State Logic.", "plain_english": "PlateVerb is a reverb plug-in that copies an old studio plate reverb. Solid State Logic owns the design. Real plate reverbs used a large vibrating metal sheet to create a smooth echo. PlateVerb recreates that lush, warm sound in software. Engineers often use it on vocals and snare drums.", "purpose_function": "It recreates the smooth, dense sound of a mechanical plate reverb and lets the user tune its decay, tone and character. Solid State Logic offers it to add classic plate ambience to vocals, drums and other sources.", "practical_application": "A technician adds PlateVerb to a snare or vocal, sets a medium decay, and uses the Colour control to match the brightness the mix needs.", "category": "SSL Reverb", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["FlexVerb", "Reverb", "Plate Reverb", "Early Reflections", "Sidechain", "SSL Native"], "common_mistakes": ["Confusing a plate reverb with a room reverb; a plate has no true room shape.", "Setting decay too long, which smears fast material like a snare.", "Ignoring the damping controls, leaving a harsh or boomy tail."], "scenario_contexts": ["Adding a bright vintage plate sound to a lead vocal.", "Using a short plate on a snare drum for classic pop and rock ambience.", "Ducking the plate tail under a busy mix with the sidechain control."], "formula_symbolic": "", "formula_words": ""}, {"id": "08e0766b-5fa1-4ed3-a097-58fba56ce0c4", "term": "SSL 360", "definition": "SSL 360 (SSL 360°) is Solid State Logic's free cross-platform companion application for Mac and Windows that acts as the control hub linking SSL hardware controllers (UF8, UF1, UC1), audio interfaces (SSL 12, SSL 18) and SSL 360-enabled plug-ins in one place. It also houses the 360 Plug-in Mixer that manages inserted Channel Strip 2 and Bus Compressor 2 instances. It is a proprietary Solid State Logic software platform.", "plain_english": "SSL 360 is free software from Solid State Logic that ties their gear together. Solid State Logic owns it. It acts like a control centre on your computer. It connects their hardware controllers, interfaces and plug-ins in one app. It also holds the mixer that manages certain SSL plug-ins.", "purpose_function": "It gives one place to set up and control SSL controllers, interfaces and plug-ins so they work together as a system. Solid State Logic provides it as the software brain of its hybrid hardware-and-software workflow.", "practical_application": "A technician opens SSL 360 to configure a UF8 controller, set up an SSL 12 interface, and manage plug-ins in the Plug-in Mixer during a session.", "category": "SSL Platform", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["SSL 360 Link", "SSL 360 Plug-In Mixer", "Channel Strip 2", "Bus Compressor 2", "SSL Native", "Control Surface"], "common_mistakes": ["Thinking SSL 360 is itself an audio effect; it is control and management software.", "Forgetting to keep SSL 360 running, so hardware and plug-ins lose their link.", "Confusing SSL 360 the app with SSL 360 Link, which is a separate control plug-in."], "scenario_contexts": ["Setting up an SSL UF8 or UC1 controller before a mix session.", "Managing all Channel Strip 2 instances through the built-in Plug-in Mixer.", "Configuring an SSL 12 audio interface's routing from one central app."], "formula_symbolic": "", "formula_words": ""}, {"id": "ac638a72-10db-4dd1-be2a-c47f1fc1bd74", "term": "SSL 360 Link", "definition": "SSL 360 Link is a free Solid State Logic plug-in that lets an SSL UC1 hardware controller operate third-party VST3 plug-ins, mapping the controller's physical channel-strip knobs and switches onto the parameters of external plug-ins. The Link plug-in itself is available in AAX, AU, VST and VST3, includes factory control maps, and supports custom mapping. It is a proprietary Solid State Logic control tool.", "plain_english": "SSL 360 Link is a free plug-in that connects an SSL hardware controller to other companies' plug-ins. Solid State Logic owns it. Normally the UC1 controller only drives SSL plug-ins. Link lets it turn the knobs of other plug-ins too. This gives hands-on control instead of using a mouse.", "purpose_function": "It extends SSL hardware control to non-SSL VST3 plug-ins so an engineer can adjust them with physical knobs. Solid State Logic offers it to bring tactile, muscle-memory control to a wider set of plug-ins.", "practical_application": "A technician loads SSL 360 Link on a channel, maps a favourite third-party EQ to the UC1's controls, then tweaks it by hand instead of by mouse.", "category": "SSL Platform", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["SSL 360", "SSL 360 Plug-In Mixer", "Control Surface", "Channel Strip 2", "Bus Compressor 2", "Plug-in"], "common_mistakes": ["Trying to control non-VST3 plug-ins; Link hosts VST3 plug-ins only.", "Confusing SSL 360 Link with the SSL 360 app, which manages SSL's own gear.", "Forgetting to assign a control map, so the hardware knobs do nothing."], "scenario_contexts": ["Controlling a third-party compressor from an SSL UC1's physical knobs.", "Building a custom control map for a favourite non-SSL EQ plug-in.", "Adding hands-on control of external plug-ins to an existing SSL hardware setup."], "formula_symbolic": "", "formula_words": ""}, {"id": "6b85b0b7-92fd-4af1-aac2-3026a2d403d1", "term": "SSL 360 Plug-In Mixer", "definition": "The SSL 360 Plug-In Mixer is a virtual mixing console inside Solid State Logic's SSL 360 software that automatically hosts and displays every Channel Strip 2 and Bus Compressor 2 instance placed in a DAW session, giving console-style overview and control. Instances appear when inserted in the DAW and disappear when removed. It can be operated from SSL UC1, UF8 and UF1 hardware. It is a proprietary Solid State Logic feature.", "plain_english": "The SSL 360 Plug-In Mixer is a virtual mixing desk inside SSL 360 software. Solid State Logic owns it. It gathers all your SSL Channel Strip and Bus Compressor plug-ins in one place. You see and control them like channels on a real desk. You can also drive it from SSL hardware controllers.", "purpose_function": "It collects a session's SSL Channel Strip 2 and Bus Compressor 2 plug-ins into one console-style view for unified control. Solid State Logic provides it so engineers can mix with these plug-ins the way they would on a hardware desk.", "practical_application": "A technician inserts several Channel Strip 2 plug-ins in a DAW, then mixes them all from the 360 Plug-in Mixer using an SSL UF8 controller.", "category": "SSL Platform", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["SSL 360", "SSL 360 Link", "Channel Strip 2", "Bus Compressor 2", "Control Surface", "SSL Native"], "common_mistakes": ["Expecting non-SSL plug-ins to appear; only Channel Strip 2 and Bus Compressor 2 populate it.", "Closing the SSL 360 app, which stops the mixer from tracking the session.", "Confusing the Plug-in Mixer with the DAW's own mixer window."], "scenario_contexts": ["Overviewing every SSL channel plug-in in a large session from one window.", "Controlling grouped Channel Strip 2 instances from an SSL UC1 controller.", "Recalling console-style settings across many tracks during a mix."], "formula_symbolic": "", "formula_words": ""}, {"id": "50cc784e-8bed-43d8-a5a2-b5fd14b4cd4c", "term": "SSL Native", "definition": "SSL Native is Solid State Logic's current range of software plug-ins that run natively on the host computer's CPU, in standard VST, AU and AAX formats, with no dedicated DSP hardware required. The range includes console-derived and creative processors such as Channel Strip 2, Bus Compressor 2, the X-series and reverbs. Native (host-processed) plug-ins are a generic concept; these specific products and the name are proprietary to Solid State Logic.", "plain_english": "SSL Native is Solid State Logic's set of software plug-ins. Solid State Logic owns them. They run on your computer with normal music software. You do not need any extra hardware to use them. The set includes SSL's tone controls, compressors and other effects.", "purpose_function": "It brings SSL's console and studio processing to any computer as standard plug-ins without special hardware. Solid State Logic offers it so engineers can use SSL-style tools in any common DAW.", "practical_application": "An engineer installs SSL Native plug-ins in a DAW and uses Channel Strip 2, Bus Compressor 2 and X-series tools across a mix.", "category": "SSL Platform", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Duende Native", "Channel Strip 2", "Bus Compressor 2", "X-EQ 2", "SSL 360", "Plug-in"], "common_mistakes": ["Thinking SSL Native needs SSL hardware; it runs on the CPU alone.", "Confusing the SSL Native range with the older DSP-based Duende system.", "Assuming it is a single plug-in rather than a whole collection."], "scenario_contexts": ["Building a full mix using only SSL Native plug-ins in a laptop DAW.", "Moving from DSP-based SSL plug-ins to the CPU-based native range.", "Combining SSL Native channel and bus tools for a console-style workflow."], "formula_symbolic": "", "formula_words": ""}, {"id": "e1384fec-e662-4453-a6ef-f646bba8ad6d", "term": "Sourcerer", "definition": "Sourcerer is a Solid State Logic dynamics plug-in that works as a frequency-dependent downward expander with filtering and sidechain controls, reducing unwanted sound such as microphone bleed, stage spill and feedback while preserving the main source. It uses simple Threshold, Time and Depth controls and was first developed for SSL Live consoles before release as a DAW plug-in. Frequency-dependent expansion is a generic method; this design and the name are proprietary to Solid State Logic.", "plain_english": "Sourcerer is a plug-in that removes unwanted background sound. Solid State Logic owns the design. It quiets bleed from other instruments and feedback on a mic. It leaves the main sound you want alone. You set just three simple controls to clean up the track.", "purpose_function": "It cleans up a signal by turning down unwanted spill, noise and feedback without the harsh chopping of a plain gate. Solid State Logic offers it to isolate a source in busy live or multi-mic recordings.", "practical_application": "A live engineer puts Sourcerer on a vocal mic to cut drum bleed and reduce feedback, keeping the voice clear.", "category": "SSL Dynamics", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Drumstrip", "Gate", "Sidechain", "Expander", "Channel Strip 2", "Feedback"], "common_mistakes": ["Setting the depth too deep, which makes the source sound choppy and unnatural.", "Treating it as a noise gate; it is a frequency-dependent expander.", "Expecting it to remove noise mixed into the wanted sound at the same frequency."], "scenario_contexts": ["Reducing drum and stage bleed on a live vocal microphone.", "Cleaning spill between close mics on a multi-mic drum kit.", "Increasing gain before feedback on a stage monitor mix."], "formula_symbolic": "", "formula_words": ""}, {"id": "ce7c51e7-4360-4d2e-a6a8-ae814811498f", "term": "The Bus+", "definition": "The Bus+ is a Solid State Logic hardware stereo bus processor, a 19-inch rack unit released in 2022 that uses a 100% analogue signal path with digital control. It builds on SSL's classic VCA (voltage-controlled amplifier) bus compressor, adding selectable compression modes (Classic, Dual Mono, Mid-Side, sidechain-summed stereo), three tonal 'colour' options, negative ratios, a two-band parallel Dynamic EQ, and a transient expander. Bus compression is a generic method; this unit and the name are proprietary to Solid State Logic.", "plain_english": "The Bus+ is a hardware compressor box from Solid State Logic. Solid State Logic owns the design. It is an analogue unit that sits in a rack. It squeezes a whole mix to glue it together, like SSL's classic desk compressor. It adds new modes, tone colours, and an extra tone-shaping stage.", "purpose_function": "It compresses and shapes a stereo mix with SSL's classic bus compression plus modern modes and extra processing. Solid State Logic built it as a flexible, updated version of its well-known hardware bus compressor.", "practical_application": "A mastering or mix engineer patches The Bus+ across the stereo master, picks a compression colour, and adds glue plus tone with the built-in dynamic EQ.", "category": "SSL Dynamics", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Bus Compressor 2", "VCA Compressor", "Mid-Side", "Dynamic EQ", "Transient Shaper", "Sidechain"], "common_mistakes": ["Assuming The Bus+ is a plug-in; it is an analogue hardware unit with digital control.", "Ignoring the sidechain filter and colour modes, missing much of its flexibility.", "Over-compressing the master and squashing the mix's dynamics."], "scenario_contexts": ["Adding analogue glue compression across a stereo mix bus.", "Using Mid-Side mode to compress the centre and sides of a mix separately.", "Shaping the master tone with the built-in dynamic EQ while compressing."], "formula_symbolic": "", "formula_words": ""}, {"id": "efec6fa3-e729-4c56-aa7c-5f59d5e63d1d", "term": "Vocalstrip", "definition": "Vocalstrip is a Solid State Logic plug-in that combines the main vocal-processing stages in one strip: high- and low-frequency enhancement, a de-esser to tame sibilance, a compressor, and an EQ (equaliser). It is tuned for shaping and controlling vocal recordings and is the vocal counterpart to SSL's Drumstrip. Its underlying de-essing, compression and EQ are generic methods; this combination and the name are proprietary to Solid State Logic.", "plain_english": "Vocalstrip is a plug-in made for voices. Solid State Logic owns the design. It puts several vocal tools in one window. It can add sparkle, soften harsh 's' sounds, even out the level, and shape the tone. Engineers use it to make a vocal sit well in a mix.", "purpose_function": "It gives a vocal track the enhancement, de-essing, compression and EQ it usually needs in a single plug-in. Solid State Logic offers it to speed up common vocal processing with tools tuned for voices.", "practical_application": "A technician inserts Vocalstrip on a lead vocal, uses the de-esser to soften harsh 's' sounds, then adds compression and EQ for a polished sound.", "category": "SSL Channel Strip", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Drumstrip", "Channel Strip 2", "De-Esser", "Compressor", "Parametric EQ", "Sibilance"], "common_mistakes": ["Setting the de-esser too strong, which makes the singer sound like they have a lisp.", "Stacking heavy enhancement and EQ boosts, which makes the vocal harsh.", "Confusing the enhancers with plain EQ; they add harmonics, not just level."], "scenario_contexts": ["Polishing a lead vocal with de-essing, compression and EQ in one plug-in.", "Softening harsh sibilance on a bright vocal recording.", "Adding air and presence to a dull vocal without a separate enhancer."], "formula_symbolic": "", "formula_words": ""}, {"id": "70f6f224-7c23-4e02-8909-513b5770ccaf", "term": "X-Comp", "definition": "X-Comp is a Solid State Logic compressor plug-in from the X-series aimed at detailed and mastering-style dynamics control, with a graphic transfer-curve display and adjustable threshold, ratio, knee, attack and release plus additional curve-shaping controls. It is designed for precise, transparent-to-characterful gain control on individual tracks, buses and masters. Compression is a generic method; this design and the name are proprietary to Solid State Logic.", "plain_english": "X-Comp is a compressor plug-in from Solid State Logic. Solid State Logic owns the design. A compressor turns down the loudest parts to even out a sound. X-Comp shows the effect as a graph you can shape. Engineers use it for careful control on tracks, groups and whole mixes.", "purpose_function": "It reduces the dynamic range of a signal with fine control over how the compression curve behaves. Solid State Logic offers it for detailed, precise dynamics work from single tracks up to mastering.", "practical_application": "An engineer uses X-Comp on a mix bus, sets a soft knee and gentle ratio, and watches the transfer curve to dial in transparent level control.", "category": "SSL Dynamics", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["X-ValveComp", "Bus Compressor 2", "The Bus+", "Compressor", "Knee", "Ratio"], "common_mistakes": ["Using too high a ratio, which over-squashes and dulls the sound.", "Ignoring the knee control, so gentle compression sounds abrupt.", "Setting attack too fast on program material and losing punch."], "scenario_contexts": ["Applying transparent glue compression on a mix bus.", "Controlling peaks on a lead vocal with a soft knee.", "Shaping the compression curve visually during mastering."], "formula_symbolic": "", "formula_words": ""}, {"id": "008a39d0-9af6-417f-9213-9eafabc68f34", "term": "X-EQ 2", "definition": "X-EQ 2 is a Solid State Logic equaliser plug-in offering up to 24 bands per instance, each switchable across a total of 17 filter types (bell, shelf, cut and custom shapes), aimed at mixing and mastering. It applies SSL's anti-cramping algorithms to keep high-frequency curves accurate and transparent at no extra CPU cost. Parametric and shelving EQ are generic methods; this design and the name are proprietary to Solid State Logic.", "plain_english": "X-EQ 2 is a tone-control plug-in from Solid State Logic. Solid State Logic owns the design. An equaliser boosts or cuts chosen frequency ranges. X-EQ 2 gives up to 24 bands and many filter shapes. It is precise and clean, so engineers use it for mixing and mastering.", "purpose_function": "It boosts or cuts many chosen frequency bands with a wide choice of filter shapes for precise tone shaping. Solid State Logic offers it as a clean, flexible EQ for detailed mix and mastering work.", "practical_application": "A mastering engineer uses X-EQ 2 on a stereo mix, adds a gentle high shelf for air and a narrow cut to fix a resonant frequency.", "category": "SSL EQ", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["X-EQ Anti-Cramping", "E Series EQ", "G Series EQ", "Parametric EQ", "Shelving EQ", "SSL Native"], "common_mistakes": ["Adding many overlapping boosts, which builds up harshness and phase problems.", "Using very narrow cuts everywhere instead of fixing only real problem frequencies.", "Assuming all digital EQs match; standard designs can distort curves near the top of the range."], "scenario_contexts": ["Making broad tonal balance moves across a full mix during mastering.", "Cutting a narrow resonant frequency on a single instrument.", "Adding a clean high-shelf 'air' boost with accurate high-frequency response."], "formula_symbolic": "", "formula_words": ""}, {"id": "073e7bd0-a118-425e-8d14-2309fd1ca4fe", "term": "X-EQ Anti-Cramping", "definition": "X-EQ Anti-Cramping refers to the corrective algorithms in Solid State Logic's X-EQ 2 that counter 'cramping', the frequency-response error affecting standard digital equalisers as their curves approach the Nyquist frequency (half the sample rate), where boosts and cuts near the top of the audible band become distorted or pulled down. The anti-cramping design keeps high-frequency EQ curves accurate and transparent without added CPU cost. Cramping and its correction are general digital-EQ concepts; this named implementation is proprietary to Solid State Logic.", "plain_english": "Anti-cramping is a fix built into Solid State Logic's X-EQ 2. Solid State Logic owns this design. Many digital tone controls get inaccurate near the very top of hearing. Their high-frequency curves get squashed and wrong. Anti-cramping corrects this so high boosts and cuts stay clean and accurate.", "purpose_function": "It corrects the high-frequency curve errors that standard digital EQs show near the Nyquist limit, keeping treble EQ moves accurate. Solid State Logic includes it so X-EQ 2 stays clean and predictable at the top of the audible range.", "practical_application": "A mastering engineer trusts a high-shelf 'air' boost in X-EQ 2 to behave accurately near 20 kHz because the anti-cramping design corrects the response.", "category": "Digital EQ", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["X-EQ 2", "Nyquist Frequency", "Sample Rate", "Shelving EQ", "Parametric EQ", "Minimum-Phase EQ"], "common_mistakes": ["Thinking all digital EQs are identical near the top of the range; many suffer cramping.", "Confusing anti-cramping with oversampling; they address the response error differently.", "Assuming cramping is audible only as level, when it also distorts the curve shape."], "scenario_contexts": ["Making an accurate high-shelf boost near 20 kHz during mastering.", "Comparing X-EQ 2's high-frequency curve with a cramped standard digital EQ.", "Explaining to students why digital EQ curves can deviate near half the sample rate."], "formula_symbolic": "", "formula_words": ""}, {"id": "a6c6cb4e-ad58-48e6-a51c-b6b4d37d4508", "term": "X-Phase", "definition": "X-Phase is a Solid State Logic plug-in for manual phase and time alignment, combining an adjustable all-pass filter with a delay and a polarity (180-degree) invert. The all-pass filter shifts phase across frequency while keeping equal gain, letting an engineer align multi-microphone sources and reduce comb filtering without changing tone. All-pass phase correction is a generic method; this design and the name are proprietary to Solid State Logic.", "plain_english": "X-Phase is a plug-in that fixes phase and timing between signals. Solid State Logic owns the design. When two mics catch one sound, they can fight and thin it out. X-Phase shifts and delays one signal to line them up. It does this without changing the tone.", "purpose_function": "It aligns the phase and timing of related signals so multiple microphones on one source add up cleanly instead of cancelling. Solid State Logic offers it to fix comb filtering and improve punch and clarity.", "practical_application": "A technician uses X-Phase to align a snare top and bottom mic, adjusting the all-pass filter and delay until the drum sounds full instead of thin.", "category": "SSL Processing", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Comb Filtering", "Polarity", "All-Pass Filter", "Time Alignment", "Phase", "X-EQ 2"], "common_mistakes": ["Only flipping polarity and expecting full alignment; phase can differ across frequencies.", "Adjusting phase by ear without checking the summed result in mono.", "Assuming the all-pass filter changes tone; it changes phase, not gain."], "scenario_contexts": ["Aligning top and bottom snare drum microphones.", "Correcting phase between a bass DI and a mic'd bass amp.", "Reducing comb filtering between spaced microphones on one source."], "formula_symbolic": "", "formula_words": ""}, {"id": "6fb4cb58-06da-47c4-8860-9d009b03c436", "term": "X-Saturator", "definition": "X-Saturator is a Solid State Logic plug-in from the X-series that adds analogue-style saturation and harmonic distortion to a signal, generating extra harmonics to add warmth, weight or edge. It offers control over the amount and character of the added harmonics. Harmonic saturation is a generic method; this design and the name are proprietary to Solid State Logic.", "plain_english": "X-Saturator is a plug-in that adds warmth and grit. Solid State Logic owns the design. It adds gentle distortion, like running audio through analogue gear. This creates extra harmonics that thicken a sound. Engineers use it to make thin or clean tracks feel richer.", "purpose_function": "It adds harmonic content to a signal to give it warmth, richness or aggression that clean digital audio can lack. Solid State Logic offers it for analogue-style colour and weight on tracks and buses.", "practical_application": "A technician adds X-Saturator to a clean bass or synth to give it more body and harmonic richness so it cuts through the mix.", "category": "SSL Processing", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["X-ValveComp", "Harmonic Distortion", "Saturation", "Tape Emulation", "X-Comp", "SSL Native"], "common_mistakes": ["Adding too much saturation, which turns warmth into harsh distortion.", "Using it on a full mix without gain-matching, so louder just sounds better.", "Confusing saturation with EQ; it adds new harmonics, not just level changes."], "scenario_contexts": ["Warming up a clean DI bass so it feels fuller.", "Adding edge and harmonics to a soft synth pad.", "Giving a sterile digital drum bus some analogue-style grit."], "formula_symbolic": "", "formula_words": ""}, {"id": "0afcbd43-e59d-4525-9f2d-bac49153e867", "term": "X-ValveComp", "definition": "X-ValveComp is a Solid State Logic compressor plug-in from the X-series that emulates a valve (vacuum-tube) compressor, adding the smooth gain control and harmonic warmth associated with tube-based dynamics. It provides standard compressor controls plus valve-style character. Valve compression is a generic method; this design and the name are proprietary to Solid State Logic.", "plain_english": "X-ValveComp is a compressor plug-in from Solid State Logic. Solid State Logic owns the design. It copies an old-style compressor built with vacuum tubes, called valves. Tube compressors squeeze sound smoothly and add gentle warmth. Engineers use it when they want control plus a rich, musical colour.", "purpose_function": "It controls dynamics while adding the smooth response and harmonic warmth of a valve compressor. Solid State Logic offers it when an engineer wants character and colour along with level control.", "practical_application": "A technician puts X-ValveComp on a vocal or bass for smooth level control and a touch of tube warmth, rather than a clean, clinical squeeze.", "category": "SSL Dynamics", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["X-Comp", "X-Saturator", "Compressor", "Tube (Valve)", "Harmonic Distortion", "Bus Compressor 2"], "common_mistakes": ["Expecting fully transparent control; the valve model adds colour by design.", "Driving it too hard, which adds unwanted distortion instead of gentle warmth.", "Confusing valve character with a plain compressor and missing its tonal effect."], "scenario_contexts": ["Adding smooth, warm compression to a lead vocal.", "Thickening a bass with valve-style level control and colour.", "Choosing a coloured compressor over a clean one for a vintage feel."], "formula_symbolic": "", "formula_words": ""}, {"id": "308934b7-7aa9-48ae-b1d3-8a424a4794b8", "term": "Fusion", "definition": "Fusion is a 2U all-analog stereo outboard processor made by Solid State Logic (SSL) for the mix bus or master bus of a hybrid studio. It chains several coloration circuits, including Vintage Drive saturation, a Violet shelving EQ, a high-frequency compressor, a Stereo Image mid-side stage, and a switchable output transformer stage, to add analog character to a stereo mix.", "plain_english": "Fusion is an analog processing box built by Solid State Logic. It sits on the main stereo output of a mix. It runs several tone-shaping circuits in a row. Engineers use it to make a digital mix sound warmer and more like analog gear.", "purpose_function": "It exists to give a finished stereo mix analog warmth, harmonic color, width, and glue in one hardware unit rather than several separate boxes. Engineers reach for it to move a clean digital mix closer to a classic analog sound.", "practical_application": "A mix engineer patches Fusion across the stereo mix bus and dials in Vintage Drive, EQ, and the transformer stage while listening to the whole mix. It is typically used at mixdown or light mastering, not on single tracks.", "category": "Analog Bus Processor", "difficulty": "intermediate", "achievement_id": "646f6b48-1257-4dad-a655-a43e80023de0", "cross": [], "related_terms": ["Vintage Drive", "Fusion Stereo Image", "Fusion Transformer", "Master Bus", "Mid-Side Processing", "Harmonic Saturation"], "common_mistakes": ["Treating Fusion as a channel plug-in and using it on individual tracks instead of the stereo bus it is designed for.", "Pushing every circuit hard at once, which stacks distortion and harshness rather than subtle analog color.", "Confusing the analog hardware unit with the separate SSL Fusion plug-in emulations that model its circuits."], "scenario_contexts": ["Adding analog weight and glue to an in-the-box mix before delivery.", "Light stereo mastering of a mixdown to warm up an overly clean digital master.", "A hybrid studio routing the DAW mix bus out to Fusion and back for analog coloration."], "formula_symbolic": "", "formula_words": ""}, {"id": "01b4a0c8-75a1-421f-856a-b0ec079381d4", "term": "Fusion Stereo Image", "definition": "Fusion Stereo Image is the mid-side (M/S) processing stage of the SSL Fusion processor. Its Width control adjusts the level of the side (difference) signal to narrow or widen the stereo image, and its Space control applies a broad low-frequency boost or cut to the side signal to alter depth, a technique based on Alan Blumlein's stereo shuffling.", "plain_english": "This is the width-and-depth stage inside SSL's Fusion box. It splits the sound into a center part and a side part. The Width control changes how wide the stereo mix feels. The Space control adjusts the low bass in the side part to change the sense of depth.", "purpose_function": "It exists to widen or focus the stereo field and add a sense of space to a mix without harming mono compatibility. Engineers use it to open up a mix that feels narrow or crowded in the center.", "practical_application": "An engineer nudges Width up a few decibels to widen a mix and uses Space to add low-end spread, checking a phase display and mono sum as they go. It is applied across the stereo bus, not on a single track.", "category": "Stereo Imaging", "difficulty": "intermediate", "achievement_id": "646f6b48-1257-4dad-a655-a43e80023de0", "cross": [], "related_terms": ["Fusion", "Mid-Side Processing", "Stereo Width", "Mono Compatibility", "Phase", "Fusion Transformer"], "common_mistakes": ["Widening too far, which weakens the center image and collapses badly when the mix is played in mono.", "Not checking the mono sum after boosting the side signal, so phase problems go unnoticed.", "Assuming Width adds new stereo content; it only raises or lowers the existing side (difference) signal."], "scenario_contexts": ["Opening up a narrow mix so it feels wider on speakers and headphones.", "Adding low-frequency spaciousness to a stereo master while watching mono compatibility.", "Tightening an overly wide mix that loses punch when summed to mono."], "formula_symbolic": "", "formula_words": ""}, {"id": "7e7de466-bc38-44ee-bd3d-fb9258d27e02", "term": "Fusion Transformer", "definition": "Fusion Transformer is the switchable output transformer stage of the SSL Fusion processor, which routes the signal through a drive circuit and a pair of miniature 600-ohm 1:1 transformers. Engaging it adds subtle low-frequency saturation, gentle low-end weight, and a progressive high-frequency phase shift that SSL describes as analog sheen and sparkle.", "plain_english": "This is a switchable analog stage at the end of SSL's Fusion box. It sends the sound through real transformers, which are coils that color the tone. Turning it on thickens the low end a little. It also adds a soft sparkle and warmth on top, like classic analog gear.", "purpose_function": "It exists to impart the harmonic coloration and low-end weight of transformer-coupled analog equipment as a final tone-shaping stage. Engineers switch it in to make a clean digital mix sound more like it passed through vintage hardware.", "practical_application": "At mixdown an engineer engages the Transformer stage on the stereo bus and A/B tests it in and out to judge the added weight and high-end character. It is used as a subtle overall color, not a corrective tool.", "category": "Analog Coloration", "difficulty": "intermediate", "achievement_id": "646f6b48-1257-4dad-a655-a43e80023de0", "cross": [], "related_terms": ["Fusion", "Vintage Drive", "Harmonic Saturation", "Transformer", "Fusion Stereo Image", "Master Bus"], "common_mistakes": ["Expecting a dramatic change; the effect is subtle low-end thickening and gentle high-frequency character.", "Forgetting that it introduces a slight high-frequency phase shift by design, and blaming it on a fault.", "Using it to fix a thin mix instead of addressing arrangement or EQ first."], "scenario_contexts": ["Adding gentle analog weight and sheen to a digital master bus.", "A/B comparing a mix with and without the transformer stage during mixdown.", "Warming up an overly clean in-the-box mix as a final coloration step."], "formula_symbolic": "", "formula_words": ""}, {"id": "33da5dd0-6029-4f5e-af77-1f6d762caf3a", "term": "Vintage Drive", "definition": "Vintage Drive is the non-linear saturation circuit of the SSL Fusion processor, controlled by a Drive knob (1 to 11) that sets how hard the circuit is pushed and a Density knob that shapes the harmonic content. Lower Density settings emphasize even-order harmonics, while higher settings produce fewer harmonics overall but more prominent odd-order content, and the interaction also creates a soft-compression effect that rounds peaks and raises average level.", "plain_english": "Vintage Drive is the saturation stage inside SSL's Fusion box. The Drive knob decides how hard the circuit is pushed to add distortion. The Density knob changes the flavor of that distortion. It also softly rounds off peaks, which makes the mix sound a bit louder and thicker.", "purpose_function": "It exists to add analog-style harmonic saturation and gentle peak-rounding to a mix, increasing perceived loudness and warmth without a simple level boost. Engineers use it to thicken and add edge or density to a stereo mix.", "practical_application": "An engineer raises Drive on the stereo bus until the mix feels thicker, then sets Density to shape the harmonic tone from smooth even harmonics to grittier odd harmonics. Small amounts are used for subtle glue; higher settings add obvious edge.", "category": "Analog Saturation", "difficulty": "intermediate", "achievement_id": "646f6b48-1257-4dad-a655-a43e80023de0", "cross": [], "related_terms": ["Fusion", "Fusion Transformer", "Harmonic Saturation", "Soft Clipping", "Master Bus", "Perceived Loudness"], "common_mistakes": ["Pushing Drive too far so the whole mix becomes harsh and distorted instead of subtly thickened.", "Confusing the loudness gain from soft-compression with a clean volume increase, then over-compressing later.", "Ignoring Density and leaving the harmonic character wrong for the material."], "scenario_contexts": ["Adding subtle harmonic thickness and glue to a clean digital mix.", "Increasing perceived loudness of a mix through gentle peak-rounding rather than a fader boost.", "Dialing in obvious edge or grit on an aggressive rock or electronic mix."], "formula_symbolic": "", "formula_words": ""}, {"id": "5061561c-bb3f-4675-a387-e995c0cb54c2", "term": "SSL", "definition": "SSL is the trademarked abbreviation for Solid State Logic, a British manufacturer of professional audio mixing consoles and studio equipment. Engineers also use the name informally to mean the company's large-format in-line consoles and the sonic character of its VCA-based channel and stereo bus dynamics. SSL is a proprietary brand owned by Solid State Logic, part of the Audiotonix group since 2017.", "plain_english": "SSL is short for Solid State Logic. It is a British company that builds large mixing desks for recording studios. Engineers often say \"an SSL\" to mean one of these consoles. The name and its designs belong to Solid State Logic.", "purpose_function": "The SSL name identifies equipment made by Solid State Logic and, informally, a recognisable console signal character. It exists as a brand so studios and engineers can specify that gear or signal chain.", "practical_application": "A technician books or patches into an \"SSL room,\" recalls console settings with SSL Total Recall, or loads SSL-branded channel strips and plug-ins during a mix.", "category": "Brand / Manufacturer", "difficulty": "intermediate", "achievement_id": "681cb58c-4a8b-470d-b37c-f9d1ca124c01", "cross": [], "related_terms": ["Solid State Logic", "Mixing console", "VCA automation", "Bus compressor", "Total Recall", "In-line console"], "common_mistakes": ["Treating \"SSL\" as a generic console type rather than one specific company's trademarked brand.", "Assuming every \"SSL-style\" plug-in is made by Solid State Logic; many emulations come from other manufacturers.", "Confusing SSL in audio with the unrelated SSL/TLS internet security protocol that shares the same letters."], "scenario_contexts": ["A studio advertises an \"SSL 4000-series room\" to attract mixing engineers.", "An engineer recalls a previous session's console setup using SSL Total Recall before a mix revision.", "A producer asks for \"SSL bus compression\" on the mix bus to glue a drum group together."], "formula_symbolic": "", "formula_words": ""}, {"id": "5e10b2d3-a26e-4c7f-95fc-815afa6c4189", "term": "Solid State Logic", "definition": "Solid State Logic (SSL) is a British professional audio manufacturer founded in 1969 by Colin Sanders, based in Oxfordshire, England. It first made solid-state logic switching electronics for pipe organs, then became known for large-format recording and mixing consoles, beginning with the SL 4000 series. Its products and name are proprietary; the company has been part of the Audiotonix group since 2017.", "plain_english": "Solid State Logic is a British company, usually just called SSL. Colin Sanders started it in 1969. It first made electronics for church organs. Later it built famous large mixing desks used in top recording studios.", "purpose_function": "Solid State Logic designs and builds consoles, outboard processors and software for music, broadcast and film audio. Its SL 4000 console combined in-line channels, voltage-controlled-amplifier fader automation and a VCA stereo bus compressor, established techniques it packaged under proprietary names such as Total Recall.", "practical_application": "Technicians operate and maintain SSL consoles in studios, and reach for SSL channel strips, bus compressors and plug-ins when tracking and mixing.", "category": "Brand / Manufacturer", "difficulty": "intermediate", "achievement_id": "681cb58c-4a8b-470d-b37c-f9d1ca124c01", "cross": [], "related_terms": ["SSL", "Mixing console", "Bus compressor", "VCA automation", "Total Recall", "Recording studio"], "common_mistakes": ["Thinking SSL always made consoles; the company began by making switching electronics for pipe organs.", "Crediting SSL with inventing the VCA bus compressor or in-line console; these are generic techniques SSL refined and branded.", "Confusing Solid State Logic the company with \"solid-state,\" the general term for transistor-based electronics."], "scenario_contexts": ["A studio installs a Solid State Logic Duality console for hybrid analogue-and-DAW mixing.", "An engineer uses the SL 4000 stereo bus compressor to add \"glue\" to a mix.", "A maintenance technician services Total Recall and automation on a legacy SL 4000 G-series desk."], "formula_symbolic": "", "formula_words": ""}, {"id": "c71ada08-8e96-4709-890d-410e1dbeb479", "term": "UC1", "definition": "UC1 is a hardware plug-in control surface made by Solid State Logic, whose name is a trademark of that company. It gives dedicated knob-per-function control of SSL Native plug-ins such as Channel Strip 2 and Bus Compressor 2, and, via the SSL 360 Link utility, of third-party plug-ins. It connects to a computer over USB and works with the cross-platform SSL 360 software rather than passing any audio itself.", "plain_english": "The UC1 is a small control box for software mixing tools. It has real knobs for the equaliser and compressor settings on screen. It is made by a company called Solid State Logic. You turn the knobs instead of dragging with a mouse. It plugs into your computer with a USB cable.", "purpose_function": "It exists to give hands-on, knob-per-function control of on-screen channel-strip and bus-compressor plug-ins, replacing mouse editing with tactile encoders and a moving-coil gain-reduction meter. This speeds up mixing and lets an engineer adjust several parameters at once.", "practical_application": "A mixing engineer places the UC1 on the desk to tweak SSL Native EQ, dynamics and bus-compression settings by hand, and uses the 360 Link plug-in to bring third-party processors under the same physical controls.", "category": "Control Surface", "difficulty": "intermediate", "achievement_id": "285a21d4-9d43-4c4a-a93b-64bce7ca7d7d", "cross": [], "related_terms": ["UF8", "UF1", "SSL 360", "360 Link", "SSL Native Channel Strip 2", "Bus Compressor"], "common_mistakes": ["Assuming the UC1 is an audio interface; it has no audio inputs or outputs and only sends control data over USB.", "Confusing UC1 (a plug-in controller) with UF8 or UF1 (DAW control surfaces for transport, faders and mixing).", "Forgetting that third-party plug-in control needs the 360 Link host plug-in loaded, not just the UC1 hardware.", "Expecting it to run without the SSL 360 software, which manages the hardware and links the plug-ins."], "scenario_contexts": ["Fine-tuning an SSL Native Channel Strip 2 EQ curve with dedicated knobs during a mix.", "Watching the moving-coil meter while setting bus-compressor gain reduction on a mix bus.", "Loading 360 Link to control a third-party reverb from the UC1 surface.", "Adding a UC1 alongside a UF8 for combined DAW and plug-in control on a desktop rig."], "formula_symbolic": "", "formula_words": ""}, {"id": "0edcaaec-1fb2-4f86-805f-0b5e20343739", "term": "UF1", "definition": "UF1 is a single-fader DAW control surface made by Solid State Logic, whose name is a trademark of that company. It combines one motorised, touch-sensitive fader with a jog/scroll wheel, a colour display, rotary encoders and transport keys to control a digital audio workstation using industry-standard DAW control protocols. It connects over USB, is managed by the SSL 360 software, and can be daisy-chained with UF8 and UC1 units.", "plain_english": "The UF1 is a compact controller for music software. It has one motorised slider, a scroll wheel and a small screen. It lets you play, stop and mix your project by hand. The company Solid State Logic makes it. You can link it with their UF8 and UC1 units over USB.", "purpose_function": "It exists to give compact, hands-on transport and mixing control of a DAW from a small desktop footprint, so an engineer can play, stop, scrub and adjust tracks without reaching for the mouse. It bridges the larger UF8 surface and the plug-in-focused UC1.", "practical_application": "A producer keeps a UF1 beside the keyboard to run transport, scrub with the jog wheel and ride a fader, and chains it to a UF8 or UC1 when more channels or plug-in control are needed.", "category": "Control Surface", "difficulty": "intermediate", "achievement_id": "285a21d4-9d43-4c4a-a93b-64bce7ca7d7d", "cross": [], "related_terms": ["UF8", "UC1", "SSL 360", "Motorised Fader", "Jog Wheel", "Mackie Control (MCU)"], "common_mistakes": ["Assuming the UF1 is an audio interface; it carries control data over USB and has no audio inputs or outputs.", "Confusing the UF1 (DAW control) with the UC1 (plug-in control), which do different jobs.", "Forgetting to select the correct DAW profile in SSL 360, so the controls map to the wrong functions.", "Thinking the motorised fader passes audio; it sends and shows automation levels only."], "scenario_contexts": ["Using the jog wheel to scrub to an exact edit point while comping vocals.", "Running transport and marker keys during a mix session from a small desk.", "Chaining a UF1 to a UF8 over USB to expand from one fader to nine.", "Riding a single track fader for a level automation pass."], "formula_symbolic": "", "formula_words": ""}]$ap$::jsonb)),
elig AS (SELECT r FROM p
  WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id=(r->>'id')::uuid)
    AND NOT EXISTS (SELECT 1 FROM glossary g WHERE g.term=r->>'term')),
g AS (
  INSERT INTO glossary (id, term, definition, plain_english, purpose_function, practical_application,
     category, difficulty, related_terms, common_mistakes, scenario_contexts, formula_symbolic, formula_words, achievement_id)
  SELECT (r->>'id')::uuid, r->>'term', r->>'definition',
     NULLIF(r->>'plain_english',''), NULLIF(r->>'purpose_function',''), NULLIF(r->>'practical_application',''),
     NULLIF(r->>'category',''), NULLIF(r->>'difficulty',''),
     ARRAY(SELECT jsonb_array_elements_text(r->'related_terms')),
     ARRAY(SELECT jsonb_array_elements_text(r->'common_mistakes')),
     ARRAY(SELECT jsonb_array_elements_text(r->'scenario_contexts')),
     NULLIF(r->>'formula_symbolic',''), NULLIF(r->>'formula_words',''), (r->>'achievement_id')::uuid
  FROM elig ON CONFLICT (id) DO NOTHING RETURNING 1
),
tp AS (
  INSERT INTO glossary_topics (glossary_id, achievement_id, is_primary, difficulty)
  SELECT (r->>'id')::uuid, (r->>'achievement_id')::uuid, true, NULLIF(r->>'difficulty','')
  FROM elig WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id=(r->>'id')::uuid AND gt.achievement_id=(r->>'achievement_id')::uuid)
  RETURNING 1
)
INSERT INTO glossary_topics (glossary_id, achievement_id, is_primary, difficulty)
SELECT (r->>'id')::uuid, ct::uuid, false, NULLIF(r->>'difficulty','')
FROM elig, jsonb_array_elements_text(r->'cross') ct
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id=(r->>'id')::uuid AND gt.achievement_id=ct::uuid);
COMMIT;
